window.RECIPE_INDEX = {"count":73,"recipes":[{"id":"4-ingredient-vegan-date-caramel-sauce","title":"4-Ingredient Vegan Date Caramel Sauce","description":"","image":"images/4_ingredient_vegan_date_caramel_sauce_uy5y4.jpg","servings":"8 -10","categories":[],"source":{"label":"https://plantbasedonabudget.com/homemade-caramel-sauce/","url":"https://plantbasedonabudget.com/homemade-caramel-sauce/"},"editPath":"data/recipes-md/4-ingredient-vegan-date-caramel-sauce.md","ingredientCount":5,"stepCount":3,"search":"4-ingredient vegan date caramel sauce  8 -10  10 medjool dates 1⁄2 cup full-fat coconut milk from a can 4 tablespoons maple syrup 1⁄4 teaspoon cinnamon 4 tablespoons reserved water from the dates fill a saucepan with water just enough to cover the dates. gently boil dates for 10 minutes. drain, reserving 4 tablespoons of the water. let sit until cool to the touch. peel and pit the dates. chop the dates and toss them in a blender with the full-fat coconut milk, maple syrup, cinnamon, and reserved water. blend until super smooth, about 2 or 3 minutes. pour the sauce back into the saucepan and bring to a boil, then simmer for about 5 minutes, or until it thickens. optional add-ins and variations: sea salt: a pinch of salt will enhance all the flavors in the vegan caramel sauce. add more, and you have yourself delicious vegan salted caramel. vanilla extract: a few drops of natural vanilla extract tastes fantastic in this healthy vegan caramel recipe. caramel extract: to further enhance the caramel flavor, add a few drops of natural caramel extract. coconut oil: for super silky caramel, swap out the reserved water for melted coconut oil. nut/seed butter: for an even more decadent non-dairy caramel, you could add a tablespoon of your favorite nut butter or seed butter. we recommend using tahini, cashew butter, almond butter, or sunflower seed butter. peanut butter is a little too strong in the vegan date caramel. https://plantbasedonabudget.com/homemade-caramel-sauce/"},{"id":"a-recipe-for-brioche-with-raisins-not-yet-tried-read","title":"A Recipe for Brioche with Raisins--not yet tried/read","description":"","image":"images/read_acci7.jpg","servings":"","categories":[],"source":{"label":"https://www.moroccoworldnews.com/2013/05/92644/moroccan-pastry-a-recipe-for-brioche-with-raisins-2","url":"https://www.moroccoworldnews.com/2013/05/92644/moroccan-pastry-a-recipe-for-brioche-with-raisins-2"},"editPath":"data/recipes-md/a-recipe-for-brioche-with-raisins-not-yet-tried-read.md","ingredientCount":13,"stepCount":15,"search":"a recipe for brioche with raisins--not yet tried/read    for the dough: 500g white flour. 50g butter. 1 egg. 60g sugar. 2 tbsp powder milk. 15g baking yeast. 1 baking powder. for the custard ( crème patissiére): 2 cups milk. 1 egg. 2 tbsp sugar. 1tsp vanilla. 20g flour or cornflower (cornstarch). 100g raisin for garnish. way of preparation: the dough: in a big bowl, put the dry ingredients then add butter and mix well. add an egg and warm water little by little then knead well until the dough is smooth and cohesive. let the dough rest for an hour in the refrigerator. (it’s better to keep it in the fridge for the whole night) you can use puff pastry. the custard: mix an egg with sugar, vanilla and cornflower. in a saucepan, boil milk then add it to the first mixture and mix well. put the mixture on a low heat and keep stirring until we get a thick cream. put the cream in refrigerator. make two balls from the dough and flatten them with a rolling pin. spread custard on the surface and sprinkle raisins on the top then roll the dough. cut the rolling dough into circles (you can put the rolling dough in the freezer for an hour to keep its shape while cutting) place brioche in an oven tray and brash them with a whipped egg then sprinkle some almonds flakes or ground almonds on the top. (optional) bake it in a pre heated oven for 25 to 30 minutes. after baking you can brush the brioche with jam. serve with tea!  https://www.moroccoworldnews.com/2013/05/92644/moroccan-pastry-a-recipe-for-brioche-with-raisins-2"},{"id":"all-around-seasoning-mix","title":"All-Around Seasoning Mix","description":"","image":"images/all_around_seasoning_mix_6m1hz.jpg","servings":"","categories":[],"source":{"label":"https://www.tasteofhome.com/recipes/all-around-seasoning-mix/","url":"https://www.tasteofhome.com/recipes/all-around-seasoning-mix/"},"editPath":"data/recipes-md/all-around-seasoning-mix.md","ingredientCount":11,"stepCount":1,"search":"all-around seasoning mix    1/2 cup paprika 3 tablespoons onion powder 3 tablespoons garlic powder 3 tablespoons cayenne pepper 2 tablespoons white pepper 2 tablespoons pepper 4 teaspoons salt 4 teaspoons dried thyme 4 teaspoons dried oregano 4 teaspoons ground cumin 4 teaspoons chili powder in a small bowl, combine all ingredients. store in an airtight container in a cool, dry place for up to 6 months. all-purpose seasoning tips what is all-purpose seasoning? https://www.tasteofhome.com/recipes/all-around-seasoning-mix/"},{"id":"almond-crescent-cookies","title":"Almond Crescent Cookies","description":"","image":"","servings":"","categories":[],"source":{"label":"","url":""},"editPath":"data/recipes-md/almond-crescent-cookies.md","ingredientCount":8,"stepCount":1,"search":"almond crescent cookies    all purposes flour 2 cups +2 tbs roasted crushed almond 1 cup 180 g butter + shortening (90g each) powdered sugar 4 tbsp vanilla 1 tbsp baking powder 1tbsp 1 egg salt whisk vanillin sugar, flour, crushed almonds, baking powder, salt\nadd in butter + shortening with hands\nadd in egg with hands\nroll out and cut\nbake ~ 8-11 minutes  "},{"id":"anko","title":"Anko","description":"","image":"","servings":"","categories":[],"source":{"label":"","url":""},"editPath":"data/recipes-md/anko.md","ingredientCount":7,"stepCount":1,"search":"anko    400g bean 360g sugar half stick butter tablespoon of molasses tablespoon of corn syrup w/ vanilla teaspoon of salt teaspoon of pectin rinse beans or soak\nuse good water for first \"brew/boil\"\ncover beans with good water in pot\nbring to boil, reduce heat for 10minutes (or until water turns tea coloured)\nstrain off water for tea, add sugar\nadd beans back into pot, cover with an inch of water\nbring to boil, reduce heat, simmer 40 minutes- 2 hours until beans tender to when mashing\nstrain beans through sieve with warmish water, let settle and then do again after pouring off excess liquid/water  "},{"id":"banana-with-carrot-bread","title":"Banana (with carrot) Bread","description":"banana bread with crushed candied walnuts, candied shredded carrot, topped with chopped pecans","image":"","servings":"","categories":[],"source":{"label":"","url":""},"editPath":"data/recipes-md/banana-with-carrot-bread.md","ingredientCount":15,"stepCount":5,"search":"banana (with carrot) bread banana bread with crushed candied walnuts, candied shredded carrot, topped with chopped pecans   3 ripe bananas 2 cups all-purpose flour 1 tsp salt 1 tsp baking powder 1 tsp baking soda 2 tbs hemp hearts 2tbs wheat germ 1/2 cup soft butter 3/4 cup sugar \u0026 molasses +1/4-1/2 cup sugar for nuts 2 large eggs 1/4 tsp vanilla/some vanilla bean 1 tbsp milk/milk powder 1 cup chopped walnuts 1 cup shredded carrots chopped pecans candied walnuts\n1 cup chopped walnuts\n2-3 tbs butter\n1/4-1/2 cup white sugar\ndash salt\nsome water\ncook low-med heat for a few minutes, lay out on parchment candied shredded carrots\n1-3 tbs butter\n1/4-1/2 cup white sugar\ndash salt\nsome molasses\nsome water\n(forgot to add) dash cinnamon whisk flour, baking soda, baking powder, salt, hemp hearts, \u0026 wheat germ, set aside\nmash bananas, set aside\ncream soft butter with sugar using spatula\nadd banana mash to butter mix and whisk until combined\nadd eggs, 1 at a time\nadd vanilla \u0026 milk\nadd candied carrots \u0026 candied walnuts\nadd flour, mix with spatula gently, lightly folding spray loaf pan(s)\nfill (used small loaf trays) 1/2-3/4 of the way\nsprinkle with chopped pecans bake at 350f for 15 minutes\nlower temperature to 325f for about 10 minutes or until center of bread reads 200f  "},{"id":"banana-cake","title":"Banana Cake","description":"Recipe by (Betty) Lynette Meeks","image":"","servings":"","categories":[],"source":{"label":"","url":""},"editPath":"data/recipes-md/banana-cake.md","ingredientCount":15,"stepCount":3,"search":"banana cake recipe by (betty) lynette meeks   3/4 cup butter/shortening (half and half) 2.5 cups sugar 3 eggs 1.5 cups mashed bananas 3 cups sifted flour (half cake half all purpose) 3/4 tsp baking powder 1/3 cup buttermilk 1 tsp baking soda 1 tsp salt 1.5 tsp vanilla for frosting 1.5 box (cups?) (~ half a bag) (bag = 2lb or 907g) powdered sugar 3/4 cup (1.5 sticks) butter 3/4 cup mashed bananas 1.5 tsp lemon juice cream together shortening, butter, and sugar, blending well.\nadd well beaten eggs and bananas, beat well\nsift flours then resift with dry ingredients\nadd dry alternatively with wet mixture of buttermilk and vanilla combined in greased, floured pans bake at 350f for about 25 minutes or until done\nremove from pan and cool for frosting\ncream all ingredients together\nspread onto cooled cake  "},{"id":"biscuits","title":"Biscuits","description":"","image":"images/biscuits_o0yew.jpg","servings":"","categories":[],"source":{"label":"","url":""},"editPath":"data/recipes-md/biscuits.md","ingredientCount":18,"stepCount":15,"search":"biscuits    parts: 1) tangzhong mix 2) biscuit mix 3) buttermilk biscuit top-wash 1) tangzhong mix: 2 tablespoons bread flour 2 tablespoons water 4 tablespoons whole milk (or: 1 1/3 tbsp of dry milk + 8 tablespoons of water) 2) biscuit mix: 1 cup of all purpose flour 1 cup of bread flour 1 tbsp baking powder 1/2 tsp baking soda 3/4 tsp salt 1/2 package of instant rapid rise yeast 1 tbsp sugar 5tbsp of unsalted butter, very cold 1/4 cup of dry cultured buttermilk 1 cup of water cooked, room temperature tangzhong 3) buttermilk biscuit top-wash: butter (1tbsp) and buttermilk (from dry, totaling about 1/3 cup) for brushing top of biscuits before placing into oven instructions: •empty the ingredients for tangzhong mix into a frying pan. •cook, stirring constantly until looks like sticky mashed potatoes (about 1min@ medium heat). •let cooked tangzhong sit to room temperature •meanwhile in a separate bowl, combining the dry ingredients of the biscuit mix. •add cooked and cool tangzhong to dry biscuit mix, along with five tablespoons of cut unsalted butter, and 1 cup of cool water. •sit to rise at leas 1-2 hours after lightly folding •mix gently, basic incorporation. do not over knead or overmix. •put mix on floured surface, gently fold into layers for about 5 minutes •cut into 3” biscuits about 1/2” to 1” desired thickness (1” preferable). •let rise 1 hour •after biscuits are cut, let rise at room temperature for one hour, then chill for at least 15 minutes. •for best biscuits -- prior to folding, cutting and rise; let dough rise in refrigerator for at least 4 days. •cover dough with 2-3tbsp melted butter before refrigeration and keep dough airtight. •brush tops with buttermilk top-wash before putting in oven. •bake @ 400f for around 5-10 minutes until tops are golden crispy  "},{"id":"blueberry-muffins","title":"blueberry muffins","description":"by Sugar Spun Run","image":"","servings":"","categories":[],"source":{"label":"","url":""},"editPath":"data/recipes-md/blueberry-muffins.md","ingredientCount":13,"stepCount":12,"search":"blueberry muffins by sugar spun run   ▢1 3⁄4 cup all-purpose flour (220g) ▢1 cup granulated sugar (100-200g)(less) ▢2 tablespoons cornstarch ▢2 teaspoons baking powder ▢1⁄2 teaspoon baking soda ▢1⁄2 teaspoon salt ▢1⁄4 cup unsalted butter melted (60ml) ▢1⁄4 cup canola oil (60ml)(1/2 avocado 1/2 veg oil) ▢1 large egg room temperature preferred ▢1 teaspoon vanilla extract ▢1 cup sour cream (240g) ▢1 3⁄4 cup blueberries (245g) (fresh or frozen will work, if using frozen you do not need to thaw first, and note that they may leave purple streaks through your muffins). ▢coarse sugar for sprinkling optional (may just use regular granulated sugar or omit entirely). instructions for air fryer preheat oven to 400f and line a 12 count muffin tin with paper liners. in a medium-sized bowl, whisk together flour, sugar, baking powder, baking soda, cornstarch, salt. in a separate bowl whisk together butter and canola oil. add egg and vanilla.\nstir in sour cream until thoroughly combined. add wet ingredients to dry and gently fold together with a spatula until mostly combined.\nonce the batter is about 75% combined, add the blueberries and fold them in as well until batter is completely combined (don’t over-mix!). evenly divide muffin batter into prepared tin/silicon liner. liners will be most of the way full!\ntop with streusel topping or thick sugar transfer to 400f (215c) preheated oven and bake for 5 minutes. after 5 minutes reduce the oven temperature to 310f (175c) without opening oven door,\nthen continue baking 8-10 minutes (or until the tops are beginning to turn golden brown and a toothpick inserted in the center comes out clean or with a few moist crumbs) allow to cool 10 minutes and allow to cool completely on a cooling rack (otherwise muffin bottoms may become soggy).\nenjoy! streusel (use half this for whole recipe) ▢1⁄2 cup all-purpose flour (60g)\n▢1⁄2 cup granulated sugar (100g)\n▢1⁄4 cup unsalted butter (56g)\n▢1 pinch salt  "},{"id":"bonnie-s-my-complete-seasoning-spice-mix","title":"Bonnie's My Complete Seasoning Spice Mix","description":"","image":"images/bonnie39s_my_complete_seasoning_spice_mi_htiss.jpg","servings":"","categories":[],"source":{"label":"https://www.justapinch.com/recipes/sauce-spread/marinade/my-complete-seasoning.html","url":"https://www.justapinch.com/recipes/sauce-spread/marinade/my-complete-seasoning.html"},"editPath":"data/recipes-md/bonnie-s-my-complete-seasoning-spice-mix.md","ingredientCount":9,"stepCount":1,"search":"bonnie's my complete seasoning spice mix    3 tablespoons salt 1 tablespoon paprika 1 tablespoon onion powder 1 tablespoon garlic powder 1/2 tablespoon white pepper 1 1/2 teaspoon ground thyme 3/4 teaspoon black pepper 1/2 teaspoon ground oregano optional: 1 tablespoon cayenne for latin dishes -  https://www.justapinch.com/recipes/sauce-spread/marinade/my-complete-seasoning.html"},{"id":"brioche","title":"Brioche","description":"","image":"images/brioche_xpvra.jpg","servings":"","categories":[],"source":{"label":"","url":""},"editPath":"data/recipes-md/brioche.md","ingredientCount":16,"stepCount":5,"search":"brioche    poolish (150g bread flour + 150g water + pinch yeast) tangzhong (2 tbs water, 4 tbs milk, 2 tbs bread flour) 125ml milk 20ml water 10g bread machine yeast 1 large egg 1 egg yolk 375g bread flour 7g salt 4g amylase 60g sugar 50g softened butter 50g butter flavored shortening melted butter triple-seed-topping (hemp hearts, wheat germ, black seeds) flakey salt combine water and milk in a small bowl, whisk in yeast to dissolve, place in a stand mixer bowl along with the whole egg and egg yolk; and the tangzhong and ripened poolish; mix on low speed, until combined. in a separate bowl, mix flour, sugar, salt, and amylase.\nwhile mixing (by hand or stand mixer), add in your flour mixture, 1⁄4 cup at a time, until all of your flour has been added. once it begins to form a rough dough, allow to knead for 2 minutes or until it begins to turn smooth.\nthen add your butter, allow to mix until fully incorporated, and knead for 5-10 more minutes or till your dough is very smooth and begins to pull from the sides of the bowl. cover with plastic wrap and rise for 45 minutes at room temperature. then place in the fridge for 1.5 hours and up to overnight. separated into 94g portions, let rise for an hour at room temperature.\nspray with pam, brush with egg wash + top with black seed.\nthen bake @ 375f (maybe start at 380-385f at first) until golden brown.\nimmediately top with melted butter and flakey salt.  "},{"id":"buttery-chewy-sugar-cookies","title":"Buttery Chewy Sugar Cookies","description":"from handletheheat.com","image":"","servings":"","categories":[],"source":{"label":"","url":""},"editPath":"data/recipes-md/buttery-chewy-sugar-cookies.md","ingredientCount":7,"stepCount":3,"search":"buttery chewy sugar cookies from handletheheat.com   21⁄2 cups (318 grams) all-purpose flour 2 teaspoons baking powder 3/4 teaspoon fine sea salt 2 sticks (226 grams) unsalted butter, at cool room temperature 11⁄4 cups (250 grams) granulated sugar, plus 1⁄4 cup (50 grams) for rolling 1 large egg plus 1 egg yolk 1 teaspoon vanilla extract preheat the oven to 350°f(may need to be lowered halfway to 340f).\nline baking sheets with parchment paper.\nin a medium bowl, whisk together the flour, baking powder, and salt to combine.\nin a large bowl, use an electric mixer fitted with a paddle attachment on medium-high speed to beat the butter and 11⁄4 cups sugar until light and fluffy, 2 to 3 minutes. add the egg, egg yolk, and vanilla, and beat until combined. slowly beat in the flour mixture. place the remaining 1/4 cup sugar in a shallow dish. using a large (3-tablespoon) (or just small cookies) spring-loaded scoop, divide the dough into balls, then roll in sugar to coat evenly. place the dough balls on the prepared baking sheets, spacing 2 inches apart, and flatten slightly with the bottom of a measuring cup. bake for 10 to 12 minutes, or until the cookies set and begin to brown. cool for 5 minutes before removing to a wire rack to cool completely. cookies can be stored in an airtight container at room temperature for up to 3 days.  "},{"id":"cajun-chicken","title":"Cajun chicken","description":"","image":"","servings":"","categories":[],"source":{"label":"","url":""},"editPath":"data/recipes-md/cajun-chicken.md","ingredientCount":17,"stepCount":1,"search":"cajun chicken    works for 2.5 lbs use salt to make tender marinade: 1 cup buttermilk 1 teaspoon herbs de province 1tablespoon garlic 1 teaspoon cajun (walmart brand square) flour mix: 1.25 cup all purpose flour 4 tablespoons panko 4 tablespoons corn starch or 1.75 cup rice flour flour seasoning: 1 teaspoon baking powder 1 teaspoon sugar pinch white pepper 1/2 teaspoon onion powder 1 tablespoon+ 1 teaspoon cajun 1/2 teaspoon parsley -  "},{"id":"cheese-danish","title":"Cheese Danish","description":"","image":"images/cheese_danish_b9cno.jpg","servings":"9 pastries","categories":[],"source":{"label":"https://cooking.nytimes.com/recipes/1017898-cheese-danish","url":"https://cooking.nytimes.com/recipes/1017898-cheese-danish"},"editPath":"data/recipes-md/cheese-danish.md","ingredientCount":8,"stepCount":5,"search":"cheese danish  9 pastries  8 ounces/226 grams cream cheese 1 1⁄4 cup/160 grams confectioners’ sugar 1 large egg yolk pinch of salt 1⁄2 teaspoon pure vanilla extract 1 batch danish dough ( see recipe) 1 large egg, lightly beaten 2 tablespoons/30 milliliters whole milk in a large bowl, beat together the cream cheese, 1/4 cup/32 grams confectioners’ sugar, the egg yolk, the salt and the vanilla until smooth. transfer the mixture to a resealable plastic bag; set aside. on a lightly floured surface, roll the dough out into a 12 1/2-inch square. trim 1/4 inch off each edge. cut the dough into nine 4-inch squares. brush the corners of each square with a bit of the beaten egg, then fold each corner into the center and press down gently. transfer the squares to 2 parchment-lined baking sheets. cut the tip off one corner of the filled plastic bag so you have a 1/2-inch hole. use the bag to pipe the cheese filling onto the center of each dough square. loosely cover the pastries with plastic wrap and let stand until slightly puffed, about 1 hour to 1 hour 20 minutes. heat oven to 425 degrees. remove the plastic and gently brush the top and sides of the dough with the beaten egg. bake for 10 minutes, then rotate the sheets and reduce oven temperature to 375 degrees. continue to bake until pastries are puffed and deep golden brown, another 6 to 8 minutes. meanwhile, whisk together the remaining 1 cup/128 grams confectioners’ sugar and the milk. let the danish cool slightly on the sheet then drizzle with the glaze. serve warm or at room temperature.  https://cooking.nytimes.com/recipes/1017898-cheese-danish"},{"id":"chicken-and-dumplings","title":"Chicken and Dumplings","description":"","image":"","servings":"large crock pot","categories":[],"source":{"label":"","url":""},"editPath":"data/recipes-md/chicken-and-dumplings.md","ingredientCount":11,"stepCount":1,"search":"chicken and dumplings  large crock pot  large condensed cream of chicken 14 chicken tenderloins 1 cup flour 1 cup self-rising flour (1 cup all purpose flour, 1.5 tsp baking powder, 1/4 tsp salt) 1 cup ice water 1 tbsp olive oil 5-6 carrots some radishes msg 1/3 stick butter optional lima beans on side??/succotash?/corn \u0026 lima bean? coat chicken in chicken bouillon while sitting out at room temp\nplace chicken in crock pot on high\nadd can of cream of chicken (large)\nmix self-rising flour, all-purpose flour, cooking oil, and cold water (very sticky dough)\nplace on surface coated in extra flour and work flour into dough until handleable\nroll out and cut with pizza cutter into dumplings\nboil\nadd dumplings to chicken\nusing same water from dumplings, boil sliced/chopped carrots until soft\nadd carrots to crock pot\nmake a roux with flour, water, and stock from crock pot\nadd roux to crock pot once all lumps are gone and flour is cooked\nadd extra water to crock pot if needed\nstir together and let sit on low for 30-45 minutes?\nadd msg\nadd butter if you want\nnutritional yeast\npeas?  "},{"id":"chicken-pinto-burrito","title":"chicken pinto burrito","description":"","image":"","servings":"","categories":[],"source":{"label":"","url":""},"editPath":"data/recipes-md/chicken-pinto-burrito.md","ingredientCount":22,"stepCount":5,"search":"chicken pinto burrito    2 boneless skinless chicken thighs (or breast) 1 tbsp (14 grams) mayo coarse kosher salt 2 cloves garlic, crushed lime zest 1/2 juice lime chile powder mexican oregano (optional) 10 cranks of black pepper pinto beans drizzle of oil jalapeno, diced sprinkle of whole cumin seeds 1 can pinto beans, drained salt to taste burrito accoutrements sour cream thinly sliced lettuce pickled onions queso fresco hot sauce cilantro set a cast-iron pan over medium heat. mix the mayo and spices into a bowl. add the chicken and slather the marinade on the exterior. add the chicken to the pan and brown on each side, about 3-4 minutes per side. cook until the internal temp is 160. slice and enjoy. drizzle oil into a pan over medium-low heat. add diced jalapeno and cumin seeds and cook until just fragrant, about 1 minute. add the pintos and cook, while stirring for another 4-5 minutes. spread a thin layer of sour cream on the bottom which will act as a glue for the beans and provide even coverage of the sour cream instead of getting large gloops everywhere. for rolling purposes, i find it best to position the fillings in the upper third. first, hit it with a layer of the seasoned beans. now here is where i like to add hot sauce as an acidic layer. follow this with a generous helping of the chicken then a sprinkle of queso fresco, the diced tomatoes minced cilantro, some shredded lettuce, and you better not forget the pickled onions. check the video for how to roll!  "},{"id":"choc-cobbler","title":"choc cobbler","description":"","image":"","servings":"","categories":[],"source":{"label":"","url":""},"editPath":"data/recipes-md/choc-cobbler.md","ingredientCount":11,"stepCount":4,"search":"choc cobbler    4 tablespoons butter 80g flour 1tsp baking powder pinch of salt 100g white sugar 1 tablespoons unsweetened cocoa powder 1/3 cup milk 1 teaspoon vanilla extract 135g white sugar 1/6 cup unsweetened cocoa powder 1 cups boiling water preheat the oven to 350 degrees f (175 degrees c). melt butter in an 8x8 inch baking dish while the oven preheats. in a medium bowl, stir together the flour, baking powder, 100g sugar, and 1 tablespoons cocoa.\nstir in milk and vanilla until smooth. spoon this batter over the melted butter in the baking dish. stir together the remaining 135g of sugar and 1/6 cup cocoa powder. sprinkle over the batter.\nslowly pour boiling water over the top of the mixture. bake for 30 minutes in the preheated oven, until set.  "},{"id":"chocolate-cake","title":"chocolate cake","description":"","image":"","servings":"","categories":[],"source":{"label":"","url":""},"editPath":"data/recipes-md/chocolate-cake.md","ingredientCount":1,"stepCount":1,"search":"chocolate cake    - -  "},{"id":"chocolate-glaze","title":"chocolate glaze","description":"for donuts etc","image":"","servings":"","categories":[],"source":{"label":"","url":""},"editPath":"data/recipes-md/chocolate-glaze.md","ingredientCount":8,"stepCount":1,"search":"chocolate glaze for donuts etc   1 tbs butter 2 tbs shortening 2 tbs cocoa 2 tbs hot water + 1/2 tsp vanillin sugar 1 tsp milk powder 1 cup powdered sugar for donuts add more powdered sugar + try corn syrup melt butter + shortening\nmix in rest may have to heat up and whisk to get proper consistency "},{"id":"cinnabon-cinnamon-rolls-but-better","title":"Cinnabon Cinnamon Rolls (But Better)","description":"","image":"","servings":"","categories":[],"source":{"label":"https://www.joshuaweissman.com/post/cinnabon-cinnamon-rolls-but-better","url":"https://www.joshuaweissman.com/post/cinnabon-cinnamon-rolls-but-better"},"editPath":"data/recipes-md/cinnabon-cinnamon-rolls-but-better.md","ingredientCount":17,"stepCount":13,"search":"cinnabon cinnamon rolls (but better)    dough: 4 cups (580g) all-purpose flour 1/2 cup (107g) granulated sugar 3/4 tsp (6g) fine sea salt 1/3 cup (84g) butter (or half butter flavored crisco) 1 cup (235g) lukewarm whole milk 21/4 tsp (7g ) instant yeast 2 eggs 1 egg yolk 4-5g amylase filling: 1 cup (225g) brown sugar 1 tbsp (14g) muscovado sugar 2.5 tbsp (17g) cinnamon 1/3 cup (84g) butter vanilla bean cream cheese glaze: 4 oz (115g) cream cheese 3/4 (90g) cups powdered sugar 1 vanilla bean 3 tbsp (45ml) whole milk in a stand mixer bowl, whisk together all-purpose flour, granulated sugar, amylase, and fine sea salt. add in softened unsalted butter. blend in using two forks. in a separate container, whisk together lukewarm whole milk and instant yeast. using the dough hook attachment set on medium-low speed, add in yeast mixture, whole eggs, and egg yolk. mix for 2-3 minutes. on a lightly floured work surface and knead for 30-60 seconds. plop into a greased bowl and cover with plastic wrap, let rise for 90 minutes. once dough is ready, mix together brown sugar, muscovado sugar, and cinnamon. dump dough out onto a lightly floured surface flattening it into a large rectangle. spread softened unsalted butter across the whole rectangle then sprinkle the cinnamon sugar evenly across the whole dough. tightly roll from the bottom all the way to the top. slice into 2” thick segments grease a 9x13 baking dish, line the bottom of the pan the rolls and cover with plastic wrap once filled. let rise at room temperature for 30-45 minutes. bake in a 375f preheated oven for 15-20 minutes. let cool in the container for 15 minutes. for the filling, beat together cream cheese then blend in powdered sugar until smooth. whisk in whole milk until smooth then add in half scraped vanilla bean and whisk together. drizzle the glaze on top of the cinnamon rolls and serve.  https://www.joshuaweissman.com/post/cinnabon-cinnamon-rolls-but-better"},{"id":"cinnamon-roll-sauce","title":"Cinnamon Roll Sauce","description":"","image":"","servings":"","categories":[],"source":{"label":"","url":""},"editPath":"data/recipes-md/cinnamon-roll-sauce.md","ingredientCount":4,"stepCount":1,"search":"cinnamon roll sauce    1/2c butter 1/2c sugar some water molasses -  "},{"id":"cucumber-avocado-salad","title":"cucumber avocado salad","description":"","image":"","servings":"","categories":[],"source":{"label":"","url":""},"editPath":"data/recipes-md/cucumber-avocado-salad.md","ingredientCount":7,"stepCount":1,"search":"cucumber avocado salad    - 1 normal cucumber or 2 smaller ones - 2 smaller avocados - 1/4 to 1/2 a carrot, thinly julienned - 2 tbs or so of lemon juice - salt \u0026 pepper - 2 scallions red pepper flakes, everything bagel seasoning sliced thinly the scallions-- add to ice water\npeel and chop cucumber, place in bowl with salt 5-15 minutes\ndrain cucumbers\nchop avocado, mix with lemon juice, salt \u0026 pepper, \u0026 julienned carrots\ndrain scallions\nadd all together and stir\nadd everything bagel seasoning and red pepper flakes  "},{"id":"custard-buns","title":"Custard Buns","description":"","image":"","servings":"","categories":[],"source":{"label":"","url":""},"editPath":"data/recipes-md/custard-buns.md","ingredientCount":38,"stepCount":2,"search":"custard buns    ingredients: preparing the custard 500ml (2 cups) milk 2 eggs 100g (1/2 cup) sugar 30g (3 1/2 tbsp) cornstarch a pinch of salt 2 tsp vanilla prepare the dough 200ml (1 cup) warm milk 1 tbsp yeast 100g (1/2 cup) sugar 1 tsp vanilla 2 eggs 90g (1 cup) butter (soften at room temperature) 600g (about 4-5 cups) plain flour topping 1 egg yolk + 3 tbsp milk almond flaked -------half recipe-------- 250ml (1 cup) milk 1 egg 50g (1/4 cup) sugar 15g (1.75 tbsp) cornstarch 1/2 pinch salt 1 tsp vanilla dough 100ml (1/2 cup) milk warm 1/2 tbs yeast 50g (1/4 cup) sugar 1/2 tsp vanilla 1 egg 45g (1/2 cup) softened butter 300g (2-2.5 cups) flour topping 1 egg yolk \u0026 3 tbs milk almond flaked for chocolate: add to the custard 2 tbs cocoa powder add to the dough 1/2 cup (50g) cocoa and 1/2 cup (100g) sugar add milk to saucepan\nadd egg, sugar, salt, cornstarch (also some vanillin) and vanilla bean\nheat on med heat for about 5 minute while continuously stirring\nonce mixture thickens, place into bowl and cover with plastic wrap, set aside for dough\nadd warm milk and yeast to bowl, whisk, add sugar, egg, vanilla- whisk\nadd softened butter, whisk\nadd flour slowly,\nmix until combined\nknead about 5 minutes or until basically smooth and not sticky\nlet sit out for an hour\neither place in fridge or use immediately (sitting in fridge is easier to handle)\nroll out dough pretty thin, 1/2 to 1/4 inch?\nspread on custard\nroll up\ncut thin!! with floss\nset on tray and cover with plastic for ~ 15 minutes, egg wash and add almonds if adding\nthen baked in air fryer @ ~335f for 8-10 minutes +  "},{"id":"danish-dough","title":"Danish Dough","description":"","image":"images/danish_dough_gszk2.jpg","servings":"","categories":[],"source":{"label":"https://cooking.nytimes.com/recipes/1017897-danish-dough","url":"https://cooking.nytimes.com/recipes/1017897-danish-dough"},"editPath":"data/recipes-md/danish-dough.md","ingredientCount":7,"stepCount":6,"search":"danish dough    1 1⁄2 cups/6 3/4 ounces/192 grams bread flour, plus more for the work surface and the rolling pin 2 tablespoons/24 grams granulated sugar 2 teaspoons/6 grams active dry yeast 3⁄4 teaspoon/3 grams kosher salt 14 tablespoons/198 grams cold, unsalted butter (1 3/4 sticks), roughly cubed 1 large egg 1⁄4 cup/60 milliliters cold whole milk combine the flour, granulated sugar, yeast and salt in the bowl of a food processor. add the butter and pulse to combine. the butter should be the size of small marbles and peas. transfer this mixture to a medium bowl. in a small bowl, whisk together the egg, milk and 2 tablespoons/30 milliliters water. add the egg mixture to the flour mixture. using a rubber spatula, fold the mixture until it is evenly moistened. turn the dough out onto a piece of plastic wrap, shape into a small rectangle, and wrap well. chill for at least 3 hours, and up to 2 days. on a lightly floured surface, using a floured rolling pin, roll the dough out to an 8-by-15-inch rectangle. with a short side facing you, fold the dough in thirds like a letter, bringing the top third of the dough down, then folding the bottom third up. use a bench scraper to help lift and fold the dough if necessary. at this point, the dough will be rough and shaggy with visible butter pieces; as you roll and fold the dough it will come together. rotate the dough 90 degrees. repeat the rolling and folding process, then rotate the dough once more and roll and fold again. as you work, dust the work surface, your hands and the rolling pin with flour as necessary. wrap the dough in plastic wrap and refrigerate for at least 1 hour. repeat the entire rolling and folding process one more time for a grand total of six turns. if the dough starts to fight you and become difficult to roll at any point, just pop it in the fridge for an extra rest. wrap the dough and refrigerate for at least 2 hours, or overnight. if you are using this dough to make the pear and almond danish braid, add 1 teaspoon/2 grams coarsely ground fresh cardamom to step 1, along with the flour, sugar, yeast and salt.  https://cooking.nytimes.com/recipes/1017897-danish-dough"},{"id":"duck-sauce","title":"duck sauce","description":"","image":"images/duck_sauce_ml9ft.jpg","servings":"","categories":[],"source":{"label":"","url":""},"editPath":"data/recipes-md/duck-sauce.md","ingredientCount":8,"stepCount":1,"search":"duck sauce    1/2 tsp soy 2 tsp sherry vinegar and some sprays 1/4 cup apricot pinch dried garlic powder pinch dried mustard powder 1tbsp water 1tsp hoisin 2tsp chili crisp -  "},{"id":"edible-gingerbread","title":"edible gingerbread","description":"","image":"","servings":"","categories":[],"source":{"label":"","url":""},"editPath":"data/recipes-md/edible-gingerbread.md","ingredientCount":14,"stepCount":1,"search":"edible gingerbread    9x13\" pan with parchment oven temp: 350f 1 cup (237 ml) milk or water (used infused cream + butter) + added vanilla to that 1/2 cup (118 ml) molasses 1/2 cup (118 ml) honey 1/2 cup (one stick, 113g) butter (i used half shortening, half butter) 1/2 cup (100g) granulated sugar 1 egg 2 1/2 cups (300g) all-purpose flour 1/2 teaspoon salt (maybe 3/4 if using unsalted butter) 1 1/2 teaspoons baking soda + pinch of baking powder 2 tablespoons ground cinnamon 2 tablespoons ground ginger (use half if you don't want it very spicy) a little finely-ground black pepper pour the cream into a pot on stove over low heat, add in shortening and butter as well as distillate\nwarm and stir until all distillate is out\nadd splash of vanilla\nremove from heat, add molasses and honey, stir, set aside\nmix dry ingredients, flour, salt, b powder,+ b soda, spices-- whisk to combine to fluff flour\nput the sugar in with the wet ingredients along with the egg and stir until smooth.\npour the wet mixture into the dry and whisk until just smooth\nmake sure mix is slightly warm\npour into 9x13 or [bread loaf pan(takes longer)]\nbake 15-35 mins\ntake out just before done\nadd marshmallows + broil\ntake out with parchment and cool on rack  "},{"id":"falafel","title":"falafel","description":"","image":"images/falafel_d3oct.jpg","servings":"","categories":[],"source":{"label":"","url":""},"editPath":"data/recipes-md/falafel.md","ingredientCount":10,"stepCount":2,"search":"falafel    2 cups dried chickpeas (soaked 12 hours) 1 l onion chopped or 2 medium/sm 1/4 cup parsley and cilantro (more) 4 sliced garlic cloves pinch baking powder? 1 tsp coriander 1 tsp cumin salt to taste (1-2 tsp) xanthan gum 2 tsp besan to coat combine soaked chickpeas with onion, herbs and garlic in a large bowl, stir together\nscoop into food processor\nblend and hold, stir with spatula, scrape sides\nadd little bit of water if needed\ndump mixture resembling ricotta? into bowl\nadd spices, baking powder, and xanthan gum\nmix thoroughly with spatula shape into falafel\ncoat with besan\nfry 350f oil?\nuntil golden and crisp need oven tray lined with parchment (for falafel balls) need oven tray lined with parchment and oven rack (for cooked falafel) spider "},{"id":"fava","title":"FAVA","description":"","image":"","servings":"","categories":[],"source":{"label":"","url":""},"editPath":"data/recipes-md/fava.md","ingredientCount":10,"stepCount":1,"search":"fava    2 tbsp cumin 1 tbsp coriander 300g tomatoes salt to taste 1/2 tsp white pepper 4 cups fava beans virgin olive oil garnish - tomatoes, parsley lemon juice - if required 8 chopped garlic cloves -  "},{"id":"fishy-rice-spice","title":"Fishy Rice Spice","description":"also served it with seasoned rice, lemon + herb.1 cup rice1.5 cup of water1 tbsp of:dried parsleyonion powdercilantrolemon juice1tsp of:dried thymedried rosemaryvegetable bouillonminced garlic (approximately one clove)other:1/2 tsp of white pepper2 tsp of coriander2 tbsp of cultured, unsalted butter","image":"","servings":"","categories":[],"source":{"label":"","url":""},"editPath":"data/recipes-md/fishy-rice-spice.md","ingredientCount":1,"stepCount":1,"search":"fishy rice spice also served it with seasoned rice, lemon + herb.1 cup rice1.5 cup of water1 tbsp of:dried parsleyonion powdercilantrolemon juice1tsp of:dried thymedried rosemaryvegetable bouillonminced garlic (approximately one clove)other:1/2 tsp of white pepper2 tsp of coriander2 tbsp of cultured, unsalted butter   - -  "},{"id":"fluff-cereal-bars","title":"fluff cereal bars","description":"","image":"","servings":"8 bars","categories":[],"source":{"label":"","url":""},"editPath":"data/recipes-md/fluff-cereal-bars.md","ingredientCount":11,"stepCount":1,"search":"fluff cereal bars  8 bars  1.5 cups plain cheerios .5 cup bran flakes .5 cup maple magic spoon .5 cup granola crushed some .5 cup toasted almond slivers 1 tbs toasted wheat germ 1-2 tbs caramel packet from brownie mix 1 cup fluff 4 tbs butter (used 1 tbs butter, 1.5 tbs avocado oil, 1.5 tbs butter shortening) use less 1 scoop protein powder pinch salt in toasted almonds mix together all dry ingredients (toasted almonds, toasted wheat germ, bran flakes, cheerios, magic spoon, granola)\nmelt together butter, add fluff to butter, caramel, scoop of protein powder, mix until combined\nonce combined, pour over dry\nmix until evenly coated\npress into greased bar tray/pan\nsit 30 minutes in fridge  "},{"id":"frosting","title":"frosting","description":"","image":"","servings":"","categories":[],"source":{"label":"","url":""},"editPath":"data/recipes-md/frosting.md","ingredientCount":5,"stepCount":1,"search":"frosting    375g pwdr sgr 42g cocoa powder pinch salt 84g butter 45ml-95ml milk -  "},{"id":"garlic-bread-sticks","title":"garlic bread sticks","description":"","image":"","servings":"12","categories":[],"source":{"label":"","url":""},"editPath":"data/recipes-md/garlic-bread-sticks.md","ingredientCount":12,"stepCount":2,"search":"garlic bread sticks  12  1 tbs instant yeast 2 tbs sugar 1 cup 100-110f water 2\u00261/2-3 cups flour; half bread flour half all-purpose-- more bread than ap 2 tsp salt +? 3 tbs olive oil for topping 4 tbs melted butter 2 tbs + parmesan 1 tsp mix herbs de provence + italian seasoning 2-3 cloves minced garlic some salt combine warm water, yeast, sugar, salt, + oil\nadd 2 cups flour\nonce incorporated, slowly add rest of flour\ndough pulls from side of bowl, not too wet\ntransfer dough to a lightly greased bowl\ncover with damp towel or paper towel +foil 30 mins- 1 hour+ (until doubled)(longer better)\nline baking sheet with parchment + lightly spray\npunch down dough\ndivide dough into 12 equal pieces (around 50g-60g)\n9-10 inch rope roll out\ncover with damp paper towel\nlet rise 20 minutes - 1 hour on sheet pan once rolled out\nbake 425f 10-15 minutes for topping: while baking, heat butter until just browned\nremove from heat\nadd in garlic cloves, sit ~30 seconds, then strain garlic out\npour butter into cup/glass with parmesan, dry herbs/spice mixture, salt\nuse brush to immediately spread onto tops of bread sticks adapted from 2 separate recipes "},{"id":"garlic-herb-butter","title":"Garlic Herb Butter","description":"","image":"","servings":"","categories":[],"source":{"label":"","url":""},"editPath":"data/recipes-md/garlic-herb-butter.md","ingredientCount":9,"stepCount":1,"search":"garlic herb butter    2 sticks unsalted butter, room temperature 4 cloves garlic, minced 1 tablespoon chopped parsley leaves 1/2 teaspoon salt or 2 tbs butter 1/2 tsp garlic large pinchful chopped fresh parsley sm pinch of salt -  "},{"id":"garlic-naan","title":"Garlic Naan","description":"Chainbaker recipe","image":"images/garlic_naan_hcykc.jpg","servings":"4 large, 8 sm","categories":[],"source":{"label":"","url":""},"editPath":"data/recipes-md/garlic-naan.md","ingredientCount":13,"stepCount":12,"search":"garlic naan chainbaker recipe 4 large, 8 sm  for the dough – 250g (8.8oz) strong white bread flour 5g (0.2oz) salt 5g (0.2oz) sugar 3-6g (0.1oz) dry yeast or three times the amount of fresh yeast 10g (0.35oz) oil 60g (2.1oz) yogurt at around 20c (68f) 100g (3.5oz) milk at around 20c (68f) for the garlic butter – 2 tablespoons of softened butter chopped parsley 1 minced clove of garlic pinch of salt (mix everything until combined ready for spreading) add the milk and yeast to a bowl and let the yeast hydrate for a couple of minutes. add the salt, sugar, oil and yogurt and give it a good mix to dissolve any salt and sugar crystals. add the flour and mix until combined. knead the dough for around 5 minutes. desired dough temperature 25 – 26c (77 – 79f). if your dough is\nwarmer, then reduce the proofing time. if it is cooler, then increase proofing time. ferment for 25 minutes. my kitchen as quite warm on the day of baking, so i had to cut down on fermentation time. keep an eye on your dough and if it is fermenting rapidly, react. fold. proof for 25 minutes. divide into 4 equal pieces and shape into balls. cover and proof for around 30 minutes. roll the dough out and rub with oil. cook in a pan on medium-high heat flipping every 30 seconds for around 4 minutes or until well coloured and puffed up. you can use more oil to get a more evenly brown colour. brush the breads with the garlic butter and enjoy whilst still warm with your favourite curry.  "},{"id":"garlic-sauce","title":"garlic sauce","description":"","image":"","servings":"","categories":[],"source":{"label":"","url":""},"editPath":"data/recipes-md/garlic-sauce.md","ingredientCount":6,"stepCount":1,"search":"garlic sauce    100g mayo 50g greek yogurt 15g vinegar 10 cranks black pepper juice from quarter lemon salt -  "},{"id":"glazed-donuts","title":"Glazed Donuts","description":"","image":"images/glazed_donuts_divx9.jpg","servings":"","categories":[],"source":{"label":"","url":""},"editPath":"data/recipes-md/glazed-donuts.md","ingredientCount":20,"stepCount":36,"search":"glazed donuts    •500g flour; half recipe on right: •167g all purpose flour 83.5g •167g cake flour 83.5g •167g bread flour 83.5g •7g fine salt 3.5g •3g amylase 1.5-2g •2tsp rapid rise yeast 1tsp •300g/ml milk (or; 150g-180g cream +130g-150g water) 150g (75g \u002675g) •35g-85g granulated sugar 17.5g-45g less •1 egg 1/2 egg •2tbs shortening/crisco 1tbs •2tbs unsalted butter 1tbs •1/3 vanilla bean + splash vanilla (bean not necessary, but worth it) •crisco for frying glaze half recipe on right •~400g powdered sugar 200g • pinch of salt 1/2 pinch • 20g corn syrup 10g • ~140g cream (warmed with vanilla bean slightly) 70g • 1/3 - 2/3 vanilla bean sm splash warmed up vanilla best refrigerated and then whisked with more cream •weigh out flours \u0026 salt, amylase combine, set aside •in a large bowl, measure out yeast •in a smaller saucepan (or microwave bowl), weigh out milk(cream+water) \u0026 sugar, combine •medium heat, warm milk sugar mixture until 115f (microwave, probably 20 sec? intervals) •do not exceed 140f or it will kill yeast •pour milk mixture into yeast, whisk •let mix sit about 15 minutes •melt butter and crisco together, cool •add vanilla, egg, + melted butter \u0026 crisco to milk yeast mix, whisk •add flour mix to milk mix, combine (i use silicone spatula) •on a very lightly floured surface, gently knead/fold dough for 5-7 minutes •grease large bowl with crisco •make dough into ball and place into well greased bowl •cover and let rise 2-3 hours •after, either roll out and shape dough or rest in fridge overnight •press dough down •roll dough out into about 1/8\" to 1/4\" •with an uncrustable sandwich cutter (any proper sized circular cutter), cut out donuts •cut out center of donut with medicine cup bottom or proper sized equivalent •once cut, let rise 30 minutes to 1 hour on a foiled, lightly floured, sheet pan •prepare wire racks (and sheet trays to lay under them, foiled/covered) •once risen, in a large pan or wok (i use a wok, on a plug in heating element for less mess) heat crisco to 350f, no more or donuts will burn •fill wok a little less than halfway •with a candy thermometer, check temperature of crisco (don't touch bottom of pan) •as soon as temperature says around 345f and climbing, quickly but carefully place as many donuts as you can fit into the hot crisco •set a 1 minute timer as soon as you put the last donut of the batch in •keep and eye on donuts as not to burn •flip after 1 minute and cook 1 more minute •cook 1 minute on each side •donuts will be a light to medium brown/golden •with a spider strainer, strain out donuts onto wire rack •continue process until all dough is fried •while donuts are still warm, dip in glaze on either side, tapping gently on side of bowl to remove excess •place donuts back onto wire racks to let glaze set •continue until all donuts are glazed and glaze is set enjoy~  "},{"id":"gravy","title":"Gravy","description":"","image":"images/gravy_lmklz.jpg","servings":"2","categories":[],"source":{"label":"https://www.recipetineats.com/gravy/","url":"https://www.recipetineats.com/gravy/"},"editPath":"data/recipes-md/gravy.md","ingredientCount":8,"stepCount":6,"search":"gravy  2  0.33 chicken stock cube / bouillon cube (sub 2 tsp powder) (note 1) 0.33 beef stock cube / bouillon cube (sub 2 tsp powder) (note 1) dont add (for chicken gravy) 0.75 cups ( 188.33ml) boiling water 20g/ 1.33 tbsp butter , unsalted 1.33 tbsp flour , plain / all purpose 0.17 tsp onion powder (ok to omit or sub garlic powder) 0.08 tsp finely ground black pepper salt , if needed crumble cubes into boiling water, mix to dissolve. melt butter in a saucepan over medium heat. add flour, onion powder and pepper. mix into butter with a wooden spoon or whisk. while stirring, slowly pour in half the liquid. once incorporated into the flour butter roux (it will thicken quickly), add remaining liquid and mix. stir for 1.5 – 2 minutes until it thickens to a gravy consistency (it's quick as water is already hot). taste, add more salt and pepper if needed. serve over chops, steak, sausages, veggies, roast chicken, pork, beef, lamb. pictured – kfc potato and gravy copycat! stock cubes / bouillon cubes – as pictured in post. chicken for base flavour, beef for flavour boost + makes gravy nice brown colour (if only chicken, gravy is pale). substitute with stock powder / granulated bouillon, but note that some brands of beef powder will not yield quite the same brown colour, will be slightly lighter. if you only use chicken cube or powder, the gravy flavour will lose a touch of seasoning and will be a pale brown colour. can make up for this with 1 tsp dark soy sauce – it will stain the gravy and add a touch of extra flavour (this is a secret cooking trick for gravy!) onion or garlic powder – not the end of the world if you don’t have this, it’s just a tiny hint of extra flavour. gravy consistency – don’t let it get too thick, it thickens more when sitting around to be served. if it gets too thick, just add a touch of water. too thin, keep it on the stove, it should thicken quickly. storage – gravy gets thicker and gets a skin on the surface as it cools. just use water to thin out, whisk the skin in and heat it up, it will be as good as new. if serving soon, just place a lid on the saucepan then reheat when required. make ahead and leftovers – transfer to container and place lid on, let cool then refrigerate for up to 5 days. can also freeze – once thawed, reheat and give it a good mix. you’ll need to loosen with water. gluten free – skip flour, ensure stock cubes are gluten free. mix 2.5 tbsp cornflour/cornstarch with 3 tbsp water, then add that into the hot stock liquid. mix, then pour that into the saucepan with melted butter. will thicken in 2 minutes or so. nutrition per serving, just under 1/2 cup per serving (yes that’s generous!). to reduce calories, can halve the butter to 30g/2tbsp – when flour is added, mixture will be crumbly rather than “wet” (as seen in video) but will dissolve in liquid (use whisk). 33 cal per serving reduction. https://www.recipetineats.com/gravy/"},{"id":"hemptsels","title":"Hemptsels","description":"","image":"images/hemptsels_sr9cl.jpg","servings":"","categories":[],"source":{"label":"","url":""},"editPath":"data/recipes-md/hemptsels.md","ingredientCount":19,"stepCount":6,"search":"hemptsels    poolish (150g bread flour + 150g water + pinch yeast) tangzhong (2 tbs water, 4 tbs milk, 2 tbs bread flour) 125ml whole milk 20??ml water 10g bread machine yeast 1 large egg 1 egg yolk 132g manitoba max fiber hemp powder (hemp flour) 268g whole wheat flour 150g bread flour 7g salt 4g amylase 1.5g (1/2 tsp) xanthan gum 60g sugar 44g softened butter 44g butter flavored shortening melted butter triple-seed-topping (1:1:1; hemp hearts, wheat germ, black seeds) flakey salt combine water and milk in a small bowl, whisk in yeast to dissolve, place in a stand mixer bowl along with the whole egg and egg yolk; and the tangzhong and ripened poolish; mix on low speed, until combined. in a separate bowl, mix flour, sugar, salt, xanthan gum and amylase.\nwhile mixing (by hand or stand mixer), add in your flour mixture, 1⁄4 cup at a time, until all of your flour has been added. once it begins to form a rough dough, allow to knead for 2 minutes or until it begins to turn smooth.\nthen add your butter, allow to mix until fully incorporated, and knead for 5-10 more minutes or till your dough is very smooth and begins to pull from the sides of the bowl. cover with plastic wrap and rise for 45 minutes at room temperature.\nthen place in the fridge for 1.5 hours and up to overnight. separated into 150g portions, shape into pretzel and let rise for at least half an hour at room temperature.\nideally refrigerate for at least 4 hours before the lye bath (1000g water to 30g naoh). top with triple-seed-topping and flakey salt.\nthen bake @ 425f until deep pretzel brown (approximately 18 minutes)\noptionally top with melted butter.  "},{"id":"hero-roll","title":"Hero Roll","description":"Josh Weissman","image":"","servings":"","categories":[],"source":{"label":"","url":""},"editPath":"data/recipes-md/hero-roll.md","ingredientCount":10,"stepCount":6,"search":"hero roll josh weissman   hero roll: - 2.5 teaspoons (8g) instant yeast - 302g (302ml) water - 600g bread flour - 2.5 tablespoons (33g) sugar - 2g amylase - 2 teaspoons (14g) fine sea salt - 1/4 cup (34g) unsalted butter - fine cornmeal for dusting - 1 egg white - 1/2 cup (118ml) water instructions: hero roll: preheat oven to 375 f. in a container mix water (90f) and yeast until dissolved, follow that with sugar, whisk until dissolved, and pour into your stand mixer bowl with the dough hook attachment. in a separate bowl, mix the bread flour and sea salt. add your flour mix a heaping spoon at a time until all it has been added. let that mix for five minutes or until your dough turns smooth; then add unsalted softened butter, let that mix for another two minutes or until incorporated and smooth. shave your dough into a ball, place it on a greased bowl, cover with plastic wrap, and let it rise for one hour at room temperature or until doubled. next, degas your dough by punching; divide into eight evenly sized balls, cover them with a damp towel and rest for ten minutes. roll your balls into a rectangle (roughly 7” by 4”). then starting from the long side, roll it tightly into a log, seal the seam, then roll it out to the ends to taper (try not to get it too long); place them onto a baking sheet lightly dusted with cornmeal, and repeat with the rest of the balls. next, cover them with another baking sheet inverted, wrap it with plastic wrap and let them proof at room temperature for 30 minutes. whisk one egg white in water until thoroughly combined, pour that into a spray bottle, and spray your dough to coat evenly and lightly with egg wash. (you can use a brush too). next, using a sharp razor, score your dough at a 35-degree angle, about a quarter of an inch deep into the dough. place in the oven and bake for 15 - 2o minutes. remove and brush with melted butter (optional), then cool on a wire rack until completely cool.  "},{"id":"homemade-puff-pastry","title":"Homemade Puff Pastry","description":"375F-390F","image":"","servings":"","categories":[],"source":{"label":"","url":""},"editPath":"data/recipes-md/homemade-puff-pastry.md","ingredientCount":5,"stepCount":16,"search":"homemade puff pastry 375f-390f   2.5 cups (320g) all purpose flour 3/4 cup (177g) cold water 1 tsp (7g) fine sea salt 1 cup plus 2 tbsp (227g) unsalted cold butter 6 grams ish of yeast example folding schedule: 10:00am - make dough and butter block and refrigerate 10:35am - encase butter into dough roll and letter fold, turn 90 degrees and repeat roll and letter fold. fridge for 30 minutes (2 folds done) 11:15 am - repeat two more folds, letting the dough rest in the fridge if necessary (now at 4 folds). once folds are complete, rest in the fridge for 30 more minutes. 11:55 am - perform 2 more folds totaling at 6 (you will likely need to rest the dough in the fridge after the 5th fold if it won't roll out). 12:30 am - once all 6 folds are done, wrap your dough and rest in the fridge for 1-3 days then use in whatever recipe you're making. (maybe beef wellington . wink wink method: start off by combining fine sea salt with all-purpose flour and give it a whisk. once that’s thoroughly incorporated, stream in cold water. knead a few times to make sure it’s all combined and the flour is hydrated. to roll your dough out into a perfect 7x7 inch square, place your dough on a sheet of wax paper. fold the wax paper so that the edges make a 7x7 inch square. roll out your dough using a rolling pin to fill in the edges. place the dough in the fridge. take your cold unsalted butter and cut it into cubes; sprinkling lightly with flour. gently beat it together using a rolling pin until it comes together to form a solid mass. fold it over using a bench scraper and continue this process until its’ smooth and cohesive. place your butter on a sheet of wax paper and repeat the process like the dough; but shaping it to be a 4x4 inch square. place in your fridge alongside your dough and let it rest for 30 minutes. take your dough and butter out of the fridge and lightly dust your work surface. slightly roll out the points of your dough to elongate them; then place your butter square in the center positioned at a diagonal. fold the edges of the dough over the butter so that they all meet together, then gently pinch the edges together. roll your dough out into a long rectangle measuring 12 inches in length and 6 inches in width. fold the top part of the rectangle 1⁄3 of the way down; then the bottom 1⁄3 to overlap the top fold. rotate your dough 90 degrees and roll it again into a rectangle 12x6 inches. perform the same folding technique. let your dough rest wrapped in the fridge if necessary. perform two more folds, and let it rest in the fridge for 30 minutes. take it out and perform two more folds again, for a total of 6 folds. see timing chart above* once you’ve done a total of 6 folds, let it rest for 1 hour before rolling your pastry out.  "},{"id":"honey-buns","title":"Honey Buns","description":"","image":"images/honey_buns_2m3ly.jpg","servings":"24ish","categories":[],"source":{"label":"","url":""},"editPath":"data/recipes-md/honey-buns.md","ingredientCount":15,"stepCount":30,"search":"honey buns  24ish  honey buns: • 2 cups all-purpose flour • 3 tablespoons granulated sugar • 1⁄2 teaspoon salt • 1⁄2 cup + 3 tablespoons milk (water + cream) • 2 1⁄4 teaspoons (1 packet) instant or active dry yeast • 5 1⁄3 tablespoons (1⁄3 cup) butter melted (half crisco) • 1 large egg • 1⁄2 tablespoon vegetable oil • 1 1⁄2 teaspoon ground cinnamon • 3 cups vegetable oil for frying (optional) glaze: • 3 tablespoons butter melted • 2 teaspoon honey • 11⁄4 cups powdered sugar • 2 tablespoons milk • 1⁄2 teaspoon vanilla extract or bean equivalent honey buns: • whisk together flour, sugar, \u0026 salt • in a microwave-safe bowl, add in the milk. microwave for 30 seconds.\n(can use stovetop)\n• milk should be at 105 - 110 degrees f. • add yeast, cooled melted butter, and egg to milk • pour the wet mixture into dry \u0026 mix gently (using very little flour)\nfor 10 minutes.\n~the dough will be sticky. • grease your hands and a large bowl with vegetable oil. • shape dough into a ball. • place the dough in the bottom of the bowl and coat it in the 1/2 tbs oil.\n• cover the bowl with plastic wrap and let the dough rise until doubled.\n• this will take about 1 to 2 hours. • line a cookie sheet with parchment paper/foil.\n• spray the parchment paper with nonstick baking spray. • once the dough has doubled, press it down. • place the dough on a lightly floured work surface. • press the dough out into a 6-inch by 14-inch rectangle.\n~you can use a rolling pin, or use your hands. • brush honey onto rectangular dough (thin layer)\n• sprinkle the cinnamon on top of the honey \u0026 dough.\n• using your brush (or hands), rub the cinnamon all over • begin rolling the dough from the long side. • once the dough is rolled up, you'll need to seal the edge.\n• do this by rubbing the edge of the dough with water.\n• pinch the wet edge into the roll of dough to form the seam.\n• if the dough isn't staying pinched together, rub a little more water on the edge and pinch again.\n• leave the dough seam side up since it will be sticky from the water and will likely stick to the counter if it touches it. • measure out 1⁄2-inch thick slices if you want thinner honey buns or 1-inch slice for thicker slices.\n(1-inch or thicker) • slide a piece of floss under the dough and cross both sides of the floss\n• pull until the floss has cut completely through the dough. • place on the prepared cookie sheet.\n• repeat with the remaining dough. if you plan on baking these, you'll want to space them 2 inches apart.\nif you plan on frying them, they can be 1⁄2 inch apart. • brush entire surface of honey bun with honey • let rise, lightly covered, for 30 minutes in a warm place. --baked honey buns: • preheat oven to 350f. -bake for 10 to 15 minutes until the edges begin to turn golden brown- • prepare the glaze while the honey buns are baking. • remove the honey buns from the oven and let cool for 10 to 20 minutes.\n• while they're still warm, dip the tops in the glaze, or place icing on top and rub in with spoon.\n• tap the wrist that's holding the honey bun to remove the excess glaze\n• place on wire rack or wax to continue cooling \u0026 let the glaze set up. --fried honey buns: • heat 3 cups of vegetable oil until it reaches 320f. • prepare the glaze while you wait for the oil to come up to temperature. • place the honey buns in one or two at a time into the oil.\n• flip once the donuts become golden brown. • once the other side becomes golden brown, place on a plate lined with paper towels.\n• let cool for 5 to 10 minutes. • dip the warm honey bun in the glaze.\n• give your wrist a tap to help any excess glaze to drip off.\n• place on a piece of wax paper and let the glaze set up. --glaze: • in a medium mixing bowl, add in the butter, powdered sugar, milk, and vanilla extract/bean.\n• whisk together until the glaze is smooth.  "},{"id":"if-making-candied-lemon-slices","title":"if making candied lemon slices","description":"","image":"","servings":"","categories":[],"source":{"label":"","url":""},"editPath":"data/recipes-md/if-making-candied-lemon-slices.md","ingredientCount":1,"stepCount":1,"search":"if making candied lemon slices    boil lemon slices a few times to remove bitter first -  "},{"id":"italian-dressing","title":"Italian Dressing","description":"Half recipe on RIGHT","image":"","servings":"","categories":[],"source":{"label":"","url":""},"editPath":"data/recipes-md/italian-dressing.md","ingredientCount":11,"stepCount":1,"search":"italian dressing half recipe on right   1/2 cup olive oil 1/4 cup 3 tbsp white wine vinegar 1.5 tbs 3 tbsp grated parmesan cheese 1.5 tbs 1 tsp dijon mustard 1/2 tsp 1 tsp honey 1/2 tsp 2 cloves garlic, minced (1/2 tsp powder) -- 1/4 tsp 1/2 tsp dried oregano 1/4 tsp 1/2 tsp dried basil 1/4 tsp 1/2 tsp dried parsley 1/4 tsp 1/2 tsp salt 1/4 tsp 1/2 tsp black pepper 1/4 tsp in a medium bowl or jar, whisk together all ingredients until smooth and creamy. serve immediately or store in an airtight container in the fridge until ready to serve.  "},{"id":"italian-wedding-soup-with-turkey-meatballs","title":"italian wedding soup with turkey meatballs","description":"","image":"","servings":"","categories":[],"source":{"label":"","url":""},"editPath":"data/recipes-md/italian-wedding-soup-with-turkey-meatballs.md","ingredientCount":17,"stepCount":6,"search":"italian wedding soup with turkey meatballs    10-12 cups chicken broth 2 tbs olive oil 1 lb ground turkey lean 1/2 cup panko 1/3 cup parsley finely chopped 1 egg 3-4 minced garlic cloves 1 tsp salt kosher 1/2 tsp pepper 1/2 cup parmesan 3/4 cup orzo 3 cups packed baby spinach 1 lemon, zested and halved 1 tsp black garlic added while simmering 1 tbs umami powder 1-2 cups? broiled carrot large chop diagonal 1-2 cups carrots cut largely broiled step 1\ncombine broth with 2 tbs olive oil in large pot-- bring to boil step 2\nadd turkey, panko, parsley, egg, garlic, salt, pepper, \u0026 1/2 cup parmesan to a large bowl- mix\nroll into 1\u00261/2 inch balls\ntransfer to pan for broiling step 3\nheat broiler to high\nset oven rack 6-8 inches away\nbroil meatballs until browned on each side step 4\nadd pasta to boiling broth and cook until al-dente\nlower heat to low simmer step 5\nadd meatballs to broth and simmer 3-5 minutes until warmed through\nremove from heat\nadd spinach and lemon zest and stir\nseason to taste with salt and pepper step 6\ndivide soup among 4 bowls\ndrizzle each with olive oil, parmesan, and a squeeze of lemon juice  "},{"id":"jalebi","title":"jalebi","description":"www.youtube.com/watch?v=pdFm9Rnz4H8","image":"","servings":"","categories":[],"source":{"label":"","url":""},"editPath":"data/recipes-md/jalebi.md","ingredientCount":16,"stepCount":1,"search":"jalebi www.youtube.com/watch?v=pdfm9rnz4h8   ingredients:- flour 1 cup /150g cornflour 4 tbsp baking soda 1/4 tsp food colour 1/4tsp (yellow/orange) yogurt 4 tbsp water 150ml vanillin amylase pinch ingredients for syrup:- sugar 3 cups water 1 \u0026 1/2 cups lemon juice 2 tsp cardamom 6-7- not this 2 tbs honey -  "},{"id":"jamaican-beef-patties","title":"Jamaican Beef Patties","description":"How to make Jamaican Beef Patties","image":"images/jamaican_beef_patties_qkc7t.jpg","servings":"?? recipe is adjusted for 1 lb of beef","categories":[],"source":{"label":"","url":""},"editPath":"data/recipes-md/jamaican-beef-patties.md","ingredientCount":32,"stepCount":1,"search":"jamaican beef patties how to make jamaican beef patties ?? recipe is adjusted for 1 lb of beef  bake @ 380f-400f ~ 20-30 minutes for the crust ♥ 2cups all purpose flour ♥ 4g salt ♥ 6tbs butter, softened ♥ 6tbs shortening ♥ 150 ml/grams chilled water --1/2 tsp bouillon into water + sm amt milk pwdr ♥ 2tsp curry ♥ 1tsp turmeric ~ pinch of msg --refrigerate for 30 mins-- for the filling ♥ 1 lb ground beef -- sm amt of bbq (sweet baby ray's honey chipotle) + bouillon + ketchup, shattah, soy sauce, thyme (thyme is optional)-- ♥ 1/2 cup onion, chopped ♥ 1/2 cup bell pepper, chopped ♥ 2 cloves garlic, {or less} ♥ 1/2 cup scallions ♥ 1 tbs ginger ♥ 1 sm carrot, chopped/diced ♥ 4.57 tbs bread crumbs ♥ 1 tsp turmeric ♥ 1 tsp bl pepper ♥ 1 tsp paprika ♥ .57 tsp jalapeno powder ♥ 1 tbs all purpose seasoning ♥ 1 tbs complete seasoning ~make eggwash~ -1 egg -splash of water -  "},{"id":"lahore-fish","title":"lahore fish","description":"","image":"","servings":"","categories":[],"source":{"label":"","url":""},"editPath":"data/recipes-md/lahore-fish.md","ingredientCount":10,"stepCount":1,"search":"lahore fish    45g tamarind 45g besan .9 lemon 2tsp salt 1.33tsp red chili powder 1.33tsp red chili flakes 3.625tsp coriander 2.66tsp cumin .225tsp garam masala 2lbs fish -  "},{"id":"large-soft-pretzels","title":"Large Soft Pretzels","description":"","image":"images/large_soft_pretzels_xrsgi.jpg","servings":"8","categories":[],"source":{"label":"https://www.publix.com/recipe/homemade-soft-pretzels","url":"https://www.publix.com/recipe/homemade-soft-pretzels"},"editPath":"data/recipes-md/large-soft-pretzels.md","ingredientCount":12,"stepCount":5,"search":"large soft pretzels  8  11 cups warm water (100°f–110°f), divided 2 tablespoons sugar 1 (1⁄4 oz) envelope active dry yeast 6 tablespoons salted butter 5 teaspoons kosher salt, divided 3 cups flour 1 teaspoon caraway seeds nonstick cooking spray plastic wrap parchment paper 3⁄4 cup baking soda spicy brown mustard (optional) combine in bowl of stand mixer: 1 cup warm water and sugar until blended. sprinkle yeast on top and set aside 5 minutes until mixture begins to foam. add butter to microwave-safe bowl; microwave on high in 10 second intervals until just melted. add to yeast mixture: 1 teaspoon salt, flour, melted butter, and caraway seeds; mix on low, using dough hook attachment, until well combined. raise speed to medium and knead 5–6 minutes, until dough is smooth and pulls away from side of bowl. remove dough from bowl; clean bowl and coat with spray. return dough to bowl, cover bowl with plastic wrap and set aside in warm place about 1 hour, until dough has doubled in size. preheat oven to 450°f. line 2 baking sheets with parchment paper and coat with spray; set aside. add remaining 10 cups water and baking soda to large saucepan; bring to boil on high. turn dough out onto lightly sprayed work surface; divide into 8 equal pieces. roll out each piece of dough into a 24-inch rope. lay rope in a u-shape. twist ends of rope over each other 2–3 times, then press end into bottom center of u to form a pretzel. arrange pretzel on parchment-lined baking sheets. repeat with remaining ropes. add pretzels to boiling water, 1 at a time; and boil 30 seconds. remove from water and arrange on baking sheet; sprinkle each pretzel with 1/2 teaspoon remaining salt. repeat process until all pretzels are boiled. bake pretzels 10–12 minutes, until dark golden brown. transfer to cooling rack and set aside 5 minutes before serving. serve with spicy brown mustard (if desired) and beer cheese sauce (see recipe).  https://www.publix.com/recipe/homemade-soft-pretzels"},{"id":"levain-cookies","title":"Levain Cookies","description":"NO CONVECTION","image":"images/levain_cookies_czigf.jpg","servings":"NO CONVECTION","categories":[],"source":{"label":"","url":""},"editPath":"data/recipes-md/levain-cookies.md","ingredientCount":12,"stepCount":12,"search":"levain cookies no convection no convection  1.5 cups (230g) cake flour 2 cups (275g) all purpose flour 1.5 tsp (5g) kosher salt 2 tsp (8g) corn starch 1/2 tsp (6g) baking soda 1.25 cups (280g) unsalted butter 1.25 cups (285g) brown sugar 1/2 cup (115g) white granulated sugar 2 eggs 3 egg yolks 2 cups (165g) walnuts lightly toasted 13 oz (368.45g) chopped chocolate in a medium saucepan, melt unsalted butter and set to the side to cool. roughly chop the dark chocolate. in a medium size bowl, combine cake flour, all-purpose flour, kosher salt, cornstarch, and baking soda. whisk together. using a stand mixer fitted with the whisk attachment, add light brown sugar and granulated sugar. whisk together on medium speed then slowly stream in the butter. once combined add in the eggs one at a time followed by the egg yolks. once smooth switch to the paddle attachment and mix in the flour mixture until smooth. add in rough chopped walnuts and chopped chocolate. mix until combined. place in a bowl, cover, and refrigerate for at least 45 minutes. weigh each dough ball out to 5.9oz and place on a parchment lined baking sheet. bake in a 415f for 10-13 minutes. (lower if needed to 400f or less) no convection set on a wire rack to cool before serving.  "},{"id":"macaroni-and-cheese","title":"Macaroni and Cheese","description":"elbow pasta in some cheeses etc","image":"","servings":"","categories":[],"source":{"label":"","url":""},"editPath":"data/recipes-md/macaroni-and-cheese.md","ingredientCount":11,"stepCount":1,"search":"macaroni and cheese elbow pasta in some cheeses etc   33g white cheddar 33g mozzarella 33g queso 1c milk (1/2 cream, 1/2 water + milk powder) 4g sodium citrate 2.5 tbs uns butter 15g ap flour 1/3 tsp salt single slice american cheese some pasta, more than 1/4 lb * * save extra cheese sauce and freeze ** -  "},{"id":"navy-muslim-bean-pie","title":"Navy (Muslim) Bean Pie","description":"Muhammad Ali's favorite pie","image":"images/navy_muslim_bean_pie_b19sd.jpg","servings":"2 whole pies","categories":[],"source":{"label":"https://tastecooking.com/recipes/bean-pie/","url":"https://tastecooking.com/recipes/bean-pie/"},"editPath":"data/recipes-md/navy-muslim-bean-pie.md","ingredientCount":19,"stepCount":4,"search":"navy (muslim) bean pie muhammad ali's favorite pie 2 whole pies  1 prepared pie crust 1⁄2 c (1 stick) unsalted butter, room temperature 1 1⁄2 c sugar 2 tbsp cinnamon 1⁄4 tsp nutmeg 1 tbsp cornstarch 1⁄4 tsp salt 3 eggs 1 1⁄2 c cooked navy beans 1 c evaporated milk 1 tsp vanilla extract zest of 1 lemon pie crust: 1⁄2 c whole wheat flour 3⁄4 c all purpose flour 1⁄2 tsp salt 1 tsp sugar 1⁄2 c (1 stick) cold butter 4-6tbs ice water adapted from lana shabazz’s iconic recipe, this pie is smooth, sweet, and custard-like, and its spices shine. don’t leave out the lemon zest: it’s a small but brilliant touch that ties the whole thing together. pie crust: toss together the flours, salt, and sugar. cut the butter into 1⁄2-inch chunks and add it to the flour mixture. using a pastry cutter, a fork, or your hands, work the butter into the flour mixture until the chunks are roughly the size of peas. add the water, one tablespoon at a time, using a fork to stir it into the mixture. stir until the dough begins to come together and form a shaggy mass. this may take 4 tablespoons of water, or up to 6 tablespoons. once a rough dough has formed, dump the dough onto a lightly floured surface and gently form it into a flat disc. wrap the disc tightly in plastic wrap, then place in the refrigerator and chill for at least 30 minutes, preferably 2 hours or more. bean pie: preheat the oven to 450°f. roll out your pie crust, then grease and line a 9-inch pie plate with it. set in the refrigerator to chill while you make the filling. in a food processor, blend the butter and sugar until combined. add the cinnamon, nutmeg, cornstarch, and salt and pulse to combine. add the eggs, one at a time, and pulse, waiting until each egg is fully combined before adding the next one. next add the beans, and process continually until the mixture is completely smooth. add the evaporated milk, vanilla extract, and lemon zest and blend until they are completely combined and the mixture is smooth. pour the filling into the pie crust. cook for five minutes, then lower the temperature to 325°f and bake for 45 minutes. let cool before serving, or else the pie won’t cut cleanly.  https://tastecooking.com/recipes/bean-pie/"},{"id":"nutribun-also-focaccia","title":"Nutribun also focaccia","description":"","image":"images/nutribun_also_focaccia_j30p1.jpg","servings":"","categories":[],"source":{"label":"","url":""},"editPath":"data/recipes-md/nutribun-also-focaccia.md","ingredientCount":20,"stepCount":2,"search":"nutribun also focaccia    600g bread flour 84g dry milk 72g sugar 30g oil 15g salt 18g nutritional yeast 360+g water 5g rr yeast or with poolish + autolysing 450g bread flour (for whole wheat, replace 200g of 450g with whole wheat) 84g dry milk 72g sugar 30g oil 18g nutritional yeast 300ish g/ml water or lessss later.... 5g rr yeast 15g salt 150g poolish knead 10 minutes, rest 1-2 hours\n197g dough balls or 98g\nrest 1-2hrs\ndust with 10g semolina mixed with 50g ap flour\nbake 350f (higher?)~15 minutes + steam poolish + autolyse\nmix together bread flour, dry milk, sugar, nutritional yeast, oil, and water\nlet rest 30 minutes\nthen, add some water to dough (for salt and yeast)\nadd salt and yeast\ncombine with wet hand until yeast and salt evenly distributed throughout\nrest 30 minutes\n1st strength building fold\nrest 30 minutes\n2nd strength building fold\nput in fridge overnight (at least 4 hours) if putting in fridge\nif not, let sit out 1-2 hours ish  "},{"id":"oil-gummies-pectin-and-gelatin","title":"oil gummies (pectin and gelatin)","description":"","image":"images/oil_gummies_pectin_and_gelatin_6d81v.jpg","servings":"180-200 lil cubes, or 45-50 mold-sized squares","categories":[],"source":{"label":"","url":""},"editPath":"data/recipes-md/oil-gummies-pectin-and-gelatin.md","ingredientCount":8,"stepCount":9,"search":"oil gummies (pectin and gelatin)  180-200 lil cubes, or 45-50 mold-sized squares  160g coconut oil 150g sugar + 100g water + 100g corn syrup 35g gelatin + 160g juice 1tbsp lecithin 10g pectin 1/3tsp potassium sorbate 100g gelatin 1 dram bottle flavouring oil bloom 160g juice with 35g gelatin boil to 220-250f: 150g sugar + 90g water + 100g corn syrup let syrup coil to 200f add 10g of pectin, 1/3tsp potassium sorbate, stir out clumps add 100g of gelatin, stirring out clumps add bloomed gelatin, lecithin add oil add flavouring oil whisk on low heat, consistently, until mixed and emulsified. fold edges into center as stirring  "},{"id":"pancakes-2","title":"Pancakes","description":"","image":"","servings":"","categories":[],"source":{"label":"","url":""},"editPath":"data/recipes-md/pancakes-2.md","ingredientCount":9,"stepCount":1,"search":"pancakes    1 cup all-purpose flour, (spooned and leveled) more 2 tablespoons sugar (maybe more) 2 teaspoons baking powder 1⁄2 teaspoon salt 1 cup milk less 2 tablespoons unsalted butter, melted, or vegetable oil 1 large egg 1 tablespoon vegetable oil lil vanilla bean mix and adjust according to preference of thickness  "},{"id":"pancakes","title":"Pancakes","description":"","image":"","servings":"8-10","categories":[],"source":{"label":"","url":""},"editPath":"data/recipes-md/pancakes.md","ingredientCount":9,"stepCount":1,"search":"pancakes  8-10  ingredients: 1 1/2 cups of flour (210g) 3 tablespoons of sugar (48g) 2 teaspoons of baking powder (9g) 1 teaspoon of salt (5g) 1 teaspoon of baking soda (5g) 2 eggs (room temperature) 1 cup of milk/buttermilk (240ml) 2 tablespoons of melted butter (28g) 1 teaspoon of vanilla extract (5ml) mix dry\nwhisk eggs, add milk (i used buttermilk), melted butter, + vanilla\nwhisk\nadd wet to dry, folding in with silicon spatula, do not overmix\nclumps are good/okay do not overmix\nscoop out with icecream scoop onto preheated + buttered pan\ncook ~ 2-4 mins each side on low-med, med heat.  "},{"id":"pumpkin-cake-banana-cake-mod","title":"Pumpkin Cake (banana cake mod)","description":"","image":"","servings":"two cakes","categories":[],"source":{"label":"","url":""},"editPath":"data/recipes-md/pumpkin-cake-banana-cake-mod.md","ingredientCount":34,"stepCount":9,"search":"pumpkin cake (banana cake mod)  two cakes  3/4 cup butter/shortening (half and half) (brown the butter, set in freezer ~ 20min) 7tbs butter, 6 tbs shortening) 2.5 cups sugar some molasses 3 eggs 1.5 cups pureed pumpkin 3 cups sifted flour (half cake half all purpose) 3/4 tsp baking powder 1/3 cup buttermilk 1 tsp baking soda 1 tsp salt small dash/shake nutmeg 1-2 tsp cinnamon dash ground ginger vanilla optional (not used) for frosting 1.5 box (cups?) (~ half a bag) (bag = 2lb or 907g) powdered sugar 3/4 cup (1.5 sticks) butter 3/4 cup pumpkin puree 1.5 tsp lemon juice 1/2 pkg cream cheese (4oz?) half recipe: 4 tbs browned butter, 3 tbs shortening 1.25 cup sugar molasses 1.5 eggs 3/4 cup pumpkin puree 1.5 cups flour, sifted (3/4 c ap fl, 3/4 c cake flour) 3/8 tsp baking powder 2 tbs \u0026 2tsp buttermilk 1/2 tsp baking soda 1/2 tsp salt small dash (1/8 tsp?) nutmeg 1 ish tsp cinnamon dash (1/8tsp-1/4 tsp) ground ginger optional vanilla cream together shortening, browned slightly firmed butter, sugar, \u0026 molasses blending well. add well beaten eggs and pumpkin, beat well sift flours then resift with dry ingredients (salt, b soda, b powder, cinnamon, nutmeg, ginger, salt) add dry alternatively with wet mixture of buttermilk combined in greased, floured pans bake at 350f for about 5-7 minutes, then reduce temp to 330-345 for 5 minutes, then reduce more if needed for rest of cooking time (about 25-35 minutes) internal temp should be about 190f-200f (closer to 190f) let cool for frosting: cream all ingredients together spread onto cooled cake or leave separate for individual slices  "},{"id":"ranch","title":"Ranch","description":"","image":"","servings":"","categories":[],"source":{"label":"","url":""},"editPath":"data/recipes-md/ranch.md","ingredientCount":10,"stepCount":1,"search":"ranch    1⁄2 cup mayonnaise ▢1⁄4 cup sour cream, or greek yogurt ▢2 teaspoons dried chives ▢1⁄2 teaspoon dried dill less ▢1⁄2 teaspoon dried parsley ▢1⁄2 teaspoon garlic powder ▢1⁄2 teaspoon onion powder ▢1⁄4 teaspoon salt ▢1⁄8 teaspoon pepper ▢3⁄4 cup buttermilk, or regular whole milk -  "},{"id":"salmon-in-air-fryer-marinade","title":"Salmon in Air Fryer (marinade)","description":"tasty","image":"","servings":"2 filet","categories":[],"source":{"label":"","url":""},"editPath":"data/recipes-md/salmon-in-air-fryer-marinade.md","ingredientCount":10,"stepCount":1,"search":"salmon in air fryer (marinade) tasty 2 filet  key west key lime juice 1/2 tsp bl pepper 1 tbs garlic 1 tbs paprika 1 tbs onion powder 1 tsp black garlic 1 tsp celery salt 2 tbs dijon 2 tbs olive oil 1.5 tsp molasses do  "},{"id":"sea-bass-with-cannellini-bean-stew","title":"Sea Bass with Cannellini Bean Stew","description":"","image":"images/sea_bass_with_cannellini_bean_stew_1gi41.jpg","servings":"","categories":[],"source":{"label":"https://www.feastingathome.com/sea-bass-with-cannellini-bean-stew/","url":"https://www.feastingathome.com/sea-bass-with-cannellini-bean-stew/"},"editPath":"data/recipes-md/sea-bass-with-cannellini-bean-stew.md","ingredientCount":15,"stepCount":5,"search":"sea bass with cannellini bean stew    2 t olive oil 1 medium onion, diced 1 cup peeled, diced carrot ( 2 carrots) 1 cup diced celery ( 2 stalks) 3– 4 smashed and roughly chopped garlic cloves 2 cups diced tomatoes ( or one 1 can, diced) 3 cups cannellini beans (2 cans rinsed and drained) or 1 1⁄2 cups dried beans, soaked overnight. 2 – 4 cups chicken stock ( 2 cups if using canned beans, 4 cups if using dried beans) 1 cup water (only if using dried beans) 2 tablespoons fresh sage (or thyme, or rosemary) 1⁄2 teaspoon kosher salt 1⁄4 teaspoon cracked pepper 4 four-ounce sea bass fillets ( or thick-cut true cod, escolar, halibut, black cod) oil, salt and pepper for fish italian parsley for garnish (or make leek oil or gremolata) in a medium-large heavy-bottomed pot, heat oil over medium-high heat. add onions, and stir for two minutes. add carrots, celery and garlic, turn heat to medium and sauté for about 5 minutes, stirring occasionally. if using canned beans, add them, along with the 2 cups stock, herbs and tomatoes, salt and pepper, and bring to a boil. turn heat down to low, cover and simmer gently for 10-15 minutes. alternatively, if using dried beans, make sure to soak them in ample water overnight or up to 24 hours. (this will prevent gastric issues and shorten cooking time. ) after the carrots, celery and garlic have been sautéing for 5 minutes. add the dried, soaked beans and 4 cups stock. add 1 additional cup water. add the herbs and salt. bring to a boil on high heat. cover, turn to low heat and let simmer 1-1 1/2 hours, or until the beans are tender, adding more water if needed. then add pepper and tomatoes. continue simmering another 1⁄2 hour. if the stew is too brothy for you, leave the lid off and keep it at a gentle simmer, letting it reduce a bit- however, i really enjoy it a little brothy. pan sear the fish: heat 1-2 t olive oil in a cast-iron skillet, over medium-high heat. pat dry fish with paper towels and season generously with kosher salt and pepper. sear each side until a golden crust forms on the fish, and turn the heat down to cook through to the desired doneness, taking care not to overcook. place the stew in a wide shallow bowl, top with seared fish and garnish with fresh italian parsley. if feeling fancy make gremolata or leek oil and drizzle over top.  https://www.feastingathome.com/sea-bass-with-cannellini-bean-stew/"},{"id":"serious-eats-halal-cart-style-chicken-and-rice-with-white-sauce","title":"Serious Eats' Halal Cart-Style Chicken and Rice with White Sauce","description":"","image":"images/serious_eats39_halal_cart_style_chicken__hx7sv.jpg","servings":"4","categories":[],"source":{"label":"https://www.seriouseats.com/serious-eats-halal-cart-style-chicken-and-rice-white-sauce-recipe","url":"https://www.seriouseats.com/serious-eats-halal-cart-style-chicken-and-rice-white-sauce-recipe"},"editPath":"data/recipes-md/serious-eats-halal-cart-style-chicken-and-rice-with-white-sauce.md","ingredientCount":25,"stepCount":8,"search":"serious eats' halal cart-style chicken and rice with white sauce  4  for the chicken: 2 tablespoons fresh lemon juice 1 tablespoon chopped fresh oregano 1/2 teaspoon ground coriander seed 3 garlic cloves, roughly chopped (about 1 1/2 tablespoons) 1/4 cup light olive oil kosher salt and freshly ground black pepper 2 pounds boneless, skinless chicken thighs, trimmed of excess fat (6 to 8 thighs) 1 tablespoon vegetable or canola oil for the rice: 2 tablespoons unsalted butter 1/2 teaspoon turmeric 1/4 teaspoon ground cumin 1 1/2 cups long-grain or basmati rice 2 1/2 cups chicken broth kosher salt and freshly ground black pepper for the sauce: 1/2 cup mayonnaise 1/2 cup greek yogurt 1 tablespoon sugar 2 tablespoons white vinegar 1 teaspoon lemon juice 1/4 cup chopped fresh parsley kosher salt and freshly ground black pepper to serve: 1 head iceberg lettuce, shredded 1 large tomato, cut into wedges fluffy pocketless pita bread, brushed in butter, lightly toasted, and cut into 1 × 3-inch strips harissa-style hot sauce, for serving for the chicken: combine the lemon juice, oregano, coriander, garlic, and olive oil in a blender. blend until smooth. season the marinade to taste with kosher salt and black pepper. place the chicken in a 1-gallon zipper-lock bag and add half of the marinade (reserve the remaining marinade in the refrigerator). turn the chicken to coat, seal the bag, and marinate the chicken in the refrigerator for at least 1 hour and up to 4 hours, turning occasionally to redistribute the marinade (see note). remove the chicken from the bag and pat it dry with paper towels. season with kosher salt and pepper, going heavy on the pepper. heat the oil in a 12-inch heavy-bottomed cast iron or stainless-steel skillet over medium-high heat until it is lightly smoking. add the chicken pieces and cook without disturbing until they are lightly browned on the first side, about 4 minutes. using tongs, flip the chicken. reduce the heat to medium and cook until the chicken is cooked through and the center of each thigh registers 165°f. on an instant-read thermometer, about 6 minutes longer. transfer the chicken to a cutting board and allow to cool for 5 minutes. using a chef’s knife, roughly chop the chicken into 1/2- to 1/4-inch chunks. transfer to a medium bowl, add the remaining marinade, cover loosely with plastic, and refrigerate while you cook the rice and prepare the sauce. for the rice: melt the butter over medium heat in a large dutch oven. add the turmeric and cumin and cook until fragrant but not browned, about 1 minute. add the rice and stir to coat. cook, stirring frequently, until the rice is lightly toasted, about 4 minutes. add the chicken broth. season to taste with salt and pepper. raise the heat to high and bring to a boil. cover, reduce to a simmer, and cook for 15 minutes without disturbing. remove from the heat and allow to rest until the water is completely absorbed and the rice is tender, about 15 minutes. for the sauce: in a small bowl, combine the mayonnaise, yogurt, sugar, vinegar, lemon juice, parsley, and 2 teaspoons black pepper. whisk to combine. season to taste with salt. to serve: return the entire contents of the chicken bowl (chicken, marinade, and all juices) to the skillet. cook over medium-high heat, stirring occasionally, until heated through. to serve, divide the rice, lettuce, tomato, and toasted pita bread evenly among four to six plates. pile the chicken on top of the rice. top with the white sauce and hot sauce. serve immediately, passing extra sauce at the table. special equipment blender, 12-inch cast iron skillet or stainless steel skillet do not marinate the chicken longer than 4 hours or it’ll get a mushy texture. if you must delay cooking the chicken for any reason, remove it from the marinade, pat it dry with paper towels, and refrigerate until ready to cook. https://www.seriouseats.com/serious-eats-halal-cart-style-chicken-and-rice-white-sauce-recipe"},{"id":"sesame-beef-thai-noodle-dinner","title":"Sesame Beef Thai Noodle Dinner","description":"","image":"images/sesame_beef_thai_noodle_dinner_dyn8x.jpg","servings":"","categories":[],"source":{"label":"https://www.homemadefoodjunkie.com/sesame-beef-thai-noodle-dinner/","url":"https://www.homemadefoodjunkie.com/sesame-beef-thai-noodle-dinner/"},"editPath":"data/recipes-md/sesame-beef-thai-noodle-dinner.md","ingredientCount":18,"stepCount":10,"search":"sesame beef thai noodle dinner    1 8 oz. package thai rice noodles 1 lb. cooked roast-sliced thinly against the grain and then into strips (for the marinade)for raw meat directions look to the bottom of the recipe in the notes section) 1/2 cup soy (or tamari) sauce 1/4 cup brown sugar 1 inch chunk ginger sliced thinly 2 tablespoons balsamic vinegar, or sherry 1 teaspoon chili paste or hot chili sesame oil to taste 1 tablespoon regular sesame oil 2 smashed cloves garlic 2 tablespoons cornstarch 2 tablespoons water 1 lime cut in half and juiced (for the stir-fry) 2 tablespoons avocado oil 1 fresh pepper-sweet or hot 1 onion-thinly sliced 2 cups snow peas 1 tablespoon sesame seeds for garnish parsley or cilantro for garnish layer sliced pre-cooked roast beef into a shallow baking dish (*for raw meat instructions see notes below the recipe) mix all the marinade ingredients together in a 4 cup bowl pour the marinade over the beef slices and store in the fridge. heat the water for the noodles and cook according to the package directions heat a large skillet to medium high and add oil. add the onions, peppers, snow peas and sesame seeds and cook until the onions are transparent letting the peppers and onions get a bit browned and caramelized. add the meat mixture and all it's marinade juices to the skillet and cook on low, until the marinade thickens into a nice sauce. a couple of minutes- stirring often! remove from heat immediately after the sauce is thickened. drain the noodles and serve on the plate with the stir fry ladled on top or mixed in as you prefer. garnish with sesame seeds, pepper pieces, cilantro, parsley or fresh basil. raw meat instructions: slice your raw steak or roast into thin slices, cutting across the grain of the meat. marinate it as directed above in step 3 except!!! do not add the cornstarch yet! add your marinated raw meat slices and all the marinade juice into a large skillet, before the vegetables, in step 6, and quickly cook it to browned on both sides. meanwhile cook the vegetables in a separate skillet as directed in step 6. after the vegetables and meat is cooked, combine them in the large skillet and add the cornstarch mixed with water. cook as directed in step 7 enjoy your meal! https://www.homemadefoodjunkie.com/sesame-beef-thai-noodle-dinner/"},{"id":"sesame-chicken","title":"Sesame Chicken","description":"","image":"","servings":"","categories":[],"source":{"label":"","url":""},"editPath":"data/recipes-md/sesame-chicken.md","ingredientCount":27,"stepCount":14,"search":"sesame chicken    ingredients 2 pounds boneless skinless chicken breast, cut into 1” cubes marinade 1/2 cup soy sauce 1 tablespoon tahini 1 teaspoon toasted sesame oil 1 teaspoon kosher salt 1/3 cup all-purpose flour 1/3 cup corn starch 1/4 cup water 1 tablespoon rice vinegar 1 1/2 teaspoons baking powder sauce 3 tablespoons toasted sesame oil 1 teaspoon minced fresh ginger 1 teaspoon garlic chili paste 1 3/4 cups chicken broth low sodium 2 teaspoons sherry 1/2 cup granulated sugar 2 teaspoons tahini (make your own here) 2 tablespoons corn starch 2 tablespoons soy sauce 1 1/2 tablespoons champagne vinegar 2 tablespoons toasted sesame seeds plus more for garnish other peanut oil to come up 3 inches up side of pan or wok slivered scallions instructions\nmix all of the marinade ingredients in a medium bowl and add the chicken pieces to coat. marinate for 30 minutes while you prepare the rest of the recipe. in a medium sauce pan, heat sesame oil over medium low heat and add the ginger and garlic chili paste and cook to flavor the oil, three minutes. add the chicken broth, sherry, sugar and tahini and raise heat to medium and bring mixture to hot. in a small bowl, mix corn starch with the soy sauce and vinegar to form a slurry. add this to the hot sauce and stir to thicken. once hot and bubbling, remove to a back burner and keep hot on a low heat. if the sauce is not thick enough, mix another tablespoon of corn starch with a little water and slowly add to hot sauce until desired thickness. if too thick, add a little water or soy sauce to thin. start cooking the rice so that it is done once the chicken is done. if you have a rice cooker, this can be a make ahead item. toast the sesame seeds by placing in a dry pan and heating over medium heat for 4-5 minutes, tossing often. remove to a dish after toasting so they don’t continue to cook in the hot pan. when ready to fry, pour the chicken into a colander over a bowl to drain off some of the excess marinade. you can discard the drained marinade. in a heavy pan or wok, heat peanut oil to 375 degrees f. heat oven to warm to hold cooked chicken between batches. fry wet chicken pieces in four batches to maintain the oil temperature, moving cooked chicken with a spider or strainer to a pan covered in paper towels. to fry, use tongs and quickly place one piece at a time into hot oil, not letting the pieces touch each other. each batch will take about 3-4 minutes. let the oil come back to 375 degrees f before starting the next batch. keep cooked chicken in warm oven between batches. once all the chicken is cooked, place warm cooked chicken pieces in a large bowl and toss with the hot sauce. add in the toasted sesame seeds and toss again, saving a little to sprinkle over the finished dish. serve on a platter or in a bowl with the reserved sesame seeds sprinkled over the dish and garnish with slivered scallions. serve with the cooked white rice on the side.  "},{"id":"shawarma-couscous-bowls","title":"Shawarma Couscous Bowls","description":"","image":"","servings":"","categories":[],"source":{"label":"","url":""},"editPath":"data/recipes-md/shawarma-couscous-bowls.md","ingredientCount":19,"stepCount":1,"search":"shawarma couscous bowls    1/4 red onion, finely sliced 2.5 oz couscous 1oz dried apricot, diced small 1 tbs butter or ghee 1 bell pepper or about 2-4 mini peppers, sliced ~9 oz or 4 carrots, cut at a bias 1 can or about 14 oz chickpeas small handful cilantro, chopped lemon juice 1 tbs sour cream 1 tbs yogurt harissa powder 1 tsp garlic powder or onion powder salt pinch sugar 2 tsp shawarma mix pepper bouillon 3/4c water slice onion finely\nsoak onion in squeeze of lemon juice, pinch of salt and pinch of sugar\nset aside\nweigh out couscous, set aside\ndice apricots, slice peppers, cut carrots at bias, rinse and dry chickpeas\nprepare sauce-- 1tbs yogurt, 1tbs sour cream, squeeze lemon, harissa, some water (1tsp at atime), salt, pepper\ntoss chickpeas, carrots, and peppers in oil,\ntoss chickpeas and carrots in 1 tsp shawarma spice blend each\ncook in oven at 375f ~ 20 minutes\ncook in air fryer 350f ~ 20 minutes\nmelt butter/ghee low med heat\nwhen melted, add couscous and toss in butter until lightly browned (2-4 minutes)\nonce toasted, add some bouillon, 3/4 cup water, and onion or garlic powder\nbring to boil\nonce boiling, place heat on low/simmer, and cover\ncook couscous until done (6-10 minutes)\nonce couscous is done, add diced apricot, stir\nplate.\nplace couscous, then chickpeas and veggies, then sauce, cilantro and pickled onions  "},{"id":"shawarma-spice","title":"Shawarma Spice","description":"","image":"","servings":"","categories":[],"source":{"label":"","url":""},"editPath":"data/recipes-md/shawarma-spice.md","ingredientCount":8,"stepCount":1,"search":"shawarma spice    cut in half for less chicken 1/2 cup extra virgin olive oil 1⁄4 1 large onion, cut into small dice (or 1tbsp onion powder) 1⁄2 1 tablespoon ras el hanout 1⁄2 1 teaspoon sweet smoked paprika 1⁄2 ~1 teaspoon kosher salt 1⁄2 1/2 cup roughly chopped cilantro, stems included (or 1/4cup dried cilantro) 1⁄4 2 tablespoons harissa 1 - good amount for: 1lb meat + 8 extra large eggs + 30oz tomatoes + bread. or use necessary amount for other meats and vegetables ras al hanuwt: www.amazon.com/dp/b07yvjqmnv/ harissa: www.amazon.com/dp/b00cb5ehag/ "},{"id":"snickerdoodles-with-icing","title":"Snickerdoodles with icing","description":"","image":"","servings":"many","categories":[],"source":{"label":"","url":""},"editPath":"data/recipes-md/snickerdoodles-with-icing.md","ingredientCount":23,"stepCount":1,"search":"snickerdoodles with icing  many  125g cake flour + 120g ap + 125g bread flour 7g cream of tartar 5g baking soda 2g baking powder - or a big pinch, half teaspoon 1/2 tsp kosher salt 300g granulated sugar + molasses (try 200-250g) 1/2 cup unsalted butter at room temperature 1/2 cup butter flavored shortening 1 large egg 1 egg yolk 1 1/2 teaspoons vanilla extract some cinnamon cinnamon sugar topping: 3 tablespoons granulated sugar 3 teaspoons ground cinnamon 2 tablespoons turbinado sugar oven: 350 time: 8-10 mins icing ~250g powdered sugar ~1/2 vanillin sugar packet ~tbs corn syrup -as much cream as needed -pinch of salt combine dry ingredients + cinnamon\nwhisk\ncombine (mixer) sugar with butter + molasses\nadd egg + egg yolk\nadd vanilla\nadd dry to wet and mix until combined\nchill in fridge\nroll into balls\ncoat with topping\nbake ~10 minutes\ncool\nicing  "},{"id":"sugar-toasted-almond-slices","title":"Sugar Toasted Almond Slices","description":"","image":"","servings":"","categories":[],"source":{"label":"","url":""},"editPath":"data/recipes-md/sugar-toasted-almond-slices.md","ingredientCount":4,"stepCount":1,"search":"sugar toasted almond slices    1 cups almond slices 2 tablespoons sugar (or more) 1 dash salt 1 tbsp butter med heat on induction burner\nmelt butter\nadd nuts \u0026 sugar \u0026 salt\ntoast until desired toastiness  "},{"id":"tahini","title":"tahini","description":"","image":"","servings":"","categories":[],"source":{"label":"","url":""},"editPath":"data/recipes-md/tahini.md","ingredientCount":5,"stepCount":1,"search":"tahini    130-ish g tahini paste ( this strongly depends on your brand) 8g or 1 to 1.5 tsp salt 1/2 lemon juiced or 15g 60-75g water more than this 1/2 garlic clove (sliced) -  "},{"id":"thumbprint-cookies","title":"Thumbprint Cookies","description":"","image":"images/thumbprint_cookies_rnwno.jpg","servings":"","categories":[],"source":{"label":"https://foodwishes.blogspot.com/2018/12/thumbprint-cookies-great-grandma-mitzi.html","url":"https://foodwishes.blogspot.com/2018/12/thumbprint-cookies-great-grandma-mitzi.html"},"editPath":"data/recipes-md/thumbprint-cookies.md","ingredientCount":8,"stepCount":1,"search":"thumbprint cookies    1 stick (1/2 cup) soft unsalted butter 1/3 cup powdered sugar (not sifted) 1 large egg yolk 1 teaspoon vanilla extract 1/4 teaspoon fine salt 1 1/4 cups all-purpose flour (5 ounces by weight) 1/2 cup fruit jam to fill centers 325 f. for 15 minutes combine powdered sugar with a little milk or water, and mix until you have a consistency that will hold its shape when piped.  https://foodwishes.blogspot.com/2018/12/thumbprint-cookies-great-grandma-mitzi.html"},{"id":"tuscan-heat-spice","title":"Tuscan Heat Spice","description":"","image":"","servings":"","categories":[],"source":{"label":"","url":""},"editPath":"data/recipes-md/tuscan-heat-spice.md","ingredientCount":6,"stepCount":1,"search":"tuscan heat spice    4 parts dried basil 2 parts dried rosemary 2 parts dried oregano 2 parts garlic powder 1 part cayenne pepper [7.5 k (hu)] 1 part ground fennel -  "},{"id":"vegetable-side","title":"vegetable side","description":"mixed veggies","image":"","servings":"like 4?","categories":[],"source":{"label":"","url":""},"editPath":"data/recipes-md/vegetable-side.md","ingredientCount":3,"stepCount":1,"search":"vegetable side mixed veggies like 4?  halved fresh green beans, frozen corn, sliced red onion, julienned carrots, circled (cut) sweet peppers, lemon juice, salt, msg, pepper, parmesan cheese measurements (whatever looks right) cut veggies (including\ncook green beans in oil a couple minutes before the rest\nadd rest of veggies\ncook until browning appears\nonce almost done, add parm and stir together green bean veggie side "},{"id":"vegetable-soup-with-lentils-seasonal-greens","title":"Vegetable Soup with Lentils \u0026 Seasonal Greens","description":"","image":"images/vegetable_soup_with_lentils_amp_seasonal_1klt3.jpg","servings":"6","categories":[],"source":{"label":"","url":""},"editPath":"data/recipes-md/vegetable-soup-with-lentils-seasonal-greens.md","ingredientCount":18,"stepCount":5,"search":"vegetable soup with lentils \u0026 seasonal greens  6  3 tablespoons olive oil 1 small sweet onion, chopped 4 cloves garlic, minced 1 small leek, cleaned and sliced (white and light green parts only) 2 stalks celery, sliced 4 medium carrots, peeled and sliced 1 cup butternut squash, chopped into 1/2-inch cubes (*see notes) 3/4 cup french lentils, rinsed and drained 4 cups 32-ounces no / low-salt vegetable stock or broth 14 ounce can chopped canned tomatoes, low salt 2 tablespoons tomato paste 1 pound baby bok choy, greens cut as a chiffonade, white parts added with the carrots and other vegetables (*see notes) 1/2 cup fresh parsley, chopped 1 tablespoon fresh thyme, chopped sea salt and fresh ground pepper 1/2 teaspoon smoked paprika 1/4 teaspoon cayenne pepper add any extra veggies : like mushrooms and green beans drizzle the olive oil in a large soup pot or dutch oven with a heavy bottom. heat on medium until hot. add the chopped onion and garlic and sauté until the onion is softened. before chopping, broil carrots and squash in oven in olive oil and paprika \u0026 cayenne. add the leek, celery, carrots, butternut squash, white portion of the bok choy and the lentils. stir gently to coat all vegetables in the olive oil then add the vegetable stock and chopped tomatoes. season with salt and pepper. cover the pot with a lid and gently simmer for about 15 minutes. add the tomato paste, chopped greens, parsley and thyme. heat until the greens are just tender. garnish with fresh parsley and black pepper. serve with a hearty whole grain bread if desired. the soup is easily adaptable by substituting rutabaga or turnips for the butternut squash. use seasonal greens such as swiss chard, kale, cabbage or spinach in place of the bok choy if desired. be sure to cut vegetables about the same size so they will cook more evenly. image of soup contains added yellow squash and zucchini + mushrooms** "},{"id":"wonton-soup","title":"Wonton soup","description":"","image":"","servings":"","categories":[],"source":{"label":"","url":""},"editPath":"data/recipes-md/wonton-soup.md","ingredientCount":21,"stepCount":10,"search":"wonton soup    1 lb ground chicken 6-10 cups chicken broth (used bouillon) 1 pkg shiitake mushrooms 1 bok choy 1 bunch green onion 2 ish tbs minced ginger 2-4 cloves minced garlic 1 tbs sherry vinegar 1/4 tsp sesame oil 1tbs soy sauce chili crisp oil kombu umami mushroom powder sesame seeds wonton wrappers 2 block of tofu for topping marinated in hoisin and soy sauce (about 1-2 tbs each) homemade wontons: recipe is 1.5x 375g / bread flour or half ap and bread flour ~200 ml / water pinch salt wontons\nmix ingredients\nrest/can rest in fridge up to whole day or so\nuse pasta roller to get thin enough\ncut into squares marinate tofu overnight first! brown mushrooms mix ground chicken, 3 finely minced/chopped green onions, soy sauce, sesame oil, sesame seeds, some chili oil, garlic, ginger, sherry vinegar, little bit of broth,shake of umami mushroom powder kombu stock: 3 cup of cold water, 1 sheet of kombu. sit for 10 minutes.\nheat gently to 140f, turn off heat and set for 2 minutes, then extract kombu stock: browned shitake @ 4\n(kombu stock made with 3cup water)\n1 tbsp of chili crisp add more water, add chopped whites of bok choy \u0026 rest of green onions\nsimmer for a while add green parts of bok choy wrap chicken mixture in wonton wrappers while broth simmers\nbring broth to boil and add wontons cook 3 minutes  "},{"id":"yellow-halal-cart-rice-garlicky-lemony-one","title":"yellow halal cart rice (garlicky lemony one)","description":"","image":"","servings":"","categories":[],"source":{"label":"","url":""},"editPath":"data/recipes-md/yellow-halal-cart-rice-garlicky-lemony-one.md","ingredientCount":8,"stepCount":1,"search":"yellow halal cart rice (garlicky lemony one)    1 cup rice 2 cups water 1 tbs bouiilon 1 tsp garlic powder or less 1/2 tbs ghee pinch smoked paprika dash of msg lemon juice mix water and spices and ghee, mix more when melted\nwhen done, squeeze lemon juice over rice and fluff together  "}]};
window.RECIPE_DATA = [{"id":"4-ingredient-vegan-date-caramel-sauce","title":"4-Ingredient Vegan Date Caramel Sauce","description":"","source":{"label":"https://plantbasedonabudget.com/homemade-caramel-sauce/","url":"https://plantbasedonabudget.com/homemade-caramel-sauce/"},"image":"images/4_ingredient_vegan_date_caramel_sauce_uy5y4.jpg","servings":"8 -10","categories":[],"ingredients":[{"type":"item","text":"10 Medjool dates"},{"type":"item","text":"1⁄2 cup full-fat coconut milk from a can"},{"type":"item","text":"4 tablespoons maple syrup"},{"type":"item","text":"1⁄4 teaspoon cinnamon"},{"type":"item","text":"4 tablespoons reserved water from the dates"}],"instructions":[{"type":"step","text":"Fill a saucepan with water just enough to cover the dates. Gently boil dates for 10 minutes."},{"type":"step","text":"Drain, reserving 4 tablespoons of the water. Let sit until cool to the touch. Peel and pit the dates. Chop the dates and toss them in a blender with the full-fat coconut milk, maple syrup, cinnamon, and reserved water. Blend until super smooth, about 2 or 3 minutes."},{"type":"step","text":"Pour the sauce back into the saucepan and bring to a boil, then simmer for about 5 minutes, or until it thickens."}],"notes":["Optional Add-ins and Variations:","Sea Salt: A pinch of salt will enhance all the flavors in the vegan caramel sauce. Add more, and you have yourself delicious vegan salted caramel.","Vanilla extract: A few drops of natural vanilla extract tastes fantastic in this healthy vegan caramel recipe.","Caramel extract: To further enhance the caramel flavor, add a few drops of natural caramel extract.","Coconut oil: For super silky caramel, swap out the reserved water for melted coconut oil.","Nut/seed butter: For an even more decadent non-dairy caramel, you could add a tablespoon of your favorite nut butter or seed butter. We recommend using tahini, cashew butter, almond butter, or sunflower seed butter. Peanut butter is a little too strong in the vegan date caramel."],"extra":""},{"id":"a-recipe-for-brioche-with-raisins-not-yet-tried-read","title":"A Recipe for Brioche with Raisins--not yet tried/read","description":"","source":{"label":"https://www.moroccoworldnews.com/2013/05/92644/moroccan-pastry-a-recipe-for-brioche-with-raisins-2","url":"https://www.moroccoworldnews.com/2013/05/92644/moroccan-pastry-a-recipe-for-brioche-with-raisins-2"},"image":"images/read_acci7.jpg","servings":"","categories":[],"ingredients":[{"type":"heading","text":"For the dough:"},{"type":"item","text":"500g white flour."},{"type":"item","text":"50g butter."},{"type":"item","text":"1 egg."},{"type":"item","text":"60g sugar."},{"type":"item","text":"2 tbsp powder milk."},{"type":"item","text":"15g baking yeast."},{"type":"item","text":"1 baking powder."},{"type":"heading","text":"For the custard ( crème patissiére):"},{"type":"item","text":"2 cups milk."},{"type":"item","text":"1 egg."},{"type":"item","text":"2 tbsp sugar."},{"type":"item","text":"1tsp vanilla."},{"type":"item","text":"20g flour or cornflower (cornstarch)."},{"type":"item","text":"100g raisin for garnish."}],"instructions":[{"type":"heading","text":"Way of preparation:"},{"type":"heading","text":"The dough:"},{"type":"step","text":"In a big bowl, put the dry ingredients then add butter and mix well."},{"type":"step","text":"Add an egg and warm water little by little then knead well until the dough is smooth and cohesive."},{"type":"step","text":"Let the dough rest for an hour in the refrigerator. (It’s better to keep it in the fridge for the whole night)"},{"type":"step","text":"You can use puff pastry."},{"type":"heading","text":"The custard:"},{"type":"step","text":"Mix an egg with sugar, vanilla and cornflower."},{"type":"step","text":"In a saucepan, boil milk then add it to the first mixture and mix well."},{"type":"step","text":"Put the mixture on a low heat and keep stirring until we get a thick cream."},{"type":"step","text":"Put the cream in refrigerator."},{"type":"step","text":"Make two balls from the dough and flatten them with a rolling pin."},{"type":"step","text":"Spread custard on the surface and sprinkle raisins on the top then roll the dough."},{"type":"step","text":"Cut the rolling dough into circles (you can put the rolling dough in the freezer for an hour to keep its shape while cutting)"},{"type":"step","text":"Place brioche in an oven tray and brash them with a whipped egg then sprinkle some almonds flakes or ground almonds on the top. (Optional)"},{"type":"step","text":"Bake it in a pre heated oven for 25 to 30 minutes."},{"type":"step","text":"After baking you can brush the brioche with jam."},{"type":"step","text":"Serve with tea!"}],"notes":[],"extra":""},{"id":"all-around-seasoning-mix","title":"All-Around Seasoning Mix","description":"","source":{"label":"https://www.tasteofhome.com/recipes/all-around-seasoning-mix/","url":"https://www.tasteofhome.com/recipes/all-around-seasoning-mix/"},"image":"images/all_around_seasoning_mix_6m1hz.jpg","servings":"","categories":[],"ingredients":[{"type":"item","text":"1/2 cup paprika"},{"type":"item","text":"3 tablespoons onion powder"},{"type":"item","text":"3 tablespoons garlic powder"},{"type":"item","text":"3 tablespoons cayenne pepper"},{"type":"item","text":"2 tablespoons white pepper"},{"type":"item","text":"2 tablespoons pepper"},{"type":"item","text":"4 teaspoons salt"},{"type":"item","text":"4 teaspoons dried thyme"},{"type":"item","text":"4 teaspoons dried oregano"},{"type":"item","text":"4 teaspoons ground cumin"},{"type":"item","text":"4 teaspoons chili powder"}],"instructions":[{"type":"step","text":"In a small bowl, combine all ingredients. Store in an airtight container in a cool, dry place for up to 6 months."}],"notes":["ALL-PURPOSE SEASONING TIPS","What is all-purpose seasoning?"],"extra":""},{"id":"almond-crescent-cookies","title":"Almond Crescent Cookies","description":"","source":{"label":"","url":""},"image":"","servings":"","categories":[],"ingredients":[{"type":"item","text":"all purposes flour 2 Cups +2 tbs"},{"type":"item","text":"Roasted Crushed almond 1 Cup"},{"type":"item","text":"180 g butter + shortening (90g each)"},{"type":"item","text":"powdered sugar 4 tbsp"},{"type":"item","text":"vanilla 1 tbsp"},{"type":"item","text":"baking powder 1tbsp"},{"type":"item","text":"1 egg"},{"type":"item","text":"salt"}],"instructions":[{"type":"step","text":"whisk vanillin sugar, flour, crushed almonds, baking powder, salt\nadd in butter + shortening with hands\nadd in egg with hands\nroll out and cut\nbake ~ 8-11 minutes"}],"notes":[],"extra":""},{"id":"anko","title":"Anko","description":"","source":{"label":"","url":""},"image":"","servings":"","categories":[],"ingredients":[{"type":"item","text":"400g bean"},{"type":"item","text":"360g sugar"},{"type":"item","text":"half stick butter"},{"type":"item","text":"tablespoon of molasses"},{"type":"item","text":"tablespoon of corn syrup w/ vanilla"},{"type":"item","text":"teaspoon of salt"},{"type":"item","text":"teaspoon of pectin"}],"instructions":[{"type":"step","text":"rinse beans or soak\nuse good water for first \"brew/boil\"\ncover beans with good water in pot\nbring to boil, reduce heat for 10minutes (or until water turns tea coloured)\nstrain off water for tea, add sugar\nadd beans back into pot, cover with an inch of water\nbring to boil, reduce heat, simmer 40 minutes- 2 hours until beans tender to when mashing\nstrain beans through sieve with warmish water, let settle and then do again after pouring off excess liquid/water"}],"notes":[],"extra":""},{"id":"banana-with-carrot-bread","title":"Banana (with carrot) Bread","description":"banana bread with crushed candied walnuts, candied shredded carrot, topped with chopped pecans","source":{"label":"","url":""},"image":"","servings":"","categories":[],"ingredients":[{"type":"item","text":"3 ripe bananas"},{"type":"item","text":"2 cups all-purpose flour"},{"type":"item","text":"1 tsp salt"},{"type":"item","text":"1 tsp baking powder"},{"type":"item","text":"1 tsp baking soda"},{"type":"item","text":"2 TBS hemp hearts"},{"type":"item","text":"2TBS wheat germ"},{"type":"item","text":"1/2 cup soft butter"},{"type":"item","text":"3/4 cup sugar \u0026 molasses +1/4-1/2 cup sugar for nuts"},{"type":"item","text":"2 large eggs"},{"type":"item","text":"1/4 tsp vanilla/some vanilla bean"},{"type":"item","text":"1 tbsp milk/milk powder"},{"type":"item","text":"1 cup chopped walnuts"},{"type":"item","text":"1 cup shredded carrots"},{"type":"item","text":"chopped pecans"}],"instructions":[{"type":"step","text":"Candied walnuts\n1 cup chopped walnuts\n2-3 TBS butter\n1/4-1/2 cup white sugar\ndash salt\nsome water\ncook low-med heat for a few minutes, lay out on parchment"},{"type":"step","text":"Candied shredded carrots\n1-3 TBS butter\n1/4-1/2 Cup white sugar\ndash salt\nsome molasses\nsome water\n(forgot to add) dash cinnamon"},{"type":"step","text":"Whisk flour, baking soda, baking powder, salt, hemp hearts, \u0026 wheat germ, set aside\nMash bananas, set aside\nCream soft butter with sugar using spatula\nAdd banana mash to butter mix and whisk until combined\nAdd eggs, 1 at a time\nAdd vanilla \u0026 milk\nAdd candied carrots \u0026 candied walnuts\nAdd flour, mix with spatula gently, lightly folding"},{"type":"step","text":"Spray loaf pan(s)\nFill (used small loaf trays) 1/2-3/4 of the way\nSprinkle with chopped pecans"},{"type":"step","text":"Bake at 350F for 15 minutes\nLower temperature to 325F for about 10 minutes or until center of bread reads 200F"}],"notes":[],"extra":""},{"id":"banana-cake","title":"Banana Cake","description":"Recipe by (Betty) Lynette Meeks","source":{"label":"","url":""},"image":"","servings":"","categories":[],"ingredients":[{"type":"item","text":"3/4 cup butter/shortening (half and half)"},{"type":"item","text":"2.5 cups sugar"},{"type":"item","text":"3 eggs"},{"type":"item","text":"1.5 cups mashed bananas"},{"type":"item","text":"3 cups sifted flour (half cake half all purpose)"},{"type":"item","text":"3/4 tsp baking powder"},{"type":"item","text":"1/3 cup buttermilk"},{"type":"item","text":"1 tsp baking soda"},{"type":"item","text":"1 tsp salt"},{"type":"item","text":"1.5 tsp vanilla"},{"type":"item","text":"For Frosting"},{"type":"item","text":"1.5 box (cups?) (~ half a bag) (bag = 2lb or 907g) powdered sugar"},{"type":"item","text":"3/4 cup (1.5 sticks) butter"},{"type":"item","text":"3/4 cup mashed bananas"},{"type":"item","text":"1.5 tsp lemon juice"}],"instructions":[{"type":"step","text":"Cream together shortening, butter, and sugar, blending well.\nAdd well beaten eggs and bananas, beat well\nSift flours then resift with dry ingredients\nAdd dry alternatively with wet mixture of buttermilk and vanilla combined"},{"type":"step","text":"In greased, floured pans bake at 350F for about 25 minutes or until done\nRemove from pan and cool"},{"type":"step","text":"For Frosting\nCream all ingredients together\nSpread onto cooled cake"}],"notes":[],"extra":"I made this."},{"id":"biscuits","title":"Biscuits","description":"","source":{"label":"","url":""},"image":"images/biscuits_o0yew.jpg","servings":"","categories":[],"ingredients":[{"type":"heading","text":"Parts:"},{"type":"item","text":"1) tangzhong mix"},{"type":"item","text":"2) biscuit mix"},{"type":"item","text":"3) buttermilk biscuit top-wash"},{"type":"heading","text":"1) Tangzhong Mix:"},{"type":"item","text":"2 tablespoons bread flour"},{"type":"item","text":"2 tablespoons water"},{"type":"item","text":"4 tablespoons whole milk (or: 1 1/3 tbsp of DRY milk + 8 tablespoons of water)"},{"type":"heading","text":"2) Biscuit Mix:"},{"type":"item","text":"1 cup of all purpose flour"},{"type":"item","text":"1 cup of bread flour"},{"type":"item","text":"1 tbsp baking powder"},{"type":"item","text":"1/2 tsp baking soda"},{"type":"item","text":"3/4 tsp salt"},{"type":"item","text":"1/2 package of instant rapid rise yeast"},{"type":"item","text":"1 tbsp sugar"},{"type":"item","text":"5Tbsp of unsalted butter, VERY cold"},{"type":"item","text":"1/4 cup of DRY cultured buttermilk"},{"type":"item","text":"1 cup of water"},{"type":"item","text":"cooked, room temperature tangzhong"},{"type":"heading","text":"3) buttermilk biscuit top-wash:"},{"type":"item","text":"butter (1tbsp) and buttermilk (from dry, totaling about 1/3 cup) for brushing top of biscuits before placing into oven"}],"instructions":[{"type":"heading","text":"Instructions:"},{"type":"step","text":"•Empty the ingredients for Tangzhong Mix into a frying pan."},{"type":"step","text":"•Cook, stirring constantly until looks like sticky mashed potatoes (about 1min@ medium heat)."},{"type":"step","text":"•Let cooked tangzhong sit to room temperature"},{"type":"step","text":"•Meanwhile in a separate bowl, combining the dry ingredients of the Biscuit Mix."},{"type":"step","text":"•Add cooked and cool tangzhong to dry biscuit mix, along with five tablespoons of cut unsalted butter, and 1 cup of cool water."},{"type":"step","text":"•Sit to rise at leas 1-2 hours after lightly folding"},{"type":"step","text":"•Mix gently, basic incorporation. Do not over knead or overmix."},{"type":"step","text":"•Put mix on floured surface, gently fold into layers for about 5 minutes"},{"type":"step","text":"•Cut into 3” biscuits about 1/2” to 1” desired thickness (1” preferable)."},{"type":"step","text":"•Let rise 1 hour"},{"type":"step","text":"•After biscuits are cut, let rise at room temperature for one hour, then chill for at least 15 minutes."},{"type":"step","text":"•For best biscuits -- prior to folding, cutting and rise; let dough rise in refrigerator for at least 4 days."},{"type":"step","text":"•Cover dough with 2-3Tbsp melted butter before refrigeration and keep dough airtight."},{"type":"step","text":"•Brush tops with buttermilk top-wash before putting in oven."},{"type":"step","text":"•Bake @ 400F for around 5-10 minutes until tops are golden crispy"}],"notes":[],"extra":""},{"id":"blueberry-muffins","title":"blueberry muffins","description":"by Sugar Spun Run","source":{"label":"","url":""},"image":"","servings":"","categories":[],"ingredients":[{"type":"item","text":"▢1 3⁄4 cup all-purpose flour (220g)"},{"type":"item","text":"▢1 cup granulated sugar (100-200g)(less)"},{"type":"item","text":"▢2 Tablespoons cornstarch"},{"type":"item","text":"▢2 teaspoons baking powder"},{"type":"item","text":"▢1⁄2 teaspoon baking soda"},{"type":"item","text":"▢1⁄2 teaspoon salt"},{"type":"item","text":"▢1⁄4 cup unsalted butter melted (60ml)"},{"type":"item","text":"▢1⁄4 cup canola oil (60ml)(1/2 avocado 1/2 veg oil)"},{"type":"item","text":"▢1 large egg room temperature preferred"},{"type":"item","text":"▢1 teaspoon vanilla extract"},{"type":"item","text":"▢1 cup sour cream (240g)"},{"type":"item","text":"▢1 3⁄4 cup blueberries (245g) (fresh or frozen will work, if using frozen you do not need to thaw first, and note that they may leave purple streaks through your muffins)."},{"type":"item","text":"▢Coarse sugar for sprinkling optional (may just use regular granulated sugar or omit entirely)."}],"instructions":[{"type":"step","text":"Instructions for Air Fryer"},{"type":"step","text":"Preheat oven to 400F and line a 12 count muffin tin with paper liners."},{"type":"step","text":"In a medium-sized bowl, whisk together flour, sugar, baking powder, baking soda, cornstarch, salt."},{"type":"step","text":"In a separate bowl whisk together butter and canola oil. Add egg and vanilla.\nStir in sour cream until thoroughly combined."},{"type":"step","text":"Add wet ingredients to dry and gently fold together with a spatula until mostly combined.\nOnce the batter is about 75% combined, add the blueberries and fold them in as well until batter is completely combined (don’t over-mix!)."},{"type":"step","text":"Evenly divide muffin batter into prepared tin/silicon liner. Liners will be most of the way full!\ntop with streusel topping or thick sugar"},{"type":"step","text":"Transfer to 400F (215C) preheated oven and bake for 5 minutes."},{"type":"step","text":"After 5 minutes reduce the oven temperature to 310F (175C) without opening oven door,\nthen continue baking 8-10 minutes"},{"type":"step","text":"(or until the tops are beginning to turn golden brown and a toothpick inserted in the center comes out clean or with a few moist crumbs)"},{"type":"step","text":"Allow to cool 10 minutes and allow to cool completely on a cooling rack (otherwise muffin bottoms may become soggy).\nEnjoy!"},{"type":"step","text":"streusel (use half this for whole recipe)"},{"type":"step","text":"▢1⁄2 cup all-purpose flour (60g)\n▢1⁄2 cup granulated sugar (100g)\n▢1⁄4 cup unsalted butter (56g)\n▢1 pinch salt"}],"notes":[],"extra":"I made this."},{"id":"bonnie-s-my-complete-seasoning-spice-mix","title":"Bonnie's My Complete Seasoning Spice Mix","description":"","source":{"label":"https://www.justapinch.com/recipes/sauce-spread/marinade/my-complete-seasoning.html","url":"https://www.justapinch.com/recipes/sauce-spread/marinade/my-complete-seasoning.html"},"image":"images/bonnie39s_my_complete_seasoning_spice_mi_htiss.jpg","servings":"","categories":[],"ingredients":[{"type":"item","text":"3 tablespoons salt"},{"type":"item","text":"1 tablespoon paprika"},{"type":"item","text":"1 tablespoon onion powder"},{"type":"item","text":"1 tablespoon garlic powder"},{"type":"item","text":"1/2 tablespoon white pepper"},{"type":"item","text":"1 1/2 teaspoon ground thyme"},{"type":"item","text":"3/4 teaspoon black pepper"},{"type":"item","text":"1/2 teaspoon ground oregano"},{"type":"heading","text":"optional:"},{"type":"item","text":"1 tablespoon cayenne for latin dishes"}],"instructions":[{"type":"step","text":"-"}],"notes":[],"extra":""},{"id":"brioche","title":"Brioche","description":"","source":{"label":"","url":""},"image":"images/brioche_xpvra.jpg","servings":"","categories":[],"ingredients":[{"type":"item","text":"poolish (150g bread flour + 150g water + pinch yeast)"},{"type":"item","text":"tangzhong (2 Tbs water, 4 Tbs milk, 2 Tbs bread flour)"},{"type":"item","text":"125ml milk"},{"type":"item","text":"20ml water"},{"type":"item","text":"10g bread machine yeast"},{"type":"item","text":"1 large egg"},{"type":"item","text":"1 egg yolk"},{"type":"item","text":"375g bread flour"},{"type":"item","text":"7g salt"},{"type":"item","text":"4g amylase"},{"type":"item","text":"60g sugar"},{"type":"item","text":"50g softened butter"},{"type":"item","text":"50g butter flavored shortening"},{"type":"item","text":"melted butter"},{"type":"item","text":"triple-seed-topping (hemp hearts, wheat germ, black seeds)"},{"type":"item","text":"flakey salt"}],"instructions":[{"type":"step","text":"Combine water and milk in a small bowl, whisk in yeast to dissolve, place in a stand mixer bowl along with the whole egg and egg yolk; and the tangzhong and ripened poolish; mix on low speed, until combined."},{"type":"step","text":"In a separate bowl, mix flour, sugar, salt, and amylase.\nWhile mixing (by hand or stand mixer), add in your flour mixture, 1⁄4 cup at a time, until all of your flour has been added."},{"type":"step","text":"Once it begins to form a rough dough, allow to knead for 2 minutes or until it begins to turn smooth.\nThen add your butter, allow to mix until fully incorporated, and knead for 5-10 more minutes or till your dough is very smooth and begins to pull from the sides of the bowl."},{"type":"step","text":"Cover with plastic wrap and rise for 45 minutes at room temperature. Then place in the fridge for 1.5 hours and up to overnight."},{"type":"step","text":"Separated into 94g portions, let rise for an hour at room temperature.\nSpray with Pam, brush with egg wash + top with black seed.\nThen bake @ 375F (maybe start at 380-385F at first) until golden brown.\nImmediately top with melted butter and flakey salt."}],"notes":[],"extra":"I made this."},{"id":"buttery-chewy-sugar-cookies","title":"Buttery Chewy Sugar Cookies","description":"from handletheheat.com","source":{"label":"","url":""},"image":"","servings":"","categories":[],"ingredients":[{"type":"item","text":"21⁄2 cups (318 grams) all-purpose flour"},{"type":"item","text":"2 teaspoons baking powder"},{"type":"item","text":"3/4 teaspoon fine sea salt"},{"type":"item","text":"2 sticks (226 grams) unsalted butter, at cool room temperature"},{"type":"item","text":"11⁄4 cups (250 grams) granulated sugar, plus 1⁄4 cup (50 grams) for rolling"},{"type":"item","text":"1 large egg plus 1 egg yolk"},{"type":"item","text":"1 teaspoon vanilla extract"}],"instructions":[{"type":"step","text":"Preheat the oven to 350°F(May need to be lowered halfway to 340F).\nLine baking sheets with parchment paper.\nIn a medium bowl, whisk together the flour, baking powder, and salt to combine.\nIn a large bowl, use an electric mixer fitted with a paddle attachment on medium-high speed to beat the butter and 11⁄4 cups sugar until light and fluffy, 2 to 3 minutes. Add the egg, egg yolk, and vanilla, and beat until combined. Slowly beat in the flour mixture."},{"type":"step","text":"Place the remaining 1/4 cup sugar in a shallow dish. Using a large (3-tablespoon) (OR just small cookies) spring-loaded scoop, divide the dough into balls, then roll in sugar to coat evenly. Place the dough balls on the prepared baking sheets, spacing 2 inches apart, and flatten slightly with the bottom of a measuring cup."},{"type":"step","text":"Bake for 10 to 12 minutes, or until the cookies set and begin to brown. Cool for 5 minutes before removing to a wire rack to cool completely. Cookies can be stored in an airtight container at room temperature for up to 3 days."}],"notes":[],"extra":""},{"id":"cajun-chicken","title":"Cajun chicken","description":"","source":{"label":"","url":""},"image":"","servings":"","categories":[],"ingredients":[{"type":"item","text":"works for 2.5 lbs"},{"type":"item","text":"use salt to make tender"},{"type":"heading","text":"marinade:"},{"type":"item","text":"1 cup buttermilk"},{"type":"item","text":"1 teaspoon herbs de province"},{"type":"item","text":"1Tablespoon garlic"},{"type":"item","text":"1 teaspoon cajun (walmart brand square)"},{"type":"heading","text":"flour mix:"},{"type":"item","text":"1.25 cup all purpose flour"},{"type":"item","text":"4 Tablespoons panko"},{"type":"item","text":"4 Tablespoons corn starch"},{"type":"item","text":"OR"},{"type":"item","text":"1.75 cup rice flour"},{"type":"heading","text":"flour seasoning:"},{"type":"item","text":"1 teaspoon baking powder"},{"type":"item","text":"1 teaspoon sugar"},{"type":"item","text":"pinch white pepper"},{"type":"item","text":"1/2 teaspoon onion powder"},{"type":"item","text":"1 Tablespoon+ 1 teaspoon cajun"},{"type":"item","text":"1/2 teaspoon parsley"}],"instructions":[{"type":"step","text":"-"}],"notes":[],"extra":""},{"id":"cheese-danish","title":"Cheese Danish","description":"","source":{"label":"https://cooking.nytimes.com/recipes/1017898-cheese-danish","url":"https://cooking.nytimes.com/recipes/1017898-cheese-danish"},"image":"images/cheese_danish_b9cno.jpg","servings":"9 pastries","categories":[],"ingredients":[{"type":"item","text":"8 ounces/226 grams cream cheese"},{"type":"item","text":"1 1⁄4 cup/160 grams confectioners’ sugar"},{"type":"item","text":"1 large egg yolk"},{"type":"item","text":"Pinch of salt"},{"type":"item","text":"1⁄2 teaspoon pure vanilla extract"},{"type":"item","text":"1 batch Danish dough ( see recipe)"},{"type":"item","text":"1 large egg, lightly beaten"},{"type":"item","text":"2 tablespoons/30 milliliters whole milk"}],"instructions":[{"type":"step","text":"In a large bowl, beat together the cream cheese, 1/4 cup/32 grams confectioners’ sugar, the egg yolk, the salt and the vanilla until smooth. Transfer the mixture to a resealable plastic bag; set aside."},{"type":"step","text":"On a lightly floured surface, roll the dough out into a 12 1/2-inch square. Trim 1/4 inch off each edge. Cut the dough into nine 4-inch squares. Brush the corners of each square with a bit of the beaten egg, then fold each corner into the center and press down gently. Transfer the squares to 2 parchment-lined baking sheets."},{"type":"step","text":"Cut the tip off one corner of the filled plastic bag so you have a 1/2-inch hole. Use the bag to pipe the cheese filling onto the center of each dough square. Loosely cover the pastries with plastic wrap and let stand until slightly puffed, about 1 hour to 1 hour 20 minutes. Heat oven to 425 degrees."},{"type":"step","text":"Remove the plastic and gently brush the top and sides of the dough with the beaten egg. Bake for 10 minutes, then rotate the sheets and reduce oven temperature to 375 degrees. Continue to bake until pastries are puffed and deep golden brown, another 6 to 8 minutes."},{"type":"step","text":"Meanwhile, whisk together the remaining 1 cup/128 grams confectioners’ sugar and the milk. Let the Danish cool slightly on the sheet then drizzle with the glaze. Serve warm or at room temperature."}],"notes":[],"extra":""},{"id":"chicken-and-dumplings","title":"Chicken and Dumplings","description":"","source":{"label":"","url":""},"image":"","servings":"large crock pot","categories":[],"ingredients":[{"type":"item","text":"large condensed cream of chicken"},{"type":"item","text":"14 chicken tenderloins"},{"type":"item","text":"1 cup flour"},{"type":"item","text":"1 cup self-rising flour (1 cup all purpose flour, 1.5 tsp baking powder, 1/4 tsp salt)"},{"type":"item","text":"1 cup ice water"},{"type":"item","text":"1 tbsp olive oil"},{"type":"item","text":"5-6 carrots"},{"type":"item","text":"some radishes"},{"type":"item","text":"MSG"},{"type":"item","text":"1/3 stick butter optional"},{"type":"item","text":"lima beans on side??/succotash?/corn \u0026 lima bean?"}],"instructions":[{"type":"step","text":"Coat chicken in chicken bouillon while sitting out at room temp\nPlace chicken in crock pot on high\nAdd can of cream of chicken (large)\nMix self-rising flour, all-purpose flour, cooking oil, and cold water (very sticky dough)\nPlace on surface coated in extra flour and work flour into dough until handleable\nRoll out and cut with pizza cutter into dumplings\nBoil\nAdd dumplings to chicken\nUsing same water from dumplings, boil sliced/chopped carrots until soft\nAdd carrots to crock pot\nMake a roux with flour, water, and stock from crock pot\nAdd roux to crock pot once all lumps are gone and flour is cooked\nAdd extra water to crock pot if needed\nStir together and let sit on low for 30-45 minutes?\nAdd MSG\nAdd butter if you want\nnutritional yeast\npeas?"}],"notes":[],"extra":"I made this."},{"id":"chicken-pinto-burrito","title":"chicken pinto burrito","description":"","source":{"label":"","url":""},"image":"","servings":"","categories":[],"ingredients":[{"type":"item","text":"2 boneless skinless chicken thighs (or breast)"},{"type":"item","text":"1 tbsp (14 grams) mayo"},{"type":"item","text":"Coarse kosher salt"},{"type":"item","text":"2 cloves garlic, crushed"},{"type":"item","text":"Lime zest"},{"type":"item","text":"1/2 juice lime"},{"type":"item","text":"Chile powder"},{"type":"item","text":"Mexican oregano (optional)"},{"type":"item","text":"10 cranks of black pepper"},{"type":"item","text":"Pinto Beans"},{"type":"item","text":"Drizzle of oil"},{"type":"item","text":"Jalapeno, diced"},{"type":"item","text":"Sprinkle of whole cumin seeds"},{"type":"item","text":"1 can pinto beans, drained"},{"type":"item","text":"Salt to taste"},{"type":"item","text":"Burrito Accoutrements"},{"type":"item","text":"Sour cream"},{"type":"item","text":"Thinly sliced lettuce"},{"type":"item","text":"Pickled onions"},{"type":"item","text":"Queso fresco"},{"type":"item","text":"Hot sauce"},{"type":"item","text":"Cilantro"}],"instructions":[{"type":"step","text":"Set a cast-iron pan over medium heat. Mix the mayo and spices into a bowl. Add the chicken and slather the marinade on the exterior."},{"type":"step","text":"Add the chicken to the pan and brown on each side, about 3-4 minutes per side. Cook until the internal temp is 160. Slice and enjoy."},{"type":"step","text":"Drizzle oil into a pan over medium-low heat. Add diced jalapeno and cumin seeds and cook until just fragrant, about 1 minute. Add the pintos and cook, while stirring for another 4-5 minutes."},{"type":"step","text":"Spread a thin layer of sour cream on the bottom which will act as a glue for the beans and provide even coverage of the sour cream instead of getting large gloops everywhere."},{"type":"step","text":"For rolling purposes, I find it best to position the fillings in the upper third. First, hit it with a layer of the seasoned beans. Now here is where I like to add hot sauce as an acidic layer. Follow this with a generous helping of the chicken then a sprinkle of queso fresco, the diced tomatoes minced cilantro, some shredded lettuce, and you better not forget the pickled onions. Check the video for how to roll!"}],"notes":[],"extra":""},{"id":"choc-cobbler","title":"choc cobbler","description":"","source":{"label":"","url":""},"image":"","servings":"","categories":[],"ingredients":[{"type":"item","text":"4 tablespoons butter"},{"type":"item","text":"80g flour"},{"type":"item","text":"1tsp baking powder"},{"type":"item","text":"pinch of salt"},{"type":"item","text":"100g white sugar"},{"type":"item","text":"1 tablespoons unsweetened cocoa powder"},{"type":"item","text":"1/3 cup milk"},{"type":"item","text":"1 teaspoon vanilla extract"},{"type":"item","text":"135g white sugar"},{"type":"item","text":"1/6 cup unsweetened cocoa powder"},{"type":"item","text":"1 cups boiling water"}],"instructions":[{"type":"step","text":"Preheat the oven to 350 degrees F (175 degrees C). Melt butter in an 8x8 inch baking dish while the oven preheats."},{"type":"step","text":"In a medium bowl, stir together the flour, baking powder, 100g sugar, and 1 tablespoons cocoa.\nStir in milk and vanilla until smooth. Spoon this batter over the melted butter in the baking dish."},{"type":"step","text":"Stir together the remaining 135g of sugar and 1/6 cup cocoa powder. Sprinkle over the batter.\nSlowly pour boiling water over the top of the mixture."},{"type":"step","text":"Bake for 30 minutes in the preheated oven, until set."}],"notes":[],"extra":""},{"id":"chocolate-cake","title":"chocolate cake","description":"","source":{"label":"","url":""},"image":"","servings":"","categories":[],"ingredients":[{"type":"item","text":"-"}],"instructions":[{"type":"step","text":"-"}],"notes":[],"extra":""},{"id":"chocolate-glaze","title":"chocolate glaze","description":"for donuts etc","source":{"label":"","url":""},"image":"","servings":"","categories":[],"ingredients":[{"type":"item","text":"1 TBS butter"},{"type":"item","text":"2 TBS shortening"},{"type":"item","text":"2 TBS cocoa"},{"type":"item","text":"2 TBS hot water +"},{"type":"item","text":"1/2 tsp vanillin sugar"},{"type":"item","text":"1 tsp milk powder"},{"type":"item","text":"1 cup powdered sugar"},{"type":"item","text":"for donuts add more powdered sugar + try corn syrup"}],"instructions":[{"type":"step","text":"melt butter + shortening\nmix in rest"}],"notes":["may have to heat up and whisk to get proper consistency"],"extra":""},{"id":"cinnabon-cinnamon-rolls-but-better","title":"Cinnabon Cinnamon Rolls (But Better)","description":"","source":{"label":"https://www.joshuaweissman.com/post/cinnabon-cinnamon-rolls-but-better","url":"https://www.joshuaweissman.com/post/cinnabon-cinnamon-rolls-but-better"},"image":"","servings":"","categories":[],"ingredients":[{"type":"heading","text":"Dough:"},{"type":"item","text":"4 cups (580g) all-purpose flour"},{"type":"item","text":"1/2 cup (107g) granulated sugar"},{"type":"item","text":"3/4 tsp (6g) fine sea salt"},{"type":"item","text":"1/3 cup (84g) butter (or half butter flavored crisco)"},{"type":"item","text":"1 cup (235g) lukewarm whole milk"},{"type":"item","text":"21/4 tsp (7g ) instant yeast"},{"type":"item","text":"2 eggs"},{"type":"item","text":"1 egg yolk"},{"type":"item","text":"4-5g amylase"},{"type":"heading","text":"Filling:"},{"type":"item","text":"1 cup (225g) brown sugar"},{"type":"item","text":"1 Tbsp (14g) muscovado sugar"},{"type":"item","text":"2.5 Tbsp (17g) cinnamon"},{"type":"item","text":"1/3 cup (84g) butter"},{"type":"heading","text":"Vanilla bean Cream Cheese Glaze:"},{"type":"item","text":"4 oz (115g) cream cheese"},{"type":"item","text":"3/4 (90g) cups powdered sugar"},{"type":"item","text":"1 vanilla bean"},{"type":"item","text":"3 Tbsp (45ml) whole milk"}],"instructions":[{"type":"step","text":"In a stand mixer bowl, whisk together all-purpose flour, granulated sugar, amylase, and fine sea salt."},{"type":"step","text":"Add in softened unsalted butter. Blend in using two forks."},{"type":"step","text":"In a separate container, whisk together lukewarm whole milk and instant yeast."},{"type":"step","text":"Using the dough hook attachment set on medium-low speed, add in yeast mixture, whole eggs, and egg yolk. Mix for 2-3 minutes."},{"type":"step","text":"On a lightly floured work surface and knead for 30-60 seconds. Plop into a greased bowl and cover with plastic wrap, let rise for 90 minutes."},{"type":"step","text":"Once dough is ready, mix together brown sugar, muscovado sugar, and cinnamon."},{"type":"step","text":"Dump dough out onto a lightly floured surface flattening it into a large rectangle."},{"type":"step","text":"Spread softened unsalted butter across the whole rectangle then sprinkle the cinnamon sugar evenly across the whole dough."},{"type":"step","text":"Tightly roll from the bottom all the way to the top. Slice into 2” thick segments"},{"type":"step","text":"Grease a 9x13 baking dish, line the bottom of the pan the rolls and cover with plastic wrap once filled. Let rise at room temperature for 30-45 minutes."},{"type":"step","text":"Bake in a 375F preheated oven for 15-20 minutes. Let cool in the container for 15 minutes."},{"type":"step","text":"For the filling, beat together cream cheese then blend in powdered sugar until smooth. Whisk in whole milk until smooth then add in half scraped vanilla bean and whisk together."},{"type":"step","text":"Drizzle the glaze on top of the cinnamon rolls and serve."}],"notes":[],"extra":""},{"id":"cinnamon-roll-sauce","title":"Cinnamon Roll Sauce","description":"","source":{"label":"","url":""},"image":"","servings":"","categories":[],"ingredients":[{"type":"item","text":"1/2c butter"},{"type":"item","text":"1/2c sugar"},{"type":"item","text":"some water"},{"type":"item","text":"molasses"}],"instructions":[{"type":"step","text":"-"}],"notes":[],"extra":""},{"id":"cucumber-avocado-salad","title":"cucumber avocado salad","description":"","source":{"label":"","url":""},"image":"","servings":"","categories":[],"ingredients":[{"type":"item","text":"- 1 normal cucumber or 2 smaller ones"},{"type":"item","text":"- 2 smaller avocados"},{"type":"item","text":"- 1/4 to 1/2 a carrot, thinly julienned"},{"type":"item","text":"- 2 TBS or so of lemon juice"},{"type":"item","text":"- salt \u0026 pepper"},{"type":"item","text":"- 2 scallions"},{"type":"item","text":"red pepper flakes, everything bagel seasoning"}],"instructions":[{"type":"step","text":"sliced thinly the scallions-- add to ice water\npeel and chop cucumber, place in bowl with salt 5-15 minutes\ndrain cucumbers\nchop avocado, mix with lemon juice, salt \u0026 pepper, \u0026 julienned carrots\ndrain scallions\nadd all together and stir\nadd everything bagel seasoning and red pepper flakes"}],"notes":[],"extra":""},{"id":"custard-buns","title":"Custard Buns","description":"","source":{"label":"","url":""},"image":"","servings":"","categories":[],"ingredients":[{"type":"heading","text":"INGREDIENTS:"},{"type":"item","text":"Preparing the custard"},{"type":"item","text":"500ml (2 cups) Milk"},{"type":"item","text":"2 Eggs"},{"type":"item","text":"100g (1/2 cup) Sugar"},{"type":"item","text":"30g (3 1/2 tbsp) Cornstarch"},{"type":"item","text":"A pinch of salt"},{"type":"item","text":"2 tsp Vanilla"},{"type":"item","text":"Prepare the dough"},{"type":"item","text":"200ml (1 cup) Warm Milk"},{"type":"item","text":"1 tbsp Yeast"},{"type":"item","text":"100g (1/2 cup) Sugar"},{"type":"item","text":"1 tsp Vanilla"},{"type":"item","text":"2 Eggs"},{"type":"item","text":"90g (1 cup) Butter (soften at room temperature)"},{"type":"item","text":"600g (about 4-5 cups) Plain flour"},{"type":"item","text":"Topping"},{"type":"item","text":"1 Egg yolk + 3 tbsp Milk"},{"type":"item","text":"Almond flaked"},{"type":"item","text":"-------HALF RECIPE--------"},{"type":"item","text":"250ml (1 cup) milk"},{"type":"item","text":"1 egg"},{"type":"item","text":"50g (1/4 cup) sugar"},{"type":"item","text":"15g (1.75 Tbsp) cornstarch"},{"type":"item","text":"1/2 pinch salt"},{"type":"item","text":"1 tsp vanilla"},{"type":"item","text":"DOUGH"},{"type":"item","text":"100ml (1/2 cup) milk warm"},{"type":"item","text":"1/2 TBS yeast"},{"type":"item","text":"50g (1/4 cup) sugar"},{"type":"item","text":"1/2 tsp vanilla"},{"type":"item","text":"1 egg"},{"type":"item","text":"45g (1/2 cup) softened butter"},{"type":"item","text":"300g (2-2.5 cups) flour"},{"type":"item","text":"topping"},{"type":"item","text":"1 egg yolk \u0026 3 Tbs milk"},{"type":"item","text":"almond flaked"},{"type":"heading","text":"for chocolate:"},{"type":"item","text":"add to the custard 2 Tbs cocoa powder"},{"type":"item","text":"add to the dough 1/2 cup (50g) cocoa and 1/2 cup (100g) sugar"}],"instructions":[{"type":"step","text":"Add milk to saucepan\nadd egg, sugar, salt, cornstarch (also some vanillin) and vanilla bean\nHeat on MED heat for about 5 minute while continuously stirring\nonce mixture thickens, place into bowl and cover with plastic wrap, set aside"},{"type":"step","text":"for dough\nadd warm milk and yeast to bowl, whisk, add sugar, egg, vanilla- whisk\nadd softened butter, whisk\nadd flour slowly,\nmix until combined\nknead about 5 minutes or until basically smooth and not sticky\nlet sit out for an hour\neither place in fridge or use immediately (sitting in fridge is easier to handle)\nroll out dough pretty thin, 1/2 to 1/4 inch?\nspread on custard\nroll up\ncut thin!! with floss\nset on tray and cover with plastic for ~ 15 minutes, egg wash and add almonds if adding\nthen baked in air fryer @ ~335F for 8-10 minutes +"}],"notes":[],"extra":""},{"id":"danish-dough","title":"Danish Dough","description":"","source":{"label":"https://cooking.nytimes.com/recipes/1017897-danish-dough","url":"https://cooking.nytimes.com/recipes/1017897-danish-dough"},"image":"images/danish_dough_gszk2.jpg","servings":"","categories":[],"ingredients":[{"type":"item","text":"1 1⁄2 cups/6 3/4 ounces/192 grams bread flour, plus more for the work surface and the rolling pin"},{"type":"item","text":"2 tablespoons/24 grams granulated sugar"},{"type":"item","text":"2 teaspoons/6 grams active dry yeast"},{"type":"item","text":"3⁄4 teaspoon/3 grams kosher salt"},{"type":"item","text":"14 tablespoons/198 grams cold, unsalted butter (1 3/4 sticks), roughly cubed"},{"type":"item","text":"1 large egg"},{"type":"item","text":"1⁄4 cup/60 milliliters cold whole milk"}],"instructions":[{"type":"step","text":"Combine the flour, granulated sugar, yeast and salt in the bowl of a food processor. Add the butter and pulse to combine. The butter should be the size of small marbles and peas. Transfer this mixture to a medium bowl."},{"type":"step","text":"In a small bowl, whisk together the egg, milk and 2 tablespoons/30 milliliters water."},{"type":"step","text":"Add the egg mixture to the flour mixture. Using a rubber spatula, fold the mixture until it is evenly moistened. Turn the dough out onto a piece of plastic wrap, shape into a small rectangle, and wrap well. Chill for at least 3 hours, and up to 2 days."},{"type":"step","text":"On a lightly floured surface, using a floured rolling pin, roll the dough out to an 8-by-15-inch rectangle. With a short side facing you, fold the dough in thirds like a letter, bringing the top third of the dough down, then folding the bottom third up. Use a bench scraper to help lift and fold the dough if necessary. At this point, the dough will be rough and shaggy with visible butter pieces; as you roll and fold the dough it will come together. Rotate the dough 90 degrees. Repeat the rolling and folding process, then rotate the dough once more and roll and fold again. As you work, dust the work surface, your hands and the rolling pin with flour as necessary. Wrap the dough in plastic wrap and refrigerate for at least 1 hour."},{"type":"step","text":"Repeat the entire rolling and folding process one more time for a grand total of six turns. If the dough starts to fight you and become difficult to roll at any point, just pop it in the fridge for an extra rest. Wrap the dough and refrigerate for at least 2 hours, or overnight."},{"type":"step","text":"If you are using this dough to make the pear and almond Danish braid, add 1 teaspoon/2 grams coarsely ground fresh cardamom to step 1, along with the flour, sugar, yeast and salt."}],"notes":[],"extra":""},{"id":"duck-sauce","title":"duck sauce","description":"","source":{"label":"","url":""},"image":"images/duck_sauce_ml9ft.jpg","servings":"","categories":[],"ingredients":[{"type":"item","text":"1/2 tsp soy"},{"type":"item","text":"2 tsp sherry vinegar and some sprays"},{"type":"item","text":"1/4 cup apricot"},{"type":"item","text":"pinch dried garlic powder"},{"type":"item","text":"pinch dried mustard powder"},{"type":"item","text":"1tbsp water"},{"type":"item","text":"1tsp hoisin"},{"type":"item","text":"2tsp chili crisp"}],"instructions":[{"type":"step","text":"-"}],"notes":[],"extra":""},{"id":"edible-gingerbread","title":"edible gingerbread","description":"","source":{"label":"","url":""},"image":"","servings":"","categories":[],"ingredients":[{"type":"item","text":"9x13\" pan with parchment"},{"type":"item","text":"oven temp: 350F"},{"type":"item","text":"1 cup (237 mL) milk or water (used infused cream + butter) + added vanilla to that"},{"type":"item","text":"1/2 cup (118 mL) molasses"},{"type":"item","text":"1/2 cup (118 mL) honey"},{"type":"item","text":"1/2 cup (one stick, 113g) butter (I used half shortening, half butter)"},{"type":"item","text":"1/2 cup (100g) granulated sugar"},{"type":"item","text":"1 egg"},{"type":"item","text":"2 1/2 cups (300g) all-purpose flour"},{"type":"item","text":"1/2 teaspoon salt (maybe 3/4 if using unsalted butter)"},{"type":"item","text":"1 1/2 teaspoons baking soda + PINCH OF BAKING POWDER"},{"type":"item","text":"2 tablespoons ground cinnamon"},{"type":"item","text":"2 tablespoons ground ginger (use half if you don't want it very spicy)"},{"type":"item","text":"a little finely-ground black pepper"}],"instructions":[{"type":"step","text":"Pour the cream into a pot on stove over low heat, add in shortening and butter as well as distillate\nwarm and stir until all distillate is out\nAdd splash of vanilla\nRemove from heat, add molasses and honey, stir, set aside\nMix dry ingredients, flour, salt, b powder,+ b soda, spices-- whisk to combine to fluff flour\nPut the sugar in with the wet ingredients along with the egg and stir until smooth.\nPour the wet mixture into the dry and whisk until just smooth\nmake sure mix is slightly warm\nPour into 9x13 or [bread loaf pan(takes longer)]\nBake 15-35 mins\nTake out just before done\nAdd marshmallows + broil\nTake out with parchment and cool on rack"}],"notes":[],"extra":""},{"id":"falafel","title":"falafel","description":"","source":{"label":"","url":""},"image":"images/falafel_d3oct.jpg","servings":"","categories":[],"ingredients":[{"type":"item","text":"2 cups dried chickpeas (soaked 12 hours)"},{"type":"item","text":"1 L onion chopped or 2 medium/sm"},{"type":"item","text":"1/4 cup parsley and cilantro (more)"},{"type":"item","text":"4 sliced garlic cloves"},{"type":"item","text":"pinch baking powder?"},{"type":"item","text":"1 tsp coriander"},{"type":"item","text":"1 tsp cumin"},{"type":"item","text":"salt to taste (1-2 tsp)"},{"type":"item","text":"xanthan gum 2 tsp"},{"type":"item","text":"besan to coat"}],"instructions":[{"type":"step","text":"Combine soaked chickpeas with onion, herbs and garlic in a large bowl, stir together\nScoop into food processor\nBlend and hold, stir with spatula, scrape sides\nadd little bit of water if needed\nDump mixture resembling ricotta? into bowl\nAdd spices, baking powder, and xanthan gum\nMix thoroughly with spatula"},{"type":"step","text":"shape into falafel\ncoat with besan\nfry 350F oil?\nuntil golden and crisp"}],"notes":["Need oven tray lined with parchment (for falafel balls)","Need oven tray lined with parchment and oven rack (for cooked falafel)","Spider"],"extra":""},{"id":"fava","title":"FAVA","description":"","source":{"label":"","url":""},"image":"","servings":"","categories":[],"ingredients":[{"type":"item","text":"2 tbsp cumin"},{"type":"item","text":"1 tbsp coriander"},{"type":"item","text":"300g tomatoes"},{"type":"item","text":"salt to taste"},{"type":"item","text":"1/2 tsp white pepper"},{"type":"item","text":"4 cups fava beans"},{"type":"item","text":"virgin olive oil"},{"type":"item","text":"garnish - tomatoes, parsley"},{"type":"item","text":"lemon juice - If required"},{"type":"item","text":"8 chopped garlic cloves"}],"instructions":[{"type":"step","text":"-"}],"notes":[],"extra":""},{"id":"fishy-rice-spice","title":"Fishy Rice Spice","description":"also served it with seasoned rice, lemon + herb.1 cup rice1.5 cup of water1 tbsp of:dried parsleyonion powdercilantrolemon juice1tsp of:dried thymedried rosemaryvegetable bouillonminced garlic (approximately one clove)other:1/2 tsp of white pepper2 tsp of coriander2 tbsp of cultured, unsalted butter","source":{"label":"","url":""},"image":"","servings":"","categories":[],"ingredients":[{"type":"item","text":"-"}],"instructions":[{"type":"step","text":"-"}],"notes":[],"extra":""},{"id":"fluff-cereal-bars","title":"fluff cereal bars","description":"","source":{"label":"","url":""},"image":"","servings":"8 bars","categories":[],"ingredients":[{"type":"item","text":"1.5 Cups plain cheerios"},{"type":"item","text":".5 Cup Bran flakes"},{"type":"item","text":".5 Cup Maple Magic Spoon"},{"type":"item","text":".5 Cup granola crushed some"},{"type":"item","text":".5 Cup toasted almond slivers"},{"type":"item","text":"1 Tbs toasted wheat germ"},{"type":"item","text":"1-2 Tbs caramel packet from brownie mix"},{"type":"item","text":"1 Cup fluff"},{"type":"item","text":"4 Tbs butter (used 1 TBS butter, 1.5 Tbs avocado oil, 1.5 Tbs butter shortening) use less"},{"type":"item","text":"1 scoop protein powder"},{"type":"item","text":"pinch salt in toasted almonds"}],"instructions":[{"type":"step","text":"Mix together all dry ingredients (toasted almonds, toasted wheat germ, bran flakes, cheerios, magic spoon, granola)\nmelt together butter, add fluff to butter, caramel, scoop of protein powder, mix until combined\nonce combined, pour over dry\nmix until evenly coated\npress into greased bar tray/pan\nsit 30 minutes in fridge"}],"notes":[],"extra":""},{"id":"frosting","title":"frosting","description":"","source":{"label":"","url":""},"image":"","servings":"","categories":[],"ingredients":[{"type":"item","text":"375g pwdr sgr"},{"type":"item","text":"42g cocoa powder"},{"type":"item","text":"pinch salt"},{"type":"item","text":"84g butter"},{"type":"item","text":"45ml-95ml milk"}],"instructions":[{"type":"step","text":"-"}],"notes":[],"extra":""},{"id":"garlic-bread-sticks","title":"garlic bread sticks","description":"","source":{"label":"","url":""},"image":"","servings":"12","categories":[],"ingredients":[{"type":"item","text":"1 Tbs instant yeast"},{"type":"item","text":"2 Tbs sugar"},{"type":"item","text":"1 cup 100-110F water"},{"type":"item","text":"2\u00261/2-3 cups flour; Half bread flour half all-purpose-- more bread than ap"},{"type":"item","text":"2 tsp salt +?"},{"type":"item","text":"3 Tbs olive oil"},{"type":"item","text":"for topping"},{"type":"item","text":"4 Tbs melted butter"},{"type":"item","text":"2 Tbs + parmesan"},{"type":"item","text":"1 tsp mix herbs de Provence + Italian seasoning"},{"type":"item","text":"2-3 cloves minced garlic"},{"type":"item","text":"some salt"}],"instructions":[{"type":"step","text":"combine warm water, yeast, sugar, salt, + oil\nadd 2 cups flour\nonce incorporated, slowly add rest of flour\ndough pulls from side of bowl, not too wet\ntransfer dough to a lightly greased bowl\ncover with damp towel or paper towel +foil 30 mins- 1 hour+ (until doubled)(longer better)\nline baking sheet with parchment + lightly spray\npunch down dough\ndivide dough into 12 equal pieces (around 50g-60g)\n9-10 inch rope roll out\ncover with damp paper towel\nlet rise 20 minutes - 1 hour on sheet pan once rolled out\nbake 425F 10-15 minutes"},{"type":"heading","text":"for topping:"},{"type":"step","text":"while baking, heat butter until just browned\nremove from heat\nadd in garlic cloves, sit ~30 seconds, then strain garlic out\npour butter into cup/glass with parmesan, dry herbs/spice mixture, salt\nuse brush to immediately spread onto tops of bread sticks"}],"notes":["adapted from 2 separate recipes"],"extra":""},{"id":"garlic-herb-butter","title":"Garlic Herb Butter","description":"","source":{"label":"","url":""},"image":"","servings":"","categories":[],"ingredients":[{"type":"item","text":"2 sticks unsalted butter, room temperature"},{"type":"item","text":"4 cloves garlic, minced"},{"type":"item","text":"1 tablespoon chopped parsley leaves"},{"type":"item","text":"1/2 teaspoon salt"},{"type":"item","text":"OR"},{"type":"item","text":"2 TBS butter"},{"type":"item","text":"1/2 tsp garlic"},{"type":"item","text":"large pinchful chopped fresh parsley"},{"type":"item","text":"sm pinch of salt"}],"instructions":[{"type":"step","text":"-"}],"notes":[],"extra":""},{"id":"garlic-naan","title":"Garlic Naan","description":"Chainbaker recipe","source":{"label":"","url":""},"image":"images/garlic_naan_hcykc.jpg","servings":"4 large, 8 sm","categories":[],"ingredients":[{"type":"item","text":"For the dough –"},{"type":"item","text":"250g (8.8oz) strong white bread flour"},{"type":"item","text":"5g (0.2oz) salt"},{"type":"item","text":"5g (0.2oz) sugar"},{"type":"item","text":"3-6g (0.1oz) dry yeast or three times the amount of fresh yeast"},{"type":"item","text":"10g (0.35oz) oil"},{"type":"item","text":"60g (2.1oz) yogurt at around 20C (68F)"},{"type":"item","text":"100g (3.5oz) milk at around 20C (68F)"},{"type":"item","text":"For the garlic butter –"},{"type":"item","text":"2 tablespoons of softened butter"},{"type":"item","text":"Chopped parsley"},{"type":"item","text":"1 minced clove of garlic"},{"type":"item","text":"Pinch of salt (Mix everything until combined ready for spreading)"}],"instructions":[{"type":"step","text":"Add the milk and yeast to a bowl and let the yeast hydrate for a couple of minutes."},{"type":"step","text":"Add the salt, sugar, oil and yogurt and give it a good mix to dissolve any salt and sugar crystals."},{"type":"step","text":"Add the flour and mix until combined."},{"type":"step","text":"Knead the dough for around 5 minutes. Desired dough temperature 25 – 26C (77 – 79F). If your dough is\nwarmer, then reduce the proofing time. If it is cooler, then increase proofing time."},{"type":"step","text":"Ferment for 25 minutes. My kitchen as quite warm on the day of baking, so I had to cut down on fermentation time. Keep an eye on your dough and if it is fermenting rapidly, react."},{"type":"step","text":"Fold."},{"type":"step","text":"Proof for 25 minutes."},{"type":"step","text":"Divide into 4 equal pieces and shape into balls."},{"type":"step","text":"Cover and proof for around 30 minutes."},{"type":"step","text":"Roll the dough out and rub with oil."},{"type":"step","text":"Cook in a pan on medium-high heat flipping every 30 seconds for around 4 minutes or until well coloured and puffed up. You can use more oil to get a more evenly brown colour."},{"type":"step","text":"Brush the breads with the garlic butter and enjoy whilst still warm with your favourite curry."}],"notes":[],"extra":"I made this."},{"id":"garlic-sauce","title":"garlic sauce","description":"","source":{"label":"","url":""},"image":"","servings":"","categories":[],"ingredients":[{"type":"item","text":"100g mayo"},{"type":"item","text":"50g greek yogurt"},{"type":"item","text":"15g vinegar"},{"type":"item","text":"10 cranks black pepper"},{"type":"item","text":"juice from quarter lemon"},{"type":"item","text":"salt"}],"instructions":[{"type":"step","text":"-"}],"notes":[],"extra":""},{"id":"glazed-donuts","title":"Glazed Donuts","description":"","source":{"label":"","url":""},"image":"images/glazed_donuts_divx9.jpg","servings":"","categories":[],"ingredients":[{"type":"heading","text":"•500g flour; HALF recipe on right:"},{"type":"item","text":"•167g All Purpose flour 83.5g"},{"type":"item","text":"•167g Cake flour 83.5g"},{"type":"item","text":"•167g Bread flour 83.5g"},{"type":"item","text":"•7g fine salt 3.5g"},{"type":"item","text":"•3g amylase 1.5-2g"},{"type":"item","text":"•2tsp Rapid Rise Yeast 1tsp"},{"type":"item","text":"•300g/ml milk (or; 150g-180g cream +130g-150g water) 150g (75g \u002675g)"},{"type":"item","text":"•35g-85g granulated sugar 17.5g-45g LESS"},{"type":"item","text":"•1 egg 1/2 egg"},{"type":"item","text":"•2Tbs shortening/crisco 1TBS"},{"type":"item","text":"•2Tbs unsalted butter 1TBS"},{"type":"item","text":"•1/3 vanilla bean + splash vanilla (bean not necessary, but worth it)"},{"type":"item","text":"•Crisco for frying"},{"type":"item","text":"GLAZE half recipe on right"},{"type":"item","text":"•~400g powdered sugar 200g"},{"type":"item","text":"• pinch of salt 1/2 pinch"},{"type":"item","text":"• 20g corn syrup 10g"},{"type":"item","text":"• ~140g cream (warmed with vanilla bean slightly) 70g"},{"type":"item","text":"• 1/3 - 2/3 vanilla bean sm splash warmed up vanilla"},{"type":"item","text":"best refrigerated and then whisked with more cream"}],"instructions":[{"type":"step","text":"•Weigh out flours \u0026 salt, amylase combine, set aside"},{"type":"step","text":"•In a Large bowl, measure out yeast"},{"type":"step","text":"•In a Smaller saucepan (or microwave bowl), weigh out milk(cream+water) \u0026 sugar, combine"},{"type":"step","text":"•Medium heat, warm milk sugar mixture until 115F (microwave, probably 20 sec? intervals)"},{"type":"step","text":"•Do not exceed 140F or it will kill yeast"},{"type":"step","text":"•Pour milk mixture into yeast, whisk"},{"type":"step","text":"•Let mix sit about 15 minutes"},{"type":"step","text":"•Melt butter and Crisco together, cool"},{"type":"step","text":"•Add vanilla, egg, + melted butter \u0026 Crisco to milk yeast mix, whisk"},{"type":"step","text":"•Add flour mix to milk mix, combine (I use silicone spatula)"},{"type":"step","text":"•On a very lightly floured surface, gently knead/fold dough for 5-7 minutes"},{"type":"step","text":"•Grease large bowl with Crisco"},{"type":"step","text":"•Make dough into ball and place into well greased bowl"},{"type":"step","text":"•Cover and let rise 2-3 hours"},{"type":"step","text":"•After, either roll out and shape dough or rest in fridge overnight"},{"type":"step","text":"•Press dough down"},{"type":"step","text":"•Roll dough out into about 1/8\" to 1/4\""},{"type":"step","text":"•With an uncrustable sandwich cutter (any proper sized circular cutter), cut out donuts"},{"type":"step","text":"•Cut out center of donut with medicine cup bottom or proper sized equivalent"},{"type":"step","text":"•Once cut, let rise 30 minutes to 1 hour on a foiled, lightly floured, sheet pan"},{"type":"step","text":"•Prepare wire racks (and sheet trays to lay under them, foiled/covered)"},{"type":"step","text":"•Once risen, in a Large pan or wok (I use a wok, on a plug in heating element for less mess) heat Crisco to 350F, no more or donuts will burn"},{"type":"step","text":"•Fill wok a little less than halfway"},{"type":"step","text":"•With a candy thermometer, check temperature of Crisco (don't touch bottom of pan)"},{"type":"step","text":"•As soon as temperature says around 345F and climbing, quickly but carefully place as many donuts as you can fit into the hot Crisco"},{"type":"step","text":"•Set a 1 minute timer as soon as you put the last donut of the batch in"},{"type":"step","text":"•Keep and eye on donuts as not to burn"},{"type":"step","text":"•Flip after 1 minute and cook 1 more minute"},{"type":"step","text":"•Cook 1 minute on each side"},{"type":"step","text":"•Donuts will be a light to medium brown/golden"},{"type":"step","text":"•With a spider strainer, strain out donuts onto wire rack"},{"type":"step","text":"•Continue process until all dough is fried"},{"type":"step","text":"•While donuts are still warm, dip in glaze on either side, tapping gently on side of bowl to remove excess"},{"type":"step","text":"•Place donuts back onto wire racks to let glaze set"},{"type":"step","text":"•Continue until all donuts are glazed and glaze is set"},{"type":"step","text":"Enjoy~"}],"notes":[],"extra":""},{"id":"gravy","title":"Gravy","description":"","source":{"label":"https://www.recipetineats.com/gravy/","url":"https://www.recipetineats.com/gravy/"},"image":"images/gravy_lmklz.jpg","servings":"2","categories":[],"ingredients":[{"type":"item","text":"0.33 chicken stock cube / bouillon cube (sub 2 tsp powder) (Note 1)"},{"type":"item","text":"0.33 beef stock cube / bouillon cube (sub 2 tsp powder) (Note 1) DONT ADD (For chicken gravy)"},{"type":"item","text":"0.75 cups ( 188.33ml) boiling water"},{"type":"item","text":"20g/ 1.33 tbsp butter , unsalted"},{"type":"item","text":"1.33 tbsp flour , plain / all purpose"},{"type":"item","text":"0.17 tsp onion powder (ok to omit or sub garlic powder)"},{"type":"item","text":"0.08 tsp finely ground black pepper"},{"type":"item","text":"Salt , if needed"}],"instructions":[{"type":"step","text":"Crumble cubes into boiling water, mix to dissolve."},{"type":"step","text":"Melt butter in a saucepan over medium heat."},{"type":"step","text":"Add flour, onion powder and pepper. Mix into butter with a wooden spoon or whisk."},{"type":"step","text":"While stirring, slowly pour in half the liquid. Once incorporated into the flour butter roux (it will thicken quickly), add remaining liquid and mix."},{"type":"step","text":"Stir for 1.5 – 2 minutes until it thickens to a gravy consistency (it's quick as water is already hot). Taste, add more salt and pepper if needed."},{"type":"step","text":"Serve over chops, steak, sausages, veggies, roast chicken, pork, beef, lamb. Pictured – KFC Potato and Gravy copycat!"}],"notes":["Stock cubes / bouillon cubes – as pictured in post. Chicken for base flavour, beef for flavour boost + makes gravy nice brown colour (if only chicken, gravy is pale).","Substitute with stock powder / granulated bouillon, but note that some brands of beef powder will not yield quite the same brown colour, will be slightly lighter.","If you only use chicken cube or powder, the gravy flavour will lose a touch of seasoning and will be a pale brown colour. Can make up for this with 1 tsp Dark soy sauce – it will stain the gravy and add a touch of extra flavour (this is a secret cooking trick for gravy!)","Onion or garlic powder – not the end of the world if you don’t have this, it’s just a tiny hint of extra flavour.","Gravy consistency – don’t let it get too thick, it thickens more when sitting around to be served. If it gets too thick, just add a touch of water. Too thin, keep it on the stove, it should thicken quickly.","Storage – gravy gets thicker and gets a skin on the surface as it cools. Just use water to thin out, whisk the skin in and heat it up, it will be as good as new.","If serving soon, just place a lid on the saucepan then reheat when required.","Make ahead and leftovers – transfer to container and place lid on, let cool then refrigerate for up to 5 days. Can also freeze – once thawed, reheat and give it a good mix. You’ll need to loosen with water.","Gluten free – Skip flour, ensure stock cubes are gluten free. Mix 2.5 tbsp cornflour/cornstarch with 3 tbsp water, then add that into the hot stock liquid. Mix, then pour that into the saucepan with melted butter. Will thicken in 2 minutes or so.","Nutrition per serving, just under 1/2 cup per serving (yes that’s generous!). To reduce calories, can halve the butter to 30g/2tbsp – when flour is added, mixture will be crumbly rather than “wet” (as seen in video) but will dissolve in liquid (use whisk). 33 cal per serving reduction."],"extra":""},{"id":"hemptsels","title":"Hemptsels","description":"","source":{"label":"","url":""},"image":"images/hemptsels_sr9cl.jpg","servings":"","categories":[],"ingredients":[{"type":"item","text":"poolish (150g bread flour + 150g water + pinch yeast)"},{"type":"item","text":"tangzhong (2 Tbs water, 4 Tbs milk, 2 Tbs bread flour)"},{"type":"item","text":"125ml whole milk"},{"type":"item","text":"20??ml water"},{"type":"item","text":"10g bread machine yeast"},{"type":"item","text":"1 large egg"},{"type":"item","text":"1 egg yolk"},{"type":"item","text":"132g manitoba max fiber hemp powder (hemp flour)"},{"type":"item","text":"268g whole wheat flour"},{"type":"item","text":"150g bread flour"},{"type":"item","text":"7g salt"},{"type":"item","text":"4g amylase"},{"type":"item","text":"1.5g (1/2 tsp) xanthan gum"},{"type":"item","text":"60g sugar"},{"type":"item","text":"44g softened butter"},{"type":"item","text":"44g butter flavored shortening"},{"type":"item","text":"melted butter"},{"type":"item","text":"triple-seed-topping (1:1:1; hemp hearts, wheat germ, black seeds)"},{"type":"item","text":"flakey salt"}],"instructions":[{"type":"step","text":"Combine water and milk in a small bowl, whisk in yeast to dissolve, place in a stand mixer bowl along with the whole egg and egg yolk; and the tangzhong and ripened poolish; mix on low speed, until combined."},{"type":"step","text":"In a separate bowl, mix flour, sugar, salt, xanthan gum and amylase.\nWhile mixing (by hand or stand mixer), add in your flour mixture, 1⁄4 cup at a time, until all of your flour has been added."},{"type":"step","text":"Once it begins to form a rough dough, allow to knead for 2 minutes or until it begins to turn smooth.\nThen add your butter, allow to mix until fully incorporated, and knead for 5-10 more minutes or till your dough is very smooth and begins to pull from the sides of the bowl."},{"type":"step","text":"Cover with plastic wrap and rise for 45 minutes at room temperature.\nThen place in the fridge for 1.5 hours and up to overnight."},{"type":"step","text":"Separated into 150g portions, shape into pretzel and let rise for at least half an hour at room temperature.\nIdeally refrigerate for at least 4 hours before the lye bath (1000g water to 30g NaOH)."},{"type":"step","text":"Top with triple-seed-topping and flakey salt.\nThen bake @ 425F until deep pretzel brown (approximately 18 minutes)\nOptionally top with melted butter."}],"notes":[],"extra":"I made this."},{"id":"hero-roll","title":"Hero Roll","description":"Josh Weissman","source":{"label":"","url":""},"image":"","servings":"","categories":[],"ingredients":[{"type":"heading","text":"Hero Roll:"},{"type":"item","text":"- 2.5 teaspoons (8g) instant yeast"},{"type":"item","text":"- 302g (302ml) water"},{"type":"item","text":"- 600g bread flour"},{"type":"item","text":"- 2.5 tablespoons (33g) sugar"},{"type":"item","text":"- 2g amylase"},{"type":"item","text":"- 2 teaspoons (14g) fine sea salt"},{"type":"item","text":"- 1/4 cup (34g) unsalted butter"},{"type":"item","text":"- fine cornmeal for dusting"},{"type":"item","text":"- 1 egg white"},{"type":"item","text":"- 1/2 cup (118ml) water"}],"instructions":[{"type":"heading","text":"INSTRUCTIONS:"},{"type":"heading","text":"Hero Roll:"},{"type":"step","text":"Preheat oven to 375 F."},{"type":"step","text":"In a container mix water (90F) and yeast until dissolved, follow that with sugar, whisk until dissolved, and pour into your stand mixer bowl with the dough hook attachment. In a separate bowl, mix the bread flour and sea salt. Add your flour mix a heaping spoon at a time until all it has been added. Let that mix for five minutes or until your dough turns smooth; then add unsalted softened butter, let that mix for another two minutes or until incorporated and smooth."},{"type":"step","text":"Shave your dough into a ball, place it on a greased bowl, cover with plastic wrap, and let it rise for one hour at room temperature or until doubled. Next, degas your dough by punching; divide into eight evenly sized balls, cover them with a damp towel and rest for ten minutes."},{"type":"step","text":"Roll your balls into a rectangle (roughly 7” by 4”). Then starting from the long side, roll it tightly into a log, seal the seam, then roll it out to the ends to taper (try not to get it too long); place them onto a baking sheet lightly dusted with cornmeal, and repeat with the rest of the balls. Next, cover them with another baking sheet inverted, wrap it with plastic wrap and let them proof at room temperature for 30 minutes."},{"type":"step","text":"Whisk one egg white in water until thoroughly combined, pour that into a spray bottle, and spray your dough to coat evenly and lightly with egg wash. (you can use a brush too). Next, using a sharp razor, score your dough at a 35-degree angle, about a quarter of an inch deep into the dough. Place in the oven and bake for 15 - 2o minutes."},{"type":"step","text":"Remove and brush with melted butter (optional), then cool on a wire rack until completely cool."}],"notes":[],"extra":""},{"id":"homemade-puff-pastry","title":"Homemade Puff Pastry","description":"375F-390F","source":{"label":"","url":""},"image":"","servings":"","categories":[],"ingredients":[{"type":"item","text":"2.5 cups (320g) all purpose flour"},{"type":"item","text":"3/4 cup (177g) cold water"},{"type":"item","text":"1 tsp (7g) fine sea salt"},{"type":"item","text":"1 cup plus 2 Tbsp (227g) unsalted cold butter"},{"type":"item","text":"6 grams ish of yeast"}],"instructions":[{"type":"heading","text":"Example Folding Schedule:"},{"type":"step","text":"10:00am - Make dough and butter block and refrigerate"},{"type":"step","text":"10:35am - Encase butter into dough roll and letter fold, turn 90 degrees and repeat roll and letter fold. Fridge for 30 minutes (2 folds done)"},{"type":"step","text":"11:15 am - Repeat two more folds, letting the dough rest in the fridge if necessary (now at 4 folds). Once folds are complete, rest in the fridge for 30 more minutes."},{"type":"step","text":"11:55 am - Perform 2 more folds totaling at 6 (you will likely need to rest the dough in the fridge after the 5th fold if it won't roll out)."},{"type":"step","text":"12:30 am - Once all 6 folds are done, wrap your dough and rest in the fridge for 1-3 days then use in whatever recipe you're making. (maybe beef wellington . wink wink"},{"type":"heading","text":"Method:"},{"type":"step","text":"Start off by combining fine sea salt with all-purpose flour and give it a whisk. Once that’s thoroughly incorporated, stream in cold water. Knead a few times to make sure it’s all combined and the flour is hydrated."},{"type":"step","text":"To roll your dough out into a perfect 7x7 inch square, place your dough on a sheet of wax paper. Fold the wax paper so that the edges make a 7x7 inch square. Roll out your dough using a rolling pin to fill in the edges. Place the dough in the fridge."},{"type":"step","text":"Take your cold unsalted butter and cut it into cubes; sprinkling lightly with flour. Gently beat it together using a rolling pin until it comes together to form a solid mass. Fold it over using a bench scraper and continue this process until its’ smooth and cohesive."},{"type":"step","text":"Place your butter on a sheet of wax paper and repeat the process like the dough; but shaping it to be a 4x4 inch square. Place in your fridge alongside your dough and let it rest for 30 minutes."},{"type":"step","text":"Take your dough and butter out of the fridge and lightly dust your work surface. Slightly roll out the points of your dough to elongate them; then place your butter square in the center positioned at a diagonal."},{"type":"step","text":"Fold the edges of the dough over the butter so that they all meet together, then gently pinch the edges together."},{"type":"step","text":"Roll your dough out into a long rectangle measuring 12 inches in length and 6 inches in width. Fold the top part of the rectangle 1⁄3 of the way down; then the bottom 1⁄3 to overlap the top fold."},{"type":"step","text":"Rotate your dough 90 degrees and roll it again into a rectangle 12x6 inches. Perform the same folding technique. Let your dough rest wrapped in the fridge if necessary."},{"type":"step","text":"Perform two more folds, and let it rest in the fridge for 30 minutes. Take it out and perform two more folds again, for a total of 6 folds."},{"type":"step","text":"See timing chart above*"},{"type":"step","text":"Once you’ve done a total of 6 folds, let it rest for 1 hour before rolling your pastry out."}],"notes":[],"extra":""},{"id":"honey-buns","title":"Honey Buns","description":"","source":{"label":"","url":""},"image":"images/honey_buns_2m3ly.jpg","servings":"24ish","categories":[],"ingredients":[{"type":"heading","text":"Honey Buns:"},{"type":"item","text":"• 2 cups all-purpose flour"},{"type":"item","text":"• 3 tablespoons granulated sugar"},{"type":"item","text":"• 1⁄2 teaspoon salt"},{"type":"item","text":"• 1⁄2 cup + 3 tablespoons milk (WATER + CREAM)"},{"type":"item","text":"• 2 1⁄4 teaspoons (1 packet) instant or active dry yeast"},{"type":"item","text":"• 5 1⁄3 tablespoons (1⁄3 cup) butter melted (HALF CRISCO)"},{"type":"item","text":"• 1 large egg"},{"type":"item","text":"• 1⁄2 tablespoon vegetable oil"},{"type":"item","text":"• 1 1⁄2 teaspoon ground cinnamon"},{"type":"item","text":"• 3 cups vegetable oil for frying (optional)"},{"type":"heading","text":"Glaze:"},{"type":"item","text":"• 3 tablespoons butter melted"},{"type":"item","text":"• 2 teaspoon honey"},{"type":"item","text":"• 11⁄4 cups powdered sugar"},{"type":"item","text":"• 2 tablespoons milk"},{"type":"item","text":"• 1⁄2 teaspoon vanilla extract or bean equivalent"}],"instructions":[{"type":"heading","text":"Honey Buns:"},{"type":"step","text":"• Whisk together flour, sugar, \u0026 salt"},{"type":"step","text":"• In a microwave-safe bowl, add in the milk. Microwave for 30 seconds.\n(can use stovetop)\n• milk should be at 105 - 110 degrees F."},{"type":"step","text":"• Add yeast, cooled melted butter, and egg to milk"},{"type":"step","text":"• Pour the wet mixture into dry \u0026 mix gently (using very little flour)\nfor 10 minutes.\n~The dough will be sticky."},{"type":"step","text":"• Grease your hands and a large bowl with vegetable oil."},{"type":"step","text":"• Shape dough into a ball."},{"type":"step","text":"• Place the dough in the bottom of the bowl and coat it in the 1/2 Tbs oil.\n• Cover the bowl with plastic wrap and let the dough rise until doubled.\n• This will take about 1 to 2 hours."},{"type":"step","text":"• Line a cookie sheet with parchment paper/foil.\n• Spray the parchment paper with nonstick baking spray."},{"type":"step","text":"• Once the dough has doubled, press it down."},{"type":"step","text":"• Place the dough on a lightly floured work surface."},{"type":"step","text":"• Press the dough out into a 6-inch by 14-inch rectangle.\n~You can use a rolling pin, or use your hands."},{"type":"step","text":"• Brush honey onto rectangular dough (thin layer)\n• Sprinkle the cinnamon on top of the honey \u0026 dough.\n• Using your brush (or hands), rub the cinnamon all over"},{"type":"step","text":"• Begin rolling the dough from the long side."},{"type":"step","text":"• Once the dough is rolled up, you'll need to seal the edge.\n• Do this by rubbing the edge of the dough with water.\n• Pinch the wet edge into the roll of dough to form the seam.\n• If the dough isn't staying pinched together, rub a little more water on the edge and pinch again.\n• Leave the dough seam side up since it will be sticky from the water and will likely stick to the counter if it touches it."},{"type":"step","text":"• Measure out 1⁄2-inch thick slices if you want thinner honey buns or 1-inch slice for thicker slices.\n(1-inch or thicker)"},{"type":"step","text":"• Slide a piece of floss under the dough and cross both sides of the floss\n• Pull until the floss has cut completely through the dough."},{"type":"step","text":"• Place on the prepared cookie sheet.\n• Repeat with the remaining dough."},{"type":"step","text":"If you plan on baking these, you'll want to space them 2 inches apart.\nIf you plan on frying them, they can be 1⁄2 inch apart."},{"type":"step","text":"• Brush entire surface of honey bun with honey"},{"type":"step","text":"• Let rise, lightly covered, for 30 minutes in a warm place."},{"type":"heading","text":"--Baked Honey Buns:"},{"type":"step","text":"• Preheat oven to 350F."},{"type":"step","text":"-Bake for 10 to 15 minutes until the edges begin to turn golden brown-"},{"type":"step","text":"• Prepare the glaze while the honey buns are baking."},{"type":"step","text":"• Remove the honey buns from the oven and let cool for 10 to 20 minutes.\n• While they're still warm, dip the tops in the glaze, or place icing on top and rub in with spoon.\n• Tap the wrist that's holding the honey bun to remove the excess glaze\n• Place on wire rack or wax to continue cooling \u0026 let the glaze set up."},{"type":"heading","text":"--Fried Honey Buns:"},{"type":"step","text":"• Heat 3 cups of vegetable oil until it reaches 320F."},{"type":"step","text":"• Prepare the glaze while you wait for the oil to come up to temperature."},{"type":"step","text":"• Place the honey buns in one or two at a time into the oil.\n• Flip once the donuts become golden brown."},{"type":"step","text":"• Once the other side becomes golden brown, place on a plate lined with paper towels.\n• Let cool for 5 to 10 minutes."},{"type":"step","text":"• Dip the warm honey bun in the glaze.\n• Give your wrist a tap to help any excess glaze to drip off.\n• Place on a piece of wax paper and let the glaze set up."},{"type":"heading","text":"--Glaze:"},{"type":"step","text":"• In a medium mixing bowl, add in the butter, powdered sugar, milk, and vanilla extract/bean.\n• Whisk together until the glaze is smooth."}],"notes":[],"extra":""},{"id":"if-making-candied-lemon-slices","title":"if making candied lemon slices","description":"","source":{"label":"","url":""},"image":"","servings":"","categories":[],"ingredients":[{"type":"item","text":"boil lemon slices a few times to remove bitter first"}],"instructions":[{"type":"step","text":"-"}],"notes":[],"extra":""},{"id":"italian-dressing","title":"Italian Dressing","description":"Half recipe on RIGHT","source":{"label":"","url":""},"image":"","servings":"","categories":[],"ingredients":[{"type":"item","text":"1/2 cup olive oil 1/4 cup"},{"type":"item","text":"3 Tbsp white wine vinegar 1.5 Tbs"},{"type":"item","text":"3 Tbsp grated parmesan cheese 1.5 Tbs"},{"type":"item","text":"1 tsp dijon mustard 1/2 tsp"},{"type":"item","text":"1 tsp honey 1/2 tsp"},{"type":"item","text":"2 cloves garlic, minced (1/2 tsp powder) -- 1/4 tsp"},{"type":"item","text":"1/2 tsp dried oregano 1/4 tsp"},{"type":"item","text":"1/2 tsp dried basil 1/4 tsp"},{"type":"item","text":"1/2 tsp dried parsley 1/4 tsp"},{"type":"item","text":"1/2 tsp salt 1/4 tsp"},{"type":"item","text":"1/2 tsp black pepper 1/4 tsp"}],"instructions":[{"type":"step","text":"In a medium bowl or jar, whisk together all ingredients until smooth and creamy. Serve immediately or store in an airtight container in the fridge until ready to serve."}],"notes":[],"extra":""},{"id":"italian-wedding-soup-with-turkey-meatballs","title":"italian wedding soup with turkey meatballs","description":"","source":{"label":"","url":""},"image":"","servings":"","categories":[],"ingredients":[{"type":"item","text":"10-12 cups chicken broth"},{"type":"item","text":"2 Tbs olive oil"},{"type":"item","text":"1 lb ground turkey lean"},{"type":"item","text":"1/2 cup panko"},{"type":"item","text":"1/3 cup parsley finely chopped"},{"type":"item","text":"1 egg"},{"type":"item","text":"3-4 minced garlic cloves"},{"type":"item","text":"1 tsp salt kosher"},{"type":"item","text":"1/2 tsp pepper"},{"type":"item","text":"1/2 cup parmesan"},{"type":"item","text":"3/4 cup orzo"},{"type":"item","text":"3 cups packed baby spinach"},{"type":"item","text":"1 lemon, zested and halved"},{"type":"item","text":"1 tsp black garlic added while simmering"},{"type":"item","text":"1 TBS umami powder"},{"type":"item","text":"1-2 cups? broiled carrot large chop diagonal"},{"type":"item","text":"1-2 cups carrots cut largely broiled"}],"instructions":[{"type":"step","text":"Step 1\nCombine broth with 2 TBS olive oil in large pot-- bring to boil"},{"type":"step","text":"Step 2\nAdd turkey, panko, parsley, egg, garlic, salt, pepper, \u0026 1/2 cup parmesan to a large bowl- mix\nroll into 1\u00261/2 inch balls\ntransfer to pan for broiling"},{"type":"step","text":"Step 3\nHeat broiler to high\nset oven rack 6-8 inches away\nbroil meatballs until browned on each side"},{"type":"step","text":"Step 4\nAdd pasta to boiling broth and cook until al-dente\nlower heat to low simmer"},{"type":"step","text":"Step 5\nAdd meatballs to broth and simmer 3-5 minutes until warmed through\nremove from heat\nadd spinach and lemon zest and stir\nseason to taste with salt and pepper"},{"type":"step","text":"Step 6\nDivide soup among 4 bowls\ndrizzle each with olive oil, parmesan, and a squeeze of lemon juice"}],"notes":[],"extra":""},{"id":"jalebi","title":"jalebi","description":"www.youtube.com/watch?v=pdFm9Rnz4H8","source":{"label":"","url":""},"image":"","servings":"","categories":[],"ingredients":[{"type":"item","text":"INGREDIENTS:-"},{"type":"item","text":"Flour 1 cup /150g"},{"type":"item","text":"Cornflour 4 tbsp"},{"type":"item","text":"Baking soda 1/4 tsp"},{"type":"item","text":"Food colour 1/4tsp"},{"type":"item","text":"(Yellow/Orange)"},{"type":"item","text":"Yogurt 4 tbsp"},{"type":"item","text":"Water 150ml"},{"type":"item","text":"vanillin"},{"type":"item","text":"amylase pinch"},{"type":"item","text":"Ingredients for syrup:-"},{"type":"item","text":"Sugar 3 cups"},{"type":"item","text":"Water 1 \u0026 1/2 cups"},{"type":"item","text":"Lemon juice 2 tsp"},{"type":"item","text":"Cardamom 6-7- not this"},{"type":"item","text":"2 tbs honey"}],"instructions":[{"type":"step","text":"-"}],"notes":[],"extra":""},{"id":"jamaican-beef-patties","title":"Jamaican Beef Patties","description":"How to make Jamaican Beef Patties","source":{"label":"","url":""},"image":"images/jamaican_beef_patties_qkc7t.jpg","servings":"?? recipe is adjusted for 1 lb of beef","categories":[],"ingredients":[{"type":"item","text":"bake @ 380F-400F ~ 20-30 minutes"},{"type":"item","text":"For the Crust"},{"type":"item","text":"♥ 2cups all purpose flour"},{"type":"item","text":"♥ 4g salt"},{"type":"item","text":"♥ 6Tbs butter, softened"},{"type":"item","text":"♥ 6Tbs shortening"},{"type":"item","text":"♥ 150 ml/grams chilled water"},{"type":"item","text":"--1/2 tsp bouillon into water + sm amt milk pwdr"},{"type":"item","text":"♥ 2tsp curry"},{"type":"item","text":"♥ 1tsp turmeric"},{"type":"item","text":"~ pinch of msg"},{"type":"item","text":"--refrigerate for 30 mins--"},{"type":"item","text":"For the Filling"},{"type":"item","text":"♥ 1 lb ground beef"},{"type":"item","text":"-- sm amt of bbq (Sweet Baby Ray's honey chipotle) + bouillon + ketchup,"},{"type":"item","text":"shattah, soy sauce, thyme (thyme is optional)--"},{"type":"item","text":"♥ 1/2 cup onion, chopped"},{"type":"item","text":"♥ 1/2 cup bell pepper, chopped"},{"type":"item","text":"♥ 2 cloves garlic, {or less}"},{"type":"item","text":"♥ 1/2 cup scallions"},{"type":"item","text":"♥ 1 Tbs ginger"},{"type":"item","text":"♥ 1 sm carrot, chopped/diced"},{"type":"item","text":"♥ 4.57 Tbs bread crumbs"},{"type":"item","text":"♥ 1 tsp turmeric"},{"type":"item","text":"♥ 1 tsp bl pepper"},{"type":"item","text":"♥ 1 tsp paprika"},{"type":"item","text":"♥ .57 tsp jalapeno powder"},{"type":"item","text":"♥ 1 Tbs all purpose seasoning"},{"type":"item","text":"♥ 1 Tbs complete seasoning"},{"type":"item","text":"~make eggwash~"},{"type":"item","text":"-1 egg"},{"type":"item","text":"-splash of water"}],"instructions":[{"type":"step","text":"-"}],"notes":[],"extra":""},{"id":"lahore-fish","title":"lahore fish","description":"","source":{"label":"","url":""},"image":"","servings":"","categories":[],"ingredients":[{"type":"item","text":"45g tamarind"},{"type":"item","text":"45g besan"},{"type":"item","text":".9 lemon"},{"type":"item","text":"2tsp salt"},{"type":"item","text":"1.33tsp red chili powder"},{"type":"item","text":"1.33tsp red chili flakes"},{"type":"item","text":"3.625tsp coriander"},{"type":"item","text":"2.66tsp cumin"},{"type":"item","text":".225tsp garam masala"},{"type":"item","text":"2lbs fish"}],"instructions":[{"type":"step","text":"-"}],"notes":[],"extra":""},{"id":"large-soft-pretzels","title":"Large Soft Pretzels","description":"","source":{"label":"https://www.publix.com/recipe/homemade-soft-pretzels","url":"https://www.publix.com/recipe/homemade-soft-pretzels"},"image":"images/large_soft_pretzels_xrsgi.jpg","servings":"8","categories":[],"ingredients":[{"type":"item","text":"11 cups warm water (100°F–110°F), divided"},{"type":"item","text":"2 tablespoons sugar"},{"type":"item","text":"1 (1⁄4 oz) envelope active dry yeast"},{"type":"item","text":"6 tablespoons salted butter"},{"type":"item","text":"5 teaspoons kosher salt, divided"},{"type":"item","text":"3 cups flour"},{"type":"item","text":"1 teaspoon caraway seeds"},{"type":"item","text":"Nonstick cooking spray"},{"type":"item","text":"Plastic wrap"},{"type":"item","text":"Parchment paper"},{"type":"item","text":"3⁄4 cup baking soda"},{"type":"item","text":"Spicy brown mustard (optional)"}],"instructions":[{"type":"step","text":"Combine in bowl of stand mixer: 1 cup warm water and sugar until blended. Sprinkle yeast on top and set aside 5 minutes until mixture begins to foam. Add butter to microwave-safe bowl; microwave on HIGH in 10 second intervals until just melted."},{"type":"step","text":"Add to yeast mixture: 1 teaspoon salt, flour, melted butter, and caraway seeds; mix on low, using dough hook attachment, until well combined. Raise speed to medium and knead 5–6 minutes, until dough is smooth and pulls away from side of bowl. Remove dough from bowl; clean bowl and coat with spray. Return dough to bowl, cover bowl with plastic wrap and set aside in warm place about 1 hour, until dough has doubled in size."},{"type":"step","text":"Preheat oven to 450°F. Line 2 baking sheets with parchment paper and coat with spray; set aside. Add remaining 10 cups water and baking soda to large saucepan; bring to boil on high. Turn dough out onto lightly sprayed work surface; divide into 8 equal pieces. Roll out each piece of dough into a 24-inch rope. Lay rope in a U-shape. Twist ends of rope over each other 2–3 times, then press end into bottom center of U to form a pretzel. Arrange pretzel on parchment-lined baking sheets. Repeat with remaining ropes."},{"type":"step","text":"Add pretzels to boiling water, 1 at a time; and boil 30 seconds. Remove from water and arrange on baking sheet; sprinkle each pretzel with 1/2 teaspoon remaining salt. Repeat process until all pretzels are boiled."},{"type":"step","text":"Bake pretzels 10–12 minutes, until dark golden brown. Transfer to cooling rack and set aside 5 minutes before serving. Serve with spicy brown mustard (if desired) and Beer Cheese Sauce (see recipe)."}],"notes":[],"extra":""},{"id":"levain-cookies","title":"Levain Cookies","description":"NO CONVECTION","source":{"label":"","url":""},"image":"images/levain_cookies_czigf.jpg","servings":"NO CONVECTION","categories":[],"ingredients":[{"type":"item","text":"1.5 cups (230g) cake flour"},{"type":"item","text":"2 cups (275g) all purpose flour"},{"type":"item","text":"1.5 tsp (5g) kosher salt"},{"type":"item","text":"2 tsp (8g) corn starch"},{"type":"item","text":"1/2 tsp (6g) baking soda"},{"type":"item","text":"1.25 cups (280g) unsalted butter"},{"type":"item","text":"1.25 cups (285g) brown sugar"},{"type":"item","text":"1/2 cup (115g) white granulated sugar"},{"type":"item","text":"2 eggs"},{"type":"item","text":"3 egg yolks"},{"type":"item","text":"2 cups (165g) walnuts lightly toasted"},{"type":"item","text":"13 oz (368.45g) chopped chocolate"}],"instructions":[{"type":"step","text":"In a medium saucepan, melt unsalted butter and set to the side to cool."},{"type":"step","text":"Roughly chop the dark chocolate."},{"type":"step","text":"In a medium size bowl, combine cake flour, all-purpose flour, kosher salt, cornstarch, and baking soda. Whisk together."},{"type":"step","text":"Using a stand mixer fitted with the whisk attachment, add light brown sugar and granulated sugar. Whisk together on medium speed then slowly stream in the butter."},{"type":"step","text":"Once combined add in the eggs one at a time followed by the egg yolks."},{"type":"step","text":"Once smooth switch to the paddle attachment and mix in the flour mixture until smooth."},{"type":"step","text":"Add in rough chopped walnuts and chopped chocolate. Mix until combined."},{"type":"step","text":"Place in a bowl, cover, and refrigerate for at least 45 minutes."},{"type":"step","text":"Weigh each dough ball out to 5.9oz and place on a parchment lined baking sheet."},{"type":"step","text":"Bake in a 415F for 10-13 minutes. (lower if needed to 400F or less)"},{"type":"step","text":"NO CONVECTION"},{"type":"step","text":"Set on a wire rack to cool before serving."}],"notes":[],"extra":"I made this."},{"id":"macaroni-and-cheese","title":"Macaroni and Cheese","description":"elbow pasta in some cheeses etc","source":{"label":"","url":""},"image":"","servings":"","categories":[],"ingredients":[{"type":"item","text":"33g white cheddar"},{"type":"item","text":"33g mozzarella"},{"type":"item","text":"33g queso"},{"type":"item","text":"1c milk (1/2 cream, 1/2 water + milk powder)"},{"type":"item","text":"4g sodium citrate"},{"type":"item","text":"2.5 Tbs uns butter"},{"type":"item","text":"15g ap flour"},{"type":"item","text":"1/3 tsp salt"},{"type":"item","text":"single slice American cheese"},{"type":"item","text":"some pasta, more than 1/4 lb"},{"type":"item","text":"* * save extra cheese sauce and freeze **"}],"instructions":[{"type":"step","text":"-"}],"notes":[],"extra":""},{"id":"navy-muslim-bean-pie","title":"Navy (Muslim) Bean Pie","description":"Muhammad Ali's favorite pie","source":{"label":"https://tastecooking.com/recipes/bean-pie/","url":"https://tastecooking.com/recipes/bean-pie/"},"image":"images/navy_muslim_bean_pie_b19sd.jpg","servings":"2 whole pies","categories":[],"ingredients":[{"type":"item","text":"1 prepared pie crust"},{"type":"item","text":"1⁄2 C (1 stick) unsalted butter, room temperature"},{"type":"item","text":"1 1⁄2 C sugar"},{"type":"item","text":"2 TBSP cinnamon"},{"type":"item","text":"1⁄4 TSP nutmeg"},{"type":"item","text":"1 TBSP cornstarch"},{"type":"item","text":"1⁄4 TSP salt"},{"type":"item","text":"3 eggs"},{"type":"item","text":"1 1⁄2 C cooked navy beans"},{"type":"item","text":"1 C evaporated milk"},{"type":"item","text":"1 TSP vanilla extract"},{"type":"item","text":"Zest of 1 lemon"},{"type":"heading","text":"PIE CRUST:"},{"type":"item","text":"1⁄2 C whole wheat flour"},{"type":"item","text":"3⁄4 C all purpose flour"},{"type":"item","text":"1⁄2 TSP salt"},{"type":"item","text":"1 TSP sugar"},{"type":"item","text":"1⁄2 C (1 stick) cold butter"},{"type":"item","text":"4-6TBS ice water"},{"type":"item","text":"Adapted from Lana Shabazz’s iconic recipe, this pie is smooth, sweet, and custard-like, and its spices shine. Don’t leave out the lemon zest: it’s a small but brilliant touch that ties the whole thing together."}],"instructions":[{"type":"heading","text":"PIE CRUST:"},{"type":"step","text":"Toss together the flours, salt, and sugar. Cut the butter into 1⁄2-inch chunks and add it to the flour mixture. Using a pastry cutter, a fork, or your hands, work the butter into the flour mixture until the chunks are roughly the size of peas. Add the water, one tablespoon at a time, using a fork to stir it into the mixture. Stir until the dough begins to come together and form a shaggy mass. This may take 4 tablespoons of water, or up to 6 tablespoons. Once a rough dough has formed, dump the dough onto a lightly floured surface and gently form it into a flat disc. Wrap the disc tightly in plastic wrap, then place in the refrigerator and chill for at least 30 minutes, preferably 2 hours or more."},{"type":"heading","text":"BEAN PIE:"},{"type":"step","text":"Preheat the oven to 450°F. Roll out your pie crust, then grease and line a 9-inch pie plate with it. Set in the refrigerator to chill while you make the filling."},{"type":"step","text":"In a food processor, blend the butter and sugar until combined. Add the cinnamon, nutmeg, cornstarch, and salt and pulse to combine. Add the eggs, one at a time, and pulse, waiting until each egg is fully combined before adding the next one. Next add the beans, and process continually until the mixture is completely smooth. Add the evaporated milk, vanilla extract, and lemon zest and blend until they are completely combined and the mixture is smooth."},{"type":"step","text":"Pour the filling into the pie crust. Cook for five minutes, then lower the temperature to 325°F and bake for 45 minutes. Let cool before serving, or else the pie won’t cut cleanly."}],"notes":[],"extra":""},{"id":"nutribun-also-focaccia","title":"Nutribun also focaccia","description":"","source":{"label":"","url":""},"image":"images/nutribun_also_focaccia_j30p1.jpg","servings":"","categories":[],"ingredients":[{"type":"item","text":"600g bread flour"},{"type":"item","text":"84g dry milk"},{"type":"item","text":"72g sugar"},{"type":"item","text":"30g oil"},{"type":"item","text":"15g salt"},{"type":"item","text":"18g nutritional yeast"},{"type":"item","text":"360+g water"},{"type":"item","text":"5g rr yeast"},{"type":"item","text":"OR"},{"type":"item","text":"WITH poolish + autolysing"},{"type":"item","text":"450g bread flour (FOR WHOLE WHEAT, REPLACE 200G OF 450G WITH WHOLE WHEAT)"},{"type":"item","text":"84g dry milk"},{"type":"item","text":"72g sugar"},{"type":"item","text":"30g oil"},{"type":"item","text":"18g nutritional yeast"},{"type":"item","text":"300ish g/ml water or lessss"},{"type":"item","text":"later...."},{"type":"item","text":"5g rr yeast"},{"type":"item","text":"15g salt"},{"type":"item","text":"150g poolish"}],"instructions":[{"type":"step","text":"knead 10 minutes, rest 1-2 hours\n197g dough balls OR 98g\nrest 1-2hrs\ndust with 10g semolina mixed with 50g ap flour\nbake 350F (higher?)~15 minutes + steam"},{"type":"step","text":"POOLISH + AUTOLYSE\nmix together bread flour, dry milk, sugar, nutritional yeast, oil, and water\nlet rest 30 minutes\nthen, add some water to dough (for salt and yeast)\nadd salt and yeast\ncombine with wet hand until yeast and salt evenly distributed throughout\nrest 30 minutes\n1st strength building fold\nrest 30 minutes\n2nd strength building fold\nPut in fridge overnight (at least 4 hours) if putting in fridge\nif not, let sit out 1-2 hours ish"}],"notes":[],"extra":"I made this."},{"id":"oil-gummies-pectin-and-gelatin","title":"oil gummies (pectin and gelatin)","description":"","source":{"label":"","url":""},"image":"images/oil_gummies_pectin_and_gelatin_6d81v.jpg","servings":"180-200 lil cubes, or 45-50 mold-sized squares","categories":[],"ingredients":[{"type":"item","text":"160g coconut oil"},{"type":"item","text":"150g sugar + 100g water + 100g corn syrup"},{"type":"item","text":"35g gelatin + 160g juice"},{"type":"item","text":"1TBSP lecithin"},{"type":"item","text":"10g pectin"},{"type":"item","text":"1/3tsp potassium sorbate"},{"type":"item","text":"100g gelatin"},{"type":"item","text":"1 dram bottle flavouring oil"}],"instructions":[{"type":"step","text":"bloom 160g juice with 35g gelatin"},{"type":"step","text":"boil to 220-250F: 150g sugar + 90g water + 100g corn syrup"},{"type":"step","text":"let syrup coil to 200F"},{"type":"step","text":"add 10g of pectin, 1/3tsp potassium sorbate, stir out clumps"},{"type":"step","text":"add 100g of gelatin, stirring out clumps"},{"type":"step","text":"add bloomed gelatin, lecithin"},{"type":"step","text":"add oil"},{"type":"step","text":"add flavouring oil"},{"type":"step","text":"whisk on low heat, consistently, until mixed and emulsified. fold edges into center as stirring"}],"notes":[],"extra":""},{"id":"pancakes-2","title":"Pancakes","description":"","source":{"label":"","url":""},"image":"","servings":"","categories":[],"ingredients":[{"type":"item","text":"1 cup all-purpose flour, (spooned and leveled) MORE"},{"type":"item","text":"2 tablespoons sugar (maybe more)"},{"type":"item","text":"2 teaspoons baking powder"},{"type":"item","text":"1⁄2 teaspoon salt"},{"type":"item","text":"1 cup milk LESS"},{"type":"item","text":"2 tablespoons unsalted butter, melted, or vegetable oil"},{"type":"item","text":"1 large egg"},{"type":"item","text":"1 tablespoon vegetable oil"},{"type":"item","text":"Lil vanilla bean"}],"instructions":[{"type":"step","text":"mix and adjust according to preference of thickness"}],"notes":[],"extra":""},{"id":"pancakes","title":"Pancakes","description":"","source":{"label":"","url":""},"image":"","servings":"8-10","categories":[],"ingredients":[{"type":"heading","text":"Ingredients:"},{"type":"item","text":"1 1/2 cups of flour (210g)"},{"type":"item","text":"3 tablespoons of sugar (48g)"},{"type":"item","text":"2 teaspoons of baking powder (9g)"},{"type":"item","text":"1 teaspoon of salt (5g)"},{"type":"item","text":"1 teaspoon of baking soda (5g)"},{"type":"item","text":"2 eggs (Room Temperature)"},{"type":"item","text":"1 cup of milk/buttermilk (240ml)"},{"type":"item","text":"2 tablespoons of melted butter (28g)"},{"type":"item","text":"1 teaspoon of vanilla extract (5ml)"}],"instructions":[{"type":"step","text":"mix dry\nwhisk eggs, add milk (i used buttermilk), melted butter, + vanilla\nwhisk\nadd wet to dry, folding in with silicon spatula, do not overmix\nCLUMPS are good/okay do not overmix\nscoop out with icecream scoop onto preheated + buttered pan\ncook ~ 2-4 mins each side on low-med, med heat."}],"notes":[],"extra":""},{"id":"pumpkin-cake-banana-cake-mod","title":"Pumpkin Cake (banana cake mod)","description":"","source":{"label":"","url":""},"image":"","servings":"two cakes","categories":[],"ingredients":[{"type":"item","text":"3/4 cup butter/shortening (half and half) (BROWN THE BUTTER, Set in freezer ~ 20min) 7TBS butter, 6 TBS shortening)"},{"type":"item","text":"2.5 cups sugar"},{"type":"item","text":"some molasses"},{"type":"item","text":"3 eggs"},{"type":"item","text":"1.5 cups pureed pumpkin"},{"type":"item","text":"3 cups sifted flour (half cake half all purpose)"},{"type":"item","text":"3/4 tsp baking powder"},{"type":"item","text":"1/3 cup buttermilk"},{"type":"item","text":"1 tsp baking soda"},{"type":"item","text":"1 tsp salt"},{"type":"item","text":"small dash/shake nutmeg"},{"type":"item","text":"1-2 tsp cinnamon"},{"type":"item","text":"dash ground ginger"},{"type":"item","text":"vanilla optional (not used)"},{"type":"item","text":"For Frosting"},{"type":"item","text":"1.5 box (cups?) (~ half a bag) (bag = 2lb or 907g) powdered sugar"},{"type":"item","text":"3/4 cup (1.5 sticks) butter"},{"type":"item","text":"3/4 cup pumpkin puree"},{"type":"item","text":"1.5 tsp lemon juice"},{"type":"item","text":"1/2 pkg cream cheese (4oz?)"},{"type":"heading","text":"HALF Recipe:"},{"type":"item","text":"4 TBS browned butter, 3 TBS shortening"},{"type":"item","text":"1.25 Cup sugar"},{"type":"item","text":"molasses"},{"type":"item","text":"1.5 Eggs"},{"type":"item","text":"3/4 Cup pumpkin puree"},{"type":"item","text":"1.5 Cups flour, sifted (3/4 C AP FL, 3/4 C cake flour)"},{"type":"item","text":"3/8 tsp baking powder"},{"type":"item","text":"2 TBS \u0026 2tsp buttermilk"},{"type":"item","text":"1/2 tsp baking soda"},{"type":"item","text":"1/2 tsp salt"},{"type":"item","text":"small dash (1/8 tsp?) nutmeg"},{"type":"item","text":"1 ish tsp cinnamon"},{"type":"item","text":"dash (1/8tsp-1/4 tsp) ground ginger"},{"type":"item","text":"optional vanilla"}],"instructions":[{"type":"step","text":"Cream together shortening, browned slightly firmed butter, sugar, \u0026 molasses blending well."},{"type":"step","text":"Add well beaten eggs and pumpkin, beat well"},{"type":"step","text":"Sift flours then resift with dry ingredients (salt, b soda, b powder, cinnamon, nutmeg, ginger, salt)"},{"type":"step","text":"Add dry alternatively with wet mixture of buttermilk combined"},{"type":"step","text":"In greased, floured pans bake at 350F for about 5-7 minutes, then REDUCE temp to 330-345 for 5 minutes, then reduce more if needed for rest of cooking time (about 25-35 minutes)"},{"type":"step","text":"Internal temp should be about 190F-200F (closer to 190F)"},{"type":"step","text":"Let cool"},{"type":"heading","text":"For Frosting:"},{"type":"step","text":"Cream all ingredients together"},{"type":"step","text":"Spread onto cooled cake or leave separate for individual slices"}],"notes":[],"extra":"I made this."},{"id":"ranch","title":"Ranch","description":"","source":{"label":"","url":""},"image":"","servings":"","categories":[],"ingredients":[{"type":"item","text":"1⁄2 Cup Mayonnaise"},{"type":"item","text":"▢1⁄4 Cup Sour Cream, or Greek yogurt"},{"type":"item","text":"▢2 teaspoons Dried Chives"},{"type":"item","text":"▢1⁄2 teaspoon Dried Dill LESS"},{"type":"item","text":"▢1⁄2 teaspoon Dried Parsley"},{"type":"item","text":"▢1⁄2 teaspoon Garlic Powder"},{"type":"item","text":"▢1⁄2 teaspoon Onion Powder"},{"type":"item","text":"▢1⁄4 teaspoon Salt"},{"type":"item","text":"▢1⁄8 teaspoon pepper"},{"type":"item","text":"▢3⁄4 Cup Buttermilk, or regular whole milk"}],"instructions":[{"type":"step","text":"-"}],"notes":[],"extra":""},{"id":"salmon-in-air-fryer-marinade","title":"Salmon in Air Fryer (marinade)","description":"tasty","source":{"label":"","url":""},"image":"","servings":"2 filet","categories":[],"ingredients":[{"type":"item","text":"key west key lime juice"},{"type":"item","text":"1/2 tsp bl pepper"},{"type":"item","text":"1 TBS garlic"},{"type":"item","text":"1 TBS paprika"},{"type":"item","text":"1 TBS onion powder"},{"type":"item","text":"1 tsp black garlic"},{"type":"item","text":"1 tsp celery salt"},{"type":"item","text":"2 TBS dijon"},{"type":"item","text":"2 TBS olive oil"},{"type":"item","text":"1.5 tsp molasses"}],"instructions":[{"type":"step","text":"do"}],"notes":[],"extra":""},{"id":"sea-bass-with-cannellini-bean-stew","title":"Sea Bass with Cannellini Bean Stew","description":"","source":{"label":"https://www.feastingathome.com/sea-bass-with-cannellini-bean-stew/","url":"https://www.feastingathome.com/sea-bass-with-cannellini-bean-stew/"},"image":"images/sea_bass_with_cannellini_bean_stew_1gi41.jpg","servings":"","categories":[],"ingredients":[{"type":"item","text":"2 T olive oil"},{"type":"item","text":"1 medium onion, diced"},{"type":"item","text":"1 cup peeled, diced carrot ( 2 carrots)"},{"type":"item","text":"1 cup diced celery ( 2 stalks)"},{"type":"item","text":"3– 4 smashed and roughly chopped garlic cloves"},{"type":"item","text":"2 cups diced tomatoes ( or one 1 can, diced)"},{"type":"item","text":"3 cups cannellini beans (2 cans rinsed and drained) or 1 1⁄2 cups dried beans, soaked overnight."},{"type":"item","text":"2 – 4 cups chicken stock ( 2 cups if using canned beans, 4 cups if using dried beans)"},{"type":"item","text":"1 cup water (only if using dried beans)"},{"type":"item","text":"2 Tablespoons fresh sage (or thyme, or rosemary)"},{"type":"item","text":"1⁄2 teaspoon kosher salt"},{"type":"item","text":"1⁄4 teaspoon cracked pepper"},{"type":"item","text":"4 four-ounce sea bass fillets ( or thick-cut true cod, escolar, halibut, black cod)"},{"type":"item","text":"oil, salt and pepper for fish"},{"type":"item","text":"Italian parsley for garnish (or make leek oil or gremolata)"}],"instructions":[{"type":"step","text":"In a medium-large heavy-bottomed pot, heat oil over medium-high heat. Add onions, and stir for two minutes. Add carrots, celery and garlic, turn heat to medium and sauté for about 5 minutes, stirring occasionally."},{"type":"step","text":"If using canned beans, add them, along with the 2 cups stock, herbs and tomatoes, salt and pepper, and bring to a boil. Turn heat down to low, cover and simmer gently for 10-15 minutes. Alternatively, if using dried beans, make sure to soak them in ample water overnight or up to 24 hours. (This will prevent gastric issues and shorten cooking time. ) After the carrots, celery and garlic have been sautéing for 5 minutes. Add the dried, soaked beans and 4 cups stock. Add 1 additional cup water. Add the herbs and salt. Bring to a boil on high heat. Cover, turn to low heat and let simmer 1-1 1/2 hours, or until the beans are tender, adding more water if needed. Then add pepper and tomatoes. Continue simmering another 1⁄2 hour. If the stew is too brothy for you, leave the lid off and keep it at a gentle simmer, letting it reduce a bit- however, I really enjoy it a little brothy."},{"type":"step","text":"Pan Sear the fish: Heat 1-2 T olive oil in a cast-iron skillet, over medium-high heat. Pat dry fish with paper towels and season generously with kosher salt and pepper. Sear each side until a golden crust forms on the fish, and turn the heat down to cook through to the desired doneness, taking care not to overcook."},{"type":"step","text":"Place the stew in a wide shallow bowl, top with seared fish and garnish with fresh Italian parsley."},{"type":"step","text":"If feeling fancy make Gremolata or Leek Oil and drizzle over top."}],"notes":[],"extra":""},{"id":"serious-eats-halal-cart-style-chicken-and-rice-with-white-sauce","title":"Serious Eats' Halal Cart-Style Chicken and Rice with White Sauce","description":"","source":{"label":"https://www.seriouseats.com/serious-eats-halal-cart-style-chicken-and-rice-white-sauce-recipe","url":"https://www.seriouseats.com/serious-eats-halal-cart-style-chicken-and-rice-white-sauce-recipe"},"image":"images/serious_eats39_halal_cart_style_chicken__hx7sv.jpg","servings":"4","categories":[],"ingredients":[{"type":"heading","text":"For the chicken:"},{"type":"item","text":"2 tablespoons fresh lemon juice"},{"type":"item","text":"1 tablespoon chopped fresh oregano"},{"type":"item","text":"1/2 teaspoon ground coriander seed"},{"type":"item","text":"3 garlic cloves, roughly chopped (about 1 1/2 tablespoons)"},{"type":"item","text":"1/4 cup light olive oil"},{"type":"item","text":"Kosher salt and freshly ground black pepper"},{"type":"item","text":"2 pounds boneless, skinless chicken thighs, trimmed of excess fat (6 to 8 thighs)"},{"type":"item","text":"1 tablespoon vegetable or canola oil"},{"type":"heading","text":"For the rice:"},{"type":"item","text":"2 tablespoons unsalted butter"},{"type":"item","text":"1/2 teaspoon turmeric"},{"type":"item","text":"1/4 teaspoon ground cumin"},{"type":"item","text":"1 1/2 cups long-grain or Basmati rice"},{"type":"item","text":"2 1/2 cups chicken broth"},{"type":"item","text":"Kosher salt and freshly ground black pepper"},{"type":"heading","text":"For the sauce:"},{"type":"item","text":"1/2 cup mayonnaise"},{"type":"item","text":"1/2 cup Greek yogurt"},{"type":"item","text":"1 tablespoon sugar"},{"type":"item","text":"2 tablespoons white vinegar"},{"type":"item","text":"1 teaspoon lemon juice"},{"type":"item","text":"1/4 cup chopped fresh parsley"},{"type":"item","text":"Kosher salt and freshly ground black pepper"},{"type":"heading","text":"To serve:"},{"type":"item","text":"1 head iceberg lettuce, shredded"},{"type":"item","text":"1 large tomato, cut into wedges"},{"type":"item","text":"Fluffy pocketless pita bread, brushed in butter, lightly toasted, and cut into 1 × 3-inch strips"},{"type":"item","text":"Harissa-style hot sauce, for serving"}],"instructions":[{"type":"step","text":"For the chicken: Combine the lemon juice, oregano, coriander, garlic, and olive oil in a blender. Blend until smooth. Season the marinade to taste with kosher salt and black pepper. Place the chicken in a 1-gallon zipper-lock bag and add half of the marinade (reserve the remaining marinade in the refrigerator). Turn the chicken to coat, seal the bag, and marinate the chicken in the refrigerator for at least 1 hour and up to 4 hours, turning occasionally to redistribute the marinade (see Note)."},{"type":"step","text":"Remove the chicken from the bag and pat it dry with paper towels. Season with kosher salt and pepper, going heavy on the pepper. Heat the oil in a 12-inch heavy-bottomed cast iron or stainless-steel skillet over medium-high heat until it is lightly smoking. Add the chicken pieces and cook without disturbing until they are lightly browned on the first side, about 4 minutes. Using tongs, flip the chicken. Reduce the heat to medium and cook until the chicken is cooked through and the center of each thigh registers 165°F. on an instant-read thermometer, about 6 minutes longer. Transfer the chicken to a cutting board and allow to cool for 5 minutes."},{"type":"step","text":"Using a chef’s knife, roughly chop the chicken into 1/2- to 1/4-inch chunks. Transfer to a medium bowl, add the remaining marinade, cover loosely with plastic, and refrigerate while you cook the rice and prepare the sauce."},{"type":"step","text":"For the rice: Melt the butter over medium heat in a large Dutch oven. Add the turmeric and cumin and cook until fragrant but not browned, about 1 minute. Add the rice and stir to coat. Cook, stirring frequently, until the rice is lightly toasted, about 4 minutes. Add the chicken broth. Season to taste with salt and pepper. Raise the heat to high and bring to a boil. Cover, reduce to a simmer, and cook for 15 minutes without disturbing. Remove from the heat and allow to rest until the water is completely absorbed and the rice is tender, about 15 minutes."},{"type":"step","text":"For the sauce: In a small bowl, combine the mayonnaise, yogurt, sugar, vinegar, lemon juice, parsley, and 2 teaspoons black pepper. Whisk to combine. Season to taste with salt."},{"type":"step","text":"To serve: Return the entire contents of the chicken bowl (chicken, marinade, and all juices) to the skillet. Cook over medium-high heat, stirring occasionally, until heated through. To serve, divide the rice, lettuce, tomato, and toasted pita bread evenly among four to six plates. Pile the chicken on top of the rice. Top with the white sauce and hot sauce. Serve immediately, passing extra sauce at the table."},{"type":"step","text":"Special equipment"},{"type":"step","text":"Blender, 12-inch cast iron skillet or stainless steel skillet"}],"notes":["Do not marinate the chicken longer than 4 hours or it’ll get a mushy texture. If you must delay cooking the chicken for any reason, remove it from the marinade, pat it dry with paper towels, and refrigerate until ready to cook."],"extra":""},{"id":"sesame-beef-thai-noodle-dinner","title":"Sesame Beef Thai Noodle Dinner","description":"","source":{"label":"https://www.homemadefoodjunkie.com/sesame-beef-thai-noodle-dinner/","url":"https://www.homemadefoodjunkie.com/sesame-beef-thai-noodle-dinner/"},"image":"images/sesame_beef_thai_noodle_dinner_dyn8x.jpg","servings":"","categories":[],"ingredients":[{"type":"item","text":"1 8 oz. package Thai rice noodles"},{"type":"item","text":"1 lb. cooked roast-sliced thinly against the grain and then into strips"},{"type":"heading","text":"(for the marinade)For raw meat directions look to the bottom of the recipe in the notes section)"},{"type":"item","text":"1/2 Cup soy (or Tamari) Sauce"},{"type":"item","text":"1/4 Cup brown sugar"},{"type":"item","text":"1 inch chunk ginger sliced thinly"},{"type":"item","text":"2 Tablespoons balsamic vinegar, or sherry"},{"type":"item","text":"1 teaspoon chili paste or hot chili sesame oil to taste"},{"type":"item","text":"1 tablespoon regular sesame oil"},{"type":"item","text":"2 smashed cloves garlic"},{"type":"item","text":"2 Tablespoons cornstarch"},{"type":"item","text":"2 Tablespoons water"},{"type":"item","text":"1 lime cut in half and juiced"},{"type":"heading","text":"(for the stir-fry)"},{"type":"item","text":"2 Tablespoons avocado oil"},{"type":"item","text":"1 fresh pepper-sweet or hot"},{"type":"item","text":"1 onion-thinly sliced"},{"type":"item","text":"2 Cups snow peas"},{"type":"item","text":"1 Tablespoon sesame seeds for garnish"},{"type":"item","text":"parsley or cilantro for garnish"}],"instructions":[{"type":"step","text":"Layer sliced pre-cooked roast beef into a shallow baking dish (*for raw meat instructions see notes below the recipe)"},{"type":"step","text":"Mix all the marinade ingredients together in a 4 Cup bowl"},{"type":"step","text":"Pour the marinade over the beef slices and store in the fridge."},{"type":"step","text":"Heat the water for the noodles and cook according to the package directions"},{"type":"step","text":"Heat a large skillet to medium high and add oil."},{"type":"step","text":"Add the onions, peppers, snow peas and sesame seeds and cook until the onions are transparent letting the peppers and onions get a bit browned and caramelized."},{"type":"step","text":"Add the meat mixture and all it's marinade juices to the skillet and cook on low, until the marinade thickens into a nice sauce. A couple of minutes- stirring often!"},{"type":"step","text":"Remove from heat immediately after the sauce is thickened."},{"type":"step","text":"Drain the noodles and serve on the plate with the stir fry ladled on top or mixed in as you prefer."},{"type":"step","text":"Garnish with sesame seeds, pepper pieces, cilantro, parsley or fresh basil."}],"notes":["Raw meat instructions: Slice your raw steak or roast into thin slices, cutting across the grain of the meat. Marinate it as directed above in step 3 EXCEPT!!! Do NOT add the cornstarch yet! Add your marinated raw meat slices and all the marinade juice into a large skillet, before the vegetables, in step 6, and quickly cook it to browned on both sides. Meanwhile cook the vegetables in a separate skillet as directed in step 6. After the vegetables and meat is cooked, combine them in the large skillet and add the cornstarch mixed with water. Cook as directed in step 7 Enjoy your meal!"],"extra":""},{"id":"sesame-chicken","title":"Sesame Chicken","description":"","source":{"label":"","url":""},"image":"","servings":"","categories":[],"ingredients":[{"type":"item","text":"INGREDIENTS"},{"type":"item","text":"2 pounds boneless skinless chicken breast, cut into 1” cubes"},{"type":"item","text":"Marinade"},{"type":"item","text":"1/2 cup soy sauce"},{"type":"item","text":"1 tablespoon tahini"},{"type":"item","text":"1 teaspoon toasted sesame oil"},{"type":"item","text":"1 teaspoon kosher salt"},{"type":"item","text":"1/3 cup all-purpose flour"},{"type":"item","text":"1/3 cup corn starch"},{"type":"item","text":"1/4 cup water"},{"type":"item","text":"1 tablespoon rice vinegar"},{"type":"item","text":"1 1/2 teaspoons baking powder"},{"type":"item","text":"SAUCE"},{"type":"item","text":"3 tablespoons toasted sesame oil"},{"type":"item","text":"1 teaspoon minced fresh ginger"},{"type":"item","text":"1 teaspoon garlic chili paste"},{"type":"item","text":"1 3/4 cups chicken broth low sodium"},{"type":"item","text":"2 teaspoons sherry"},{"type":"item","text":"1/2 cup granulated sugar"},{"type":"item","text":"2 teaspoons tahini (make your own here)"},{"type":"item","text":"2 tablespoons corn starch"},{"type":"item","text":"2 tablespoons soy sauce"},{"type":"item","text":"1 1/2 tablespoons Champagne vinegar"},{"type":"item","text":"2 tablespoons toasted sesame seeds plus more for garnish"},{"type":"item","text":"Other"},{"type":"item","text":"Peanut oil to come up 3 inches up side of pan or wok"},{"type":"item","text":"Slivered scallions"}],"instructions":[{"type":"step","text":"INSTRUCTIONS\nMix all of the marinade ingredients in a medium bowl and add the chicken pieces to coat. Marinate for 30 minutes while you prepare the rest of the recipe."},{"type":"step","text":"In a medium sauce pan, heat sesame oil over medium low heat and add the ginger and garlic chili paste and cook to flavor the oil, three minutes."},{"type":"step","text":"Add the chicken broth, sherry, sugar and tahini and raise heat to medium and bring mixture to hot."},{"type":"step","text":"In a small bowl, mix corn starch with the soy sauce and vinegar to form a slurry."},{"type":"step","text":"Add this to the hot sauce and stir to thicken. Once hot and bubbling, remove to a back burner and keep hot on a low heat. If the sauce is not thick enough, mix another tablespoon of corn starch with a little water and slowly add to hot sauce until desired thickness. If too thick, add a little water or soy sauce to thin."},{"type":"step","text":"Start cooking the rice so that it is done once the chicken is done. If you have a rice cooker, this can be a make ahead item."},{"type":"step","text":"Toast the sesame seeds by placing in a dry pan and heating over medium heat for 4-5 minutes, tossing often. Remove to a dish after toasting so they don’t continue to cook in the hot pan."},{"type":"step","text":"When ready to fry, pour the chicken into a colander over a bowl to drain off some of the excess marinade. You can discard the drained marinade."},{"type":"step","text":"In a heavy pan or wok, heat peanut oil to 375 degrees F."},{"type":"step","text":"Heat oven to warm to hold cooked chicken between batches."},{"type":"step","text":"Fry wet chicken pieces in four batches to maintain the oil temperature, moving cooked chicken with a spider or strainer to a pan covered in paper towels. To fry, use tongs and quickly place one piece at a time into hot oil, not letting the pieces touch each other. Each batch will take about 3-4 minutes. Let the oil come back to 375 degrees F before starting the next batch. Keep cooked chicken in warm oven between batches."},{"type":"step","text":"Once all the chicken is cooked, place warm cooked chicken pieces in a large bowl and toss with the hot sauce. Add in the toasted sesame seeds and toss again, saving a little to sprinkle over the finished dish."},{"type":"step","text":"Serve on a platter or in a bowl with the reserved sesame seeds sprinkled over the dish and garnish with slivered scallions."},{"type":"step","text":"Serve with the cooked white rice on the side."}],"notes":[],"extra":""},{"id":"shawarma-couscous-bowls","title":"Shawarma Couscous Bowls","description":"","source":{"label":"","url":""},"image":"","servings":"","categories":[],"ingredients":[{"type":"item","text":"1/4 red onion, finely sliced"},{"type":"item","text":"2.5 oz couscous"},{"type":"item","text":"1oz dried apricot, diced small"},{"type":"item","text":"1 Tbs butter or ghee"},{"type":"item","text":"1 bell pepper or about 2-4 mini peppers, sliced"},{"type":"item","text":"~9 oz or 4 carrots, cut at a bias"},{"type":"item","text":"1 can or about 14 oz chickpeas"},{"type":"item","text":"small handful cilantro, chopped"},{"type":"item","text":"lemon juice"},{"type":"item","text":"1 TBS sour cream"},{"type":"item","text":"1 TBS yogurt"},{"type":"item","text":"harissa powder"},{"type":"item","text":"1 tsp garlic powder or onion powder"},{"type":"item","text":"salt"},{"type":"item","text":"pinch sugar"},{"type":"item","text":"2 tsp shawarma mix"},{"type":"item","text":"pepper"},{"type":"item","text":"bouillon"},{"type":"item","text":"3/4c water"}],"instructions":[{"type":"step","text":"Slice onion finely\nSoak onion in squeeze of lemon juice, pinch of salt and pinch of sugar\nSet aside\nWeigh out couscous, set aside\nDice apricots, slice peppers, cut carrots at bias, rinse and dry chickpeas\nPrepare sauce-- 1TBS yogurt, 1TBS sour cream, squeeze lemon, harissa, some water (1tsp at atime), salt, pepper\nToss chickpeas, carrots, and peppers in oil,\nToss chickpeas and carrots in 1 tsp shawarma spice blend each\nCook in oven at 375F ~ 20 minutes\nCook in air fryer 350F ~ 20 minutes\nMelt butter/ghee low med heat\nWhen melted, add couscous and toss in butter until lightly browned (2-4 minutes)\nOnce toasted, add some bouillon, 3/4 CUP water, and onion or garlic powder\nBring to boil\nOnce boiling, place heat on low/simmer, and cover\nCook couscous until done (6-10 minutes)\nOnce couscous is done, add diced apricot, stir\nPlate.\nPlace couscous, then chickpeas and veggies, then sauce, cilantro and pickled onions"}],"notes":[],"extra":""},{"id":"shawarma-spice","title":"Shawarma Spice","description":"","source":{"label":"","url":""},"image":"","servings":"","categories":[],"ingredients":[{"type":"item","text":"cut in half for less chicken"},{"type":"item","text":"1/2 cup extra virgin olive oil 1⁄4"},{"type":"item","text":"1 large onion, cut into small dice (or 1tbsp onion powder) 1⁄2"},{"type":"item","text":"1 tablespoon ras el hanout 1⁄2"},{"type":"item","text":"1 teaspoon sweet smoked paprika 1⁄2"},{"type":"item","text":"~1 teaspoon kosher salt 1⁄2"},{"type":"item","text":"1/2 cup roughly chopped cilantro, stems included (or 1/4cup dried cilantro) 1⁄4"},{"type":"item","text":"2 tablespoons harissa 1"}],"instructions":[{"type":"step","text":"-"}],"notes":["good amount for: 1lb meat + 8 extra large eggs + 30oz tomatoes + bread. or use necessary amount for other meats and vegetables","ras al hanuwt: www.amazon.com/dp/B07YVJQMNV/","harissa: www.amazon.com/dp/B00CB5EHAG/"],"extra":""},{"id":"snickerdoodles-with-icing","title":"Snickerdoodles with icing","description":"","source":{"label":"","url":""},"image":"","servings":"many","categories":[],"ingredients":[{"type":"item","text":"125g cake flour + 120g ap + 125g bread flour"},{"type":"item","text":"7g cream of tartar"},{"type":"item","text":"5g baking soda"},{"type":"item","text":"2g baking powder - or a big pinch, half teaspoon"},{"type":"item","text":"1/2 tsp kosher salt"},{"type":"item","text":"300g granulated sugar + molasses (try 200-250g)"},{"type":"item","text":"1/2 cup unsalted butter at room temperature"},{"type":"item","text":"1/2 cup butter flavored shortening"},{"type":"item","text":"1 large egg"},{"type":"item","text":"1 egg yolk"},{"type":"item","text":"1 1/2 teaspoons vanilla extract"},{"type":"item","text":"some cinnamon"},{"type":"heading","text":"Cinnamon Sugar Topping:"},{"type":"item","text":"3 tablespoons granulated sugar"},{"type":"item","text":"3 teaspoons ground cinnamon"},{"type":"item","text":"2 tablespoons turbinado sugar"},{"type":"item","text":"OVEN: 350"},{"type":"item","text":"TIME: 8-10 mins"},{"type":"item","text":"Icing"},{"type":"item","text":"~250g powdered sugar"},{"type":"item","text":"~1/2 vanillin sugar packet"},{"type":"item","text":"~Tbs corn syrup"},{"type":"item","text":"-as much cream as needed"},{"type":"item","text":"-pinch of salt"}],"instructions":[{"type":"step","text":"combine dry ingredients + cinnamon\nwhisk\ncombine (mixer) sugar with butter + molasses\nadd egg + egg yolk\nadd vanilla\nadd dry to wet and mix until combined\nchill in fridge\nroll into balls\ncoat with topping\nbake ~10 minutes\ncool\nicing"}],"notes":[],"extra":""},{"id":"sugar-toasted-almond-slices","title":"Sugar Toasted Almond Slices","description":"","source":{"label":"","url":""},"image":"","servings":"","categories":[],"ingredients":[{"type":"item","text":"1 cups Almond slices"},{"type":"item","text":"2 tablespoons Sugar (or more)"},{"type":"item","text":"1 dash Salt"},{"type":"item","text":"1 tbsp butter"}],"instructions":[{"type":"step","text":"Med heat on induction burner\nMelt butter\nAdd nuts \u0026 sugar \u0026 salt\ntoast until desired toastiness"}],"notes":[],"extra":""},{"id":"tahini","title":"tahini","description":"","source":{"label":"","url":""},"image":"","servings":"","categories":[],"ingredients":[{"type":"item","text":"130-ish g TAHINI PASTE ( this strongly depends on your brand)"},{"type":"item","text":"8g or 1 to 1.5 TSP SALT"},{"type":"item","text":"1/2 LEMON JUICED or 15g"},{"type":"item","text":"60-75g water MORE than this"},{"type":"item","text":"1/2 GARLIC CLOVE (sliced)"}],"instructions":[{"type":"step","text":"-"}],"notes":[],"extra":""},{"id":"thumbprint-cookies","title":"Thumbprint Cookies","description":"","source":{"label":"https://foodwishes.blogspot.com/2018/12/thumbprint-cookies-great-grandma-mitzi.html","url":"https://foodwishes.blogspot.com/2018/12/thumbprint-cookies-great-grandma-mitzi.html"},"image":"images/thumbprint_cookies_rnwno.jpg","servings":"","categories":[],"ingredients":[{"type":"item","text":"1 stick (1/2 cup) soft unsalted butter"},{"type":"item","text":"1/3 cup powdered sugar (not sifted)"},{"type":"item","text":"1 large egg yolk"},{"type":"item","text":"1 teaspoon vanilla extract"},{"type":"item","text":"1/4 teaspoon fine salt"},{"type":"item","text":"1 1/4 cups all-purpose flour (5 ounces by weight)"},{"type":"item","text":"1/2 cup fruit jam to fill centers"},{"type":"item","text":"325 F. for 15 minutes"}],"instructions":[{"type":"step","text":"Combine powdered sugar with a little milk or water, and mix until you have a consistency that will hold its shape when piped."}],"notes":[],"extra":""},{"id":"tuscan-heat-spice","title":"Tuscan Heat Spice","description":"","source":{"label":"","url":""},"image":"","servings":"","categories":[],"ingredients":[{"type":"item","text":"4 parts dried basil"},{"type":"item","text":"2 parts dried rosemary"},{"type":"item","text":"2 parts dried oregano"},{"type":"item","text":"2 parts garlic powder"},{"type":"item","text":"1 part cayenne pepper [7.5 k (hu)]"},{"type":"item","text":"1 part ground fennel"}],"instructions":[{"type":"step","text":"-"}],"notes":[],"extra":""},{"id":"vegetable-side","title":"vegetable side","description":"mixed veggies","source":{"label":"","url":""},"image":"","servings":"like 4?","categories":[],"ingredients":[{"type":"item","text":"halved fresh green beans, frozen corn, sliced red onion, julienned carrots, circled (cut) sweet peppers,"},{"type":"item","text":"lemon juice, salt, msg, pepper, parmesan cheese"},{"type":"item","text":"measurements (whatever looks right)"}],"instructions":[{"type":"step","text":"cut veggies (including\ncook green beans in oil a couple minutes before the rest\nadd rest of veggies\ncook until browning appears\nonce almost done, add parm and stir together"}],"notes":["green bean veggie side"],"extra":""},{"id":"vegetable-soup-with-lentils-seasonal-greens","title":"Vegetable Soup with Lentils \u0026 Seasonal Greens","description":"","source":{"label":"","url":""},"image":"images/vegetable_soup_with_lentils_amp_seasonal_1klt3.jpg","servings":"6","categories":[],"ingredients":[{"type":"item","text":"3 tablespoons olive oil"},{"type":"item","text":"1 small sweet onion, chopped"},{"type":"item","text":"4 cloves garlic, minced"},{"type":"item","text":"1 small leek, cleaned and sliced (white and light green parts only)"},{"type":"item","text":"2 stalks celery, sliced"},{"type":"item","text":"4 medium carrots, peeled and sliced"},{"type":"item","text":"1 cup butternut squash, chopped into 1/2-inch cubes (*see notes)"},{"type":"item","text":"3/4 cup French lentils, rinsed and drained"},{"type":"item","text":"4 cups 32-ounces no / low-salt vegetable stock or broth"},{"type":"item","text":"14 ounce can chopped canned tomatoes, low salt"},{"type":"item","text":"2 tablespoons tomato paste"},{"type":"item","text":"1 pound baby Bok Choy, greens cut as a chiffonade, white parts added with the carrots and other vegetables (*see notes)"},{"type":"item","text":"1/2 cup fresh parsley, chopped"},{"type":"item","text":"1 tablespoon fresh thyme, chopped"},{"type":"item","text":"sea salt and fresh ground pepper"},{"type":"item","text":"1/2 teaspoon smoked paprika"},{"type":"item","text":"1/4 teaspoon cayenne pepper"},{"type":"item","text":"Add any extra veggies : like mushrooms and green beans"}],"instructions":[{"type":"step","text":"Drizzle the olive oil in a large soup pot or dutch oven with a heavy bottom. Heat on medium until hot. Add the chopped onion and garlic and sauté until the onion is softened."},{"type":"step","text":"Before chopping, broil carrots and squash in oven in olive oil and paprika \u0026 cayenne."},{"type":"step","text":"Add the leek, celery, carrots, butternut squash, white portion of the Bok Choy and the lentils. Stir gently to coat all vegetables in the olive oil then add the vegetable stock and chopped tomatoes. Season with salt and pepper. Cover the pot with a lid and gently simmer for about 15 minutes."},{"type":"step","text":"Add the tomato paste, chopped greens, parsley and thyme. Heat until the greens are just tender."},{"type":"step","text":"Garnish with fresh parsley and black pepper. Serve with a hearty whole grain bread if desired."}],"notes":["The soup is easily adaptable by substituting rutabaga or turnips for the butternut squash.","Use seasonal greens such as Swiss Chard, Kale, Cabbage or Spinach in place of the Bok Choy if desired.","Be sure to cut vegetables about the same size so they will cook more evenly.","image of soup contains added yellow squash and zucchini + mushrooms**"],"extra":""},{"id":"wonton-soup","title":"Wonton soup","description":"","source":{"label":"","url":""},"image":"","servings":"","categories":[],"ingredients":[{"type":"item","text":"1 LB ground chicken"},{"type":"item","text":"6-10 cups chicken broth (used bouillon)"},{"type":"item","text":"1 pkg shiitake mushrooms"},{"type":"item","text":"1 bok choy"},{"type":"item","text":"1 bunch green onion"},{"type":"item","text":"2 ish TBS minced ginger"},{"type":"item","text":"2-4 cloves minced garlic"},{"type":"item","text":"1 TBS sherry vinegar"},{"type":"item","text":"1/4 tsp sesame oil"},{"type":"item","text":"1TBS soy sauce"},{"type":"item","text":"chili crisp oil"},{"type":"item","text":"kombu"},{"type":"item","text":"umami mushroom powder"},{"type":"item","text":"sesame seeds"},{"type":"item","text":"wonton wrappers"},{"type":"item","text":"2 block of tofu for topping"},{"type":"item","text":"marinated in hoisin and soy sauce (about 1-2 TBS each)"},{"type":"item","text":"homemade wontons: recipe is 1.5x"},{"type":"item","text":"375g / bread flour or half ap and bread flour"},{"type":"item","text":"~200 ml / water"},{"type":"item","text":"pinch salt"}],"instructions":[{"type":"step","text":"WONTONS\nmix ingredients\nrest/can rest in fridge up to whole day or so\nuse pasta roller to get thin enough\ncut into squares"},{"type":"step","text":"MARINATE TOFU OVERNIGHT FIRST!"},{"type":"step","text":"brown mushrooms"},{"type":"step","text":"mix ground chicken, 3 finely minced/chopped green onions, soy sauce, sesame oil, sesame seeds, some chili oil, garlic, ginger, sherry vinegar, little bit of broth,shake of umami mushroom powder"},{"type":"heading","text":"kombu stock:"},{"type":"step","text":"3 cup of cold water, 1 sheet of kombu. sit for 10 minutes.\nheat gently to 140F, turn off heat and set for 2 minutes, then extract kombu"},{"type":"heading","text":"stock:"},{"type":"step","text":"browned shitake @ 4\n(kombu stock made with 3cup water)\n1 tbsp of chili crisp"},{"type":"step","text":"add more water, add chopped whites of bok choy \u0026 rest of green onions\nsimmer for a while"},{"type":"step","text":"add green parts of bok choy"},{"type":"step","text":"wrap chicken mixture in wonton wrappers while broth simmers\nbring broth to boil and add wontons"},{"type":"step","text":"Cook 3 MINUTES"}],"notes":[],"extra":""},{"id":"yellow-halal-cart-rice-garlicky-lemony-one","title":"yellow halal cart rice (garlicky lemony one)","description":"","source":{"label":"","url":""},"image":"","servings":"","categories":[],"ingredients":[{"type":"item","text":"1 cup rice"},{"type":"item","text":"2 cups water"},{"type":"item","text":"1 TBS bouiilon"},{"type":"item","text":"1 tsp garlic powder or less"},{"type":"item","text":"1/2 Tbs ghee"},{"type":"item","text":"pinch smoked paprika"},{"type":"item","text":"dash of MSG"},{"type":"item","text":"lemon juice"}],"instructions":[{"type":"step","text":"mix water and spices and ghee, mix more when melted\nwhen done, squeeze lemon juice over rice and fluff together"}],"notes":[],"extra":""}];
